const DEFAULT_SHIPPING_RATES = {
  basePackagingKg: 0.5,        // base box/material weight added to every dry-goods order
  liveBasePackagingKg: 0.5,    // base box/oxygen-bag weight added to every live-fish order
  basePackagingByWeight: {},   // optional per-item-weight overrides; falls back to basePackagingKg
  liveBasePackagingByWeight: {}, // optional per-item-weight overrides; falls back to liveBasePackagingKg
  dryGoods: {
    "Up to 500g":{ TN:60,  SouthIndia:80,  CentralIndia:100, NorthIndia:120 },
    "500g-1kg":  { TN:80,  SouthIndia:100, CentralIndia:120, NorthIndia:150 },
    "1-2kg":     { TN:120, SouthIndia:150, CentralIndia:180, NorthIndia:220 },
    "2-5kg":     { TN:200, SouthIndia:250, CentralIndia:300, NorthIndia:400 },
    "5-10kg":    { TN:350, SouthIndia:450, CentralIndia:550, NorthIndia:700 },
  },
  liveFish: {
    // Same weight tiers as dry goods — live fish carry a premium due to oxygen packing & insulation
    "Up to 500g":{ TN:130, SouthIndia:180, CentralIndia:220, NorthIndia:300 },
    "500g-1kg":  { TN:170, SouthIndia:230, CentralIndia:290, NorthIndia:380 },
    "1-2kg":     { TN:250, SouthIndia:300, CentralIndia:400, NorthIndia:500 },
    "2-5kg":     { TN:400, SouthIndia:500, CentralIndia:650, NorthIndia:800 },
    "5-10kg":    { TN:600, SouthIndia:750, CentralIndia:900, NorthIndia:1200 },
  },
  // Thermacol (insulated) box material surcharge — added ONLY when a thermacol packing is chosen.
  // Charged by total live-parcel weight bracket, just like the courier rates above.
  thermacol: {
    "Up to 500g":40, "500g-1kg":70, "1-2kg":110, "2-5kg":200, "5-10kg":350,
  },
  // Standard packing (carton box, or courier bag for small/dry items) — base material charge.
  // Charged by total parcel-weight bracket, just like the courier & thermacol rates above.
  carton: {
    "Up to 500g":20, "500g-1kg":30, "1-2kg":50, "2-5kg":80, "5-10kg":120,
  },
  // ⚡ Speed-courier surcharge — by total parcel-weight bracket × zone (3 speed zones).
  speedCourier: {
    "Up to 500g":{ TN:80,  SouthIndia:120, CentralNorth:180 },
    "500g-1kg":  { TN:120, SouthIndia:180, CentralNorth:250 },
    "1-2kg":     { TN:180, SouthIndia:250, CentralNorth:350 },
    "2-5kg":     { TN:280, SouthIndia:400, CentralNorth:550 },
    "5-10kg":    { TN:450, SouthIndia:650, CentralNorth:850 },
  },
};
/* Canonical weight tiers shared by dry goods AND live fish. */
const SHIP_TIERS = ["Up to 500g","500g-1kg","1-2kg","2-5kg","5-10kg"];
/* Migrate any legacy shipping brackets (e.g. old Small/Medium/Large live-fish keys) to the
   weight tiers above, preserving prices for any tier that already matches. */
function normalizeShippingRates(rates){
  if(!rates || typeof rates!=="object") return rates;
  const fixType=(obj,def)=>{
    const keys=Object.keys(obj||{});
    const clean = keys.length===SHIP_TIERS.length && SHIP_TIERS.every(t=>keys.includes(t));
    if(clean) return obj; // already weight-based
    const out={};
    SHIP_TIERS.forEach(t=>{ out[t]={...def[t], ...((obj&&obj[t])?obj[t]:{})}; });
    return out;
  };
  return { ...rates,
    dryGoods: fixType(rates.dryGoods, DEFAULT_SHIPPING_RATES.dryGoods),
    liveFish: fixType(rates.liveFish, DEFAULT_SHIPPING_RATES.liveFish) };
}
/* Normalize a whole settings object loaded from storage (currently just shipping rates). */
/* ═══════════════════ COUPONS ═══════════════════ */
/* One list drives all three things that used to be configured separately: the coupon codes,
   the first-order welcome offer, and the seasonal/festival banner. A coupon decides for
   itself where it appears (`showOnWelcome` / `showAtCheckout`) and who it is for
   (`firstOrderOnly`), which is what makes "the welcome banner never shows on my own account"
   a setting rather than a rule baked into the code: an owner who wants everyone to see a
   festival offer just leaves firstOrderOnly off. */
function normalizeCoupon(c){
  if(!c||typeof c!=="object") return null;
  const type=["flat","percent","coins"].includes(c.type)?c.type:"flat";
  return {
    /* Derived, never random. migrateCoupons runs on every render, so a random fallback handed
       the same coupon a new id each time — and React, keying the banners on it, threw the card
       away and built a fresh one every render. That was the blinking welcome banner: not an
       animation bug, an identity one. Anything without a stored id is identified by what it
       is instead. */
    id: c.id||("cp-"+String(c.code||c.name||"offer").trim().toUpperCase().replace(/[^A-Z0-9]+/g,"-").slice(0,32)),
    code: String(c.code||"").trim().toUpperCase(),
    name: String(c.name||"").trim(),          // "Welcome Offer", "Diwali Sale", …
    type,                                     // flat ₹ | percent % | coins (reward, not a discount)
    value: Number(c.value ?? c.discount ?? 0) || 0,
    maxDiscount: Number(c.maxDiscount||0)||0, // 0 = uncapped. Only meaningful for percent.
    minOrder: Number(c.minOrder||0)||0,
    firstOrderOnly: !!c.firstOrderOnly,
    active: c.active!==false,
    secret: !!c.secret,                       // never listed anywhere; must be typed in
    endsAt: c.endsAt||"",                     // datetime-local; "" = no expiry
    showAtCheckout: c.showAtCheckout!==false,
    showOnWelcome: !!c.showOnWelcome,
    emoji: c.emoji||"🎉",
    bg: c.bg||"#7c3aed",
  };
}
/* Legacy settings carried the same information in three shapes. Fold them into the one list
   on read, so an owner who has not touched the new screen keeps exactly what they had. */
function migrateCoupons(s){
  const list=(Array.isArray(s.coupons)?s.coupons:[]).map(normalizeCoupon).filter(c=>c&&c.code);
  const have=code=>list.some(c=>c.code===String(code||"").toUpperCase());
  /* The legacy welcome fields describe THE welcome offer. Matching only on code meant an owner
     who built a new one on the coupons screen — a 10% welcome, say, under a new code — kept the
     old ₹100 one as well, and the home page showed two welcome banners saying different things.
     If the list already defines a first-order offer for the welcome screen, that IS the welcome
     offer and the legacy fields are the same thing in older clothes. */
  const haveWelcome=list.some(c=>c.firstOrderOnly&&c.showOnWelcome);
  if(s.welcomeCouponEnabled!==false && s.welcomeCoupon && !have(s.welcomeCoupon) && !haveWelcome){
    list.push(normalizeCoupon({
      code:s.welcomeCoupon, name:"Welcome Offer", type:"flat",
      value:Number(s.welcomeCouponAmount||100), minOrder:Number(s.welcomeCouponMinOrder||999),
      firstOrderOnly:true, active:true, showOnWelcome:true, showAtCheckout:true, emoji:"🎉", bg:"#ff5a40",
    }));
  }
  const fb=s.festivalBanner||{};
  if(fb.active && fb.text && !list.some(c=>c.name===fb.text)){
    // The old festival banner was text-only — no code. It survives as an announcement-style
    // entry: shown on the welcome screen, never offered at checkout, nothing to redeem.
    list.push(normalizeCoupon({
      code:"", name:fb.text, type:"flat", value:0, active:true,
      showOnWelcome:true, showAtCheckout:false, endsAt:fb.endsAt||"", emoji:fb.emoji||"🎉", bg:fb.bg||"#7c3aed",
    }));
  }
  return list;
}
function couponExpired(c,now=Date.now()){
  if(!c||!c.endsAt) return false;
  const t=new Date(c.endsAt).getTime();
  return !isNaN(t) && t<now;
}
/* Has this shopper already placed an order? Cancelled ones don't count against them. */
function hasPriorOrder(orders){ return (orders||[]).some(o=>o&&o.status!=="Cancelled"); }
/* Every coupon the shopper could actually use right now. `where` filters by surface. */
function usableCoupons(settings,orders,where){
  const now=Date.now();
  return migrateCoupons(settings||{}).filter(c=>
    c.active && !couponExpired(c,now) &&
    (!c.firstOrderOnly || !hasPriorOrder(orders)) &&
    // A secret code is never advertised on any surface — the whole point is that it has to
    // be typed in by someone who was told it.
    (where==="welcome" ? (c.showOnWelcome && !c.secret) : where==="checkout" ? (c.showAtCheckout && !c.secret && c.code) : true)
  );
}
/* What a coupon is worth on this subtotal: a rupee discount, or reward coins. Percent
   coupons honour their own ceiling first — the global caps are applied later, over the
   whole order, in the checkout total. */
function couponBenefit(c,subtotal){
  if(!c) return {discount:0,coins:0};
  if(c.type==="coins") return {discount:0,coins:Math.max(0,Math.round(c.value))};
  let d = c.type==="percent" ? Math.round((subtotal||0)*c.value/100) : Number(c.value||0);
  if(c.maxDiscount>0) d=Math.min(d,c.maxDiscount);
  return {discount:Math.max(0,Math.min(d,subtotal||0)),coins:0};
}
/* How many coins one order may absorb. 0 means no cap — matching the discount-cap field
   beside it in Settings — which `walletMaxCoins||100` could never express, since 0 fell
   through to the default and quietly reimposed a 100-coin ceiling on a store that had
   deliberately removed it. An unset value still defaults to 100. */
function walletCoinCap(settings){
  const v=settings&&settings.walletMaxCoins;
  if(v===0||v==="0") return Infinity;
  return Number(v)||100;
}
/* The terms shipped with a line saying the store is "not registered under GST" and that bills
   would become Tax Invoices "once we register". That was true when it was written. It stopped
   being true the moment a GSTIN was saved: checkout charges GST, the invoice is already issued
   as a Tax Invoice with HSN and a tax split — and the terms still told customers no GST was
   charged. Terms that contradict the bill are the one kind of stale text worth code to fix.

   It is not simply deleted from the default, because the default is also what a store with no
   GSTIN shows, and there the sentence is correct and legally useful. So it is rewritten only
   when a GSTIN is actually configured. The saved copy in Firebase — not the default — is what
   the live site renders, which is why this runs on the way through normalizeSettings rather
   than being a one-line edit to the constant: every reader is fed through here, so the stale
   sentence stops being displayed everywhere at once, without the owner editing anything.
   Idempotent: once rewritten the pattern no longer matches. */
const GST_UNREG_RE=/\s*We are currently a small enterprise not registered under GST[^.]*\.(?:[^.]*at which point your bill will be issued as a GST Tax Invoice\.)?/i;
/* Deliberately not "your bill is a Tax Invoice, prices include GST". GST is claimed per product,
   so a basket of goods we do not claim GST on carries no tax at all and is billed as a BILL OF
   SUPPLY — which is most live-fish orders. Wording that promised a Tax Invoice on every order
   would be a different false statement from the one being removed. */
const GST_REG_TERM=" We are registered under GST (our GSTIN is shown on your bill). Where GST applies to an item, the price shown is inclusive of it and your bill is issued as a GST Tax Invoice; items we do not charge GST on are billed as a Bill of Supply.";
const RETURN_POLICY_V2="Live fish and plants are final sale after safe delivery. Dead-on-Arrival claims require one continuous unboxing video sent on WhatsApp within 2 hours of delivery; the claim must be raised within 24 hours. Approved DOA claims cover the affected fish value only, as either a refund or reward coins; shipping is not refundable. Unused accessories and equipment in original, undamaged packaging may be returned within 3 days of delivery. Return shipping is paid by the customer unless the item arrived damaged or incorrect. Returned dry-goods refunds are issued within 5–7 working days after inspection. Customers cannot cancel after payment confirmation, and store cancellation is unavailable after shipment.";
function applyGstTerms(text,gstin){
  const t=String(text||"");
  if(!String(gstin||"").trim()) return t;          // genuinely unregistered — the notice stands
  if(!GST_UNREG_RE.test(t)) return t;
  return t.replace(GST_UNREG_RE,GST_REG_TERM).replace(/\s{2,}/g," ").trim();
}
function normalizeSettings(s){
  if(!s) return s;
  let fixed = s.termsPolicy ? {...s, termsPolicy: applyGstTerms(s.termsPolicy, s.gstin)} : s;
  const privacy=String(fixed.privacyPolicy||"");
  if(/payment reference ID and screenshot you submit so we can verify your payment/i.test(privacy)){
    fixed={...fixed,privacyPolicy:privacy
      .replace(/plus the payment reference ID and screenshot you submit so we can verify your payment\./i,"plus the verified payment status returned by our payment gateway.")
      .replace(/Payments are processed through your own UPI app or our secure payment gateway;/i,"Payments are processed securely by our PCI-compliant payment gateway (PhonePe or Razorpay);")};
  }
  /* Cashfree stopped serving this store, so a saved privacy policy naming it as the payment
     processor is now simply untrue. Unlike the live-fish policy text — which is temporarily
     inapplicable and must come back verbatim — this wording is wrong and should be corrected
     in place, so it deliberately runs here in normalizeSettings and is saved back. */
  if(/Cashfree/i.test(String(fixed.privacyPolicy||""))){
    fixed={...fixed,privacyPolicy:String(fixed.privacyPolicy)
      .replace(/the verified payment status returned by Cashfree/gi,"the verified payment status returned by our payment gateway")
      .replace(/Payments are processed securely by Cashfree;/gi,"Payments are processed securely by our PCI-compliant payment gateway (PhonePe or Razorpay);")
      .replace(/\bCashfree\b/g,"our payment gateway")};
  }
  if(/vote for the same tank more than once per day/i.test(String(fixed.tankRewardRules||""))){
    fixed={...fixed,tankRewardRules:String(fixed.tankRewardRules).replace(/vote for the same tank more than once per day/gi,"vote more than once for the same tank image")};
  }
  if(/NO RETURNS & NO REPLACEMENTS once live fish/i.test(String(fixed.returnPolicy||""))){
    fixed={...fixed,returnPolicy:RETURN_POLICY_V2};
  }
  if(fixed.shippingRates) return {...fixed, shippingRates: normalizeShippingRates(fixed.shippingRates)};
  return fixed;
}
const ZONE_LABELS = { TN:"Tamil Nadu", SouthIndia:"South India", CentralIndia:"Central India", NorthIndia:"North India" };
const ZONE_KEYS   = Object.keys(ZONE_LABELS);
function pincodeToZone(pin){
  const p=parseInt((pin||"").replace(/\D/g,""),10);
  if(!p||isNaN(p))return null;
  if(p>=600000&&p<=643999)return "TN";
  if((p>=500000&&p<=535999)||(p>=560000&&p<=599999)||(p>=670000&&p<=695999)||(p>=605000&&p<=607999))return "SouthIndia";
  if((p>=400000&&p<=445999)||(p>=450000&&p<=497999)||(p>=360000&&p<=396999)||(p>=403000&&p<=403999))return "CentralIndia";
  return "NorthIndia";
}
/* All Indian GST state / UT codes → official name (used for the invoice "Place of Supply"). */
const GST_STATES={
  "01":"JAMMU AND KASHMIR","02":"HIMACHAL PRADESH","03":"PUNJAB","04":"CHANDIGARH",
  "05":"UTTARAKHAND","06":"HARYANA","07":"DELHI","08":"RAJASTHAN","09":"UTTAR PRADESH",
  "10":"BIHAR","11":"SIKKIM","12":"ARUNACHAL PRADESH","13":"NAGALAND","14":"MANIPUR",
  "15":"MIZORAM","16":"TRIPURA","17":"MEGHALAYA","18":"ASSAM","19":"WEST BENGAL",
  "20":"JHARKHAND","21":"ODISHA","22":"CHHATTISGARH","23":"MADHYA PRADESH","24":"GUJARAT",
  "26":"DADRA & NAGAR HAVELI AND DAMAN & DIU","27":"MAHARASHTRA","29":"KARNATAKA",
  "30":"GOA","31":"LAKSHADWEEP","32":"KERALA","33":"TAMIL NADU","34":"PUDUCHERRY",
  "35":"ANDAMAN & NICOBAR ISLANDS","36":"TELANGANA","37":"ANDHRA PRADESH","38":"LADAKH"
};
/* Derive the buyer's state (GST code + name) from a 6-digit Indian PIN.
   For a Tamil-Nadu seller the only distinction that changes the tax is TN (33)
   vs. everything-else, and the 600xxx–643xxx TN block is unambiguous — so even
   where two neighbouring states share a PIN band the tax charged is unaffected
   (any non-TN PIN → inter-state → IGST). Returns null if the PIN is unknown. */
function pincodeToState(pin){
  const p=parseInt(String(pin||"").replace(/\D/g,""),10);
  if(!p||isNaN(p)||p<100000||p>999999) return null;
  const pre=Math.floor(p/1000); // first 3 digits
  let code="";
  // Puducherry (UT 34) sits inside Tamil Nadu/Kerala/AP postal ranges — its
  // scattered pockets are inter-state (IGST) for a TN seller, so match them by
  // exact PIN first: Pondicherry town, Karaikal, Yanam and Mahe.
  if((p>=605001&&p<=605014)||(p>=609602&&p<=609609)||p===533464||p===673310||p===673311) code="34";
  // Pockets that sit inside a larger neighbouring band — checked first.
  else if(pre===160) code="04";         // Chandigarh (inside Punjab)
  else if(pre===403) code="30";         // Goa (inside Maharashtra 40x)
  else if(pre===737) code="11";         // Sikkim (inside West Bengal 7xx)
  else if(pre===682) code="32";         // Kochi circle → Kerala
  else if(pre===795) code="14";         // Manipur
  else if(pre===796) code="15";         // Mizoram
  else if(pre===799) code="16";         // Tripura
  else if(pre===194) code="38";         // Ladakh (Leh/Kargil)
  else if(pre===110) code="07";         // Delhi
  else if(pre>=121&&pre<=136) code="06"; // Haryana
  else if(pre>=140&&pre<=160) code="03"; // Punjab
  else if(pre>=171&&pre<=177) code="02"; // Himachal Pradesh
  else if(pre>=180&&pre<=193) code="01"; // Jammu & Kashmir
  else if(pre>=246&&pre<=263) code="05"; // Uttarakhand (inside UP band)
  else if(pre>=201&&pre<=285) code="09"; // Uttar Pradesh
  else if(pre>=301&&pre<=345) code="08"; // Rajasthan
  else if(pre>=360&&pre<=396) code="24"; // Gujarat
  else if(pre>=400&&pre<=445) code="27"; // Maharashtra
  else if(pre>=450&&pre<=488) code="23"; // Madhya Pradesh
  else if(pre>=490&&pre<=497) code="22"; // Chhattisgarh
  else if(pre>=500&&pre<=509) code="36"; // Telangana
  else if(pre>=510&&pre<=539) code="37"; // Andhra Pradesh
  else if(pre>=560&&pre<=591) code="29"; // Karnataka
  else if(pre>=600&&pre<=643) code="33"; // TAMIL NADU
  else if(pre>=670&&pre<=695) code="32"; // Kerala
  else if(pre>=700&&pre<=743) code="19"; // West Bengal
  else if(pre>=750&&pre<=770) code="21"; // Odisha
  else if(pre>=781&&pre<=788) code="18"; // Assam
  else if(pre>=790&&pre<=792) code="12"; // Arunachal Pradesh
  else if(pre>=793&&pre<=794) code="17"; // Meghalaya
  else if(pre>=797&&pre<=798) code="13"; // Nagaland
  else if(pre>=800&&pre<=813) code="10"; // Bihar
  else if(pre>=814&&pre<=835) code="20"; // Jharkhand
  else if(pre>=836&&pre<=855) code="10"; // Bihar (Purnia/Katihar belt)
  return code?{code,name:GST_STATES[code]||""}:null;
}
/* Parse a GSTIN → {valid, stateCode, stateName}. Format: 2-digit state + 10-char PAN + entity + 'Z' + checksum. */
function parseGstin(g){
  const v=String(g||"").trim().toUpperCase();
  const valid=/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]$/.test(v);
  const stateCode=v.slice(0,2);
  return {valid, stateCode, stateName:GST_STATES[stateCode]||""};
}
/* Live Arrival Guarantee opt-in fee varies by destination: Inside TN / South India / Rest of India (North).
   Central India + anything unknown is grouped under "North" (rest of India). Falls back to the flat price. */
function liveGuaranteeZoneKey(zone){
  if(zone==="TN") return "TN";
  if(zone==="SouthIndia") return "South";
  return "North"; // NorthIndia + CentralIndia + unknown
}
function liveGuaranteeZoneLabel(zone){
  const k=liveGuaranteeZoneKey(zone);
  return k==="TN"?"Inside Tamil Nadu":k==="South"?"South India":"Rest of India";
}
function liveGuaranteePriceForZone(zone, settings){
  const flat=Number(settings.liveGuaranteePrice||150);
  const map={ TN:settings.liveGuaranteePriceTN, South:settings.liveGuaranteePriceSouth, North:settings.liveGuaranteePriceNorth };
  const v=map[liveGuaranteeZoneKey(zone)];
  return (v===0||v) ? Number(v) : flat;
}
/* Lowest of the three zone prices — used to show a "from ₹X" hint before an address is entered. */
function liveGuaranteeMinPrice(settings){
  const vals=["liveGuaranteePriceTN","liveGuaranteePriceSouth","liveGuaranteePriceNorth"]
    .map(k=>settings[k]).filter(v=>v===0||v).map(Number);
  if(!vals.length) return Number(settings.liveGuaranteePrice||150);
  return Math.min(...vals);
}
/* ⚡ Speed-courier add-on resolved by destination zone: Tamil Nadu / South India / Central & North.
   CentralIndia + NorthIndia + unknown share the "CentralNorth" rate. Falls back to the flat price. */
function speedCourierZoneKey(zone){
  if(zone==="TN") return "TN";
  if(zone==="SouthIndia") return "SouthIndia";
  return "CentralNorth"; // CentralIndia + NorthIndia + unknown
}
function speedCourierZoneLabel(zone){
  const k=speedCourierZoneKey(zone);
  return k==="TN"?"Tamil Nadu":k==="SouthIndia"?"South India":"Central & North India";
}
function speedCourierForZone(zone, settings, cart){
  const zk=speedCourierZoneKey(zone);
  const sr=(settings&&settings.shippingRates)||{};
  const tbl=sr.speedCourier;
  if(tbl){
    const bracket=parcelWeightBracket(cart, sr);
    const row=tbl[bracket]||tbl["Up to 500g"]||{};
    const v=row[zk];
    if(v===0||v) return Number(v);
  }
  // Legacy flat per-zone (used until the weight chart is filled in Settings)
  const legacy=settings.speedCourierRates;
  if(legacy && (legacy[zk]===0||legacy[zk])) return Number(legacy[zk]);
  return Number(settings.specialDeliveryPrice||0);
}
/* Total parcel-weight bracket for a whole cart (fish + dry + base packing weight). */
function parcelWeightBracket(cart, r){
  r=r||DEFAULT_SHIPPING_RATES;
  const fish=(cart||[]).filter(i=>i.category==="Live Fish");
  const dry=(cart||[]).filter(i=>i.category!=="Live Fish");
  const fishWt=fish.reduce((s,i)=>s+(Number(i.variantPackagingWeight!=null?i.variantPackagingWeight:i.packagingWeight)||0.2)*i.qty,0);
  const dryWt=dry.reduce((s,i)=>s+(Number(i.variantPackagingWeight!=null?i.variantPackagingWeight:i.packagingWeight)||0.1)*i.qty,0);
  const base=basePackagingWeight(r,fish.length?"live":"dry",fishWt+dryWt);
  return getWeightBracket(fishWt+dryWt+base);
}
/* Live fish uses the same 5-tier weight brackets as dry goods so rates are directly comparable */
function getLiveFishWeightBracket(kg){
  if(kg<=0.5)return "Up to 500g";
  if(kg<=1)  return "500g-1kg";
  if(kg<=2)  return "1-2kg";
  if(kg<=5)  return "2-5kg";
  return "5-10kg";
}
function getWeightBracket(kg){
  if(kg<=0.5)return "Up to 500g";
  if(kg<=1)  return "500g-1kg";
  if(kg<=2)  return "1-2kg";
  if(kg<=5)  return "2-5kg";
  return "5-10kg";
}
function basePackagingWeight(r,kind,itemKg){
  r=r||DEFAULT_SHIPPING_RATES;
  const live=kind==="live";
  const map=(live?r.liveBasePackagingByWeight:r.basePackagingByWeight)||{};
  const value=map[getWeightBracket(Math.max(0,Number(itemKg)||0))];
  if(value===0||value) return Math.max(0,Number(value)||0);
  const legacy=live
    ? (r.liveBasePackagingKg!=null?r.liveBasePackagingKg:(r.basePackagingKg??0.5))
    : (r.basePackagingKg??0.5);
  return Math.max(0,Number(legacy)||0);
}
/* ─────────── Live-fish packing options (customer chooses one at checkout) ───────────
   Two independent layers fold into 4 named options:
     • box     : carton | thermacol  (thermacol = insulated, adds a weight-based material charge)
     • courier : normal | special    (special = priority/fast & safe, adds the flat Special fee)
   rank = protection level (1 = lightest → 4 = safest). The Live Arrival Guarantee applies when
   the customer picks the admin-recommended packing (per product) OR a higher-rank one. */
const PACKING_OPTIONS = [
  { key:"carton_normal",      label:"Standard Packing · Normal Courier",   box:"carton",    courier:"normal",  rank:1, blurb:"Economical — carton box or courier bag, fine for nearby locations." },
  { key:"carton_special",     label:"Standard Packing · Premium Courier",  box:"carton",    courier:"special", rank:2, blurb:"Faster delivery with safe handling by the courier." },
  { key:"thermacol_standard", label:"Thermacol Box · Standard Courier", box:"thermacol", courier:"normal",  rank:3, blurb:"Insulated box — for premium fish, local transport." },
  { key:"thermacol_special",  label:"Thermacol Box · Premium Courier",  box:"thermacol", courier:"special", rank:4, blurb:"Best protection — premium fish & long-distance travel." },
];
const PACKING_BY_KEY = PACKING_OPTIONS.reduce((m,o)=>{m[o.key]=o;return m;},{});
function packingOpt(key){ return PACKING_BY_KEY[key] || PACKING_BY_KEY.carton_special; }
function packingLabel(key){ return packingOpt(key).label; }
/* Recommended packing for a cart = the safest (highest-rank) per-product suggestion among its live fish. */
function suggestedPackingForCart(cart, zone){
  // Admin sets a recommended packing per location on each live product: Inside TN vs Others (outside TN).
  const inTN = zone==="TN";
  let best=null;
  (cart||[]).forEach(i=>{
    if(i.category!=="Live Fish") return;
    const byLoc = inTN ? i.suggestedPackingTN : i.suggestedPackingOther;
    const o=PACKING_BY_KEY[byLoc||i.suggestedPacking||"carton_special"];
    if(o && (!best || o.rank>best.rank)) best=o;
  });
  return best ? best.key : "carton_special";
}
/* Thermacol material surcharge for a given parcel-weight bracket. */
function thermacolCharge(bracket, settings){
  const r=(settings&&settings.shippingRates)||DEFAULT_SHIPPING_RATES;
  return Number((r.thermacol||DEFAULT_SHIPPING_RATES.thermacol)[bracket]||0);
}
/* Standard-packing (carton box / courier bag) charge for a given parcel-weight bracket. */
function cartonCharge(bracket, settings){
  const r=(settings&&settings.shippingRates)||DEFAULT_SHIPPING_RATES;
  return Number((r.carton||DEFAULT_SHIPPING_RATES.carton)[bracket]||0);
}
/* Thermacol (packaging) portion of a cart's shipping fee — 0 unless a thermacol packing is chosen.
   Used to keep the shipping-reward calc to courier charges only (packaging is never rewardable). */
function thermacolFeeFor(cart, packingKey, settings){
  const pk=packingOpt(packingKey);
  if(pk.box!=="thermacol") return 0;
  const fishItems=(cart||[]).filter(i=>i.category==="Live Fish");
  if(!fishItems.length) return 0;
  const r=settings.shippingRates||DEFAULT_SHIPPING_RATES;
  const fishWt=fishItems.reduce((s,i)=>s+(Number(i.variantPackagingWeight!=null?i.variantPackagingWeight:i.packagingWeight)||0.2)*i.qty,0);
  const liveBase=basePackagingWeight(r,"live",fishWt);
  return thermacolCharge(getLiveFishWeightBracket(fishWt+liveBase), settings);
}
/* Zones live fish are NOT delivered to when the admin restriction is on. */
const LIVE_FISH_BLOCKED_ZONES = ["CentralIndia","NorthIndia"];
function liveFishBlockedForZone(zone, settings){
  if(settings && settings.liveFishRestrictNCIndia===false) return false;
  return LIVE_FISH_BLOCKED_ZONES.includes(zone);
}
/* The customer's oldest un-redeemed shipping-reward code (reward stacks on top of coupons). */
function unredeemedShippingReward(orders){
  const list=orders||[];
  const redeemed=new Set(list.map(o=>(o.rewardRedeemedCode||"").toLowerCase()).filter(Boolean));
  const sorted=[...list].sort((a,b)=>(a.placedAt||"").localeCompare(b.placedAt||"")); // oldest first
  for(const o of sorted){
    const rw=o.shippingReward;
    if(rw&&rw.code&&!redeemed.has(rw.code.toLowerCase())){
      return {code:rw.code, amount:Number(rw.amount)||0, fromOrderId:o.id};
    }
  }
  return null;
}
/* Itemised shipping cost so checkout can show a breakup:
   { courier, thermacol, carton, special, total, freeShip }. All in ₹. */
function shippingBreakdown(cart, zone, opts, settings){
  if(!zone) return null;
  const r = settings.shippingRates || DEFAULT_SHIPPING_RATES;
  // opts: object {packing, special} (new) OR a bare boolean isSpecial (legacy)
  const o = (opts && typeof opts==="object") ? opts : { special: !!opts };
  const packing = packingOpt(o.packing);
  const dryItems  = cart.filter(i=>i.category!=="Live Fish");
  const fishItems = cart.filter(i=>i.category==="Live Fish");
  // Special-courier surcharge applies when the fish packing uses a special courier, or (dry-only) the special box is ticked
  const wantSpecial = fishItems.length ? (packing.courier==="special") : !!o.special;
  // Free-delivery threshold — waives courier + packaging (a special courier still bypasses free delivery)
  const threshold = Number(settings.freeDeliveryThreshold||0);
  const subtotal = cart.reduce((s,i)=>s+i.price*i.qty, 0);
  const freeShip = threshold > 0 && subtotal >= threshold && !wantSpecial;
  let courier = 0, thermacol = 0, carton = 0, special = 0;
  if(fishItems.length){
    // Weight-based live fish shipping (uses variantPackagingWeight if set, else product packagingWeight)
    const fishWt = fishItems.reduce((s,i)=>{
      const wt = Number(i.variantPackagingWeight != null ? i.variantPackagingWeight : i.packagingWeight) || 0.2;
      return s + wt * i.qty;
    },0);
    const liveBase = basePackagingWeight(r,"live",fishWt);
    const bracket = getLiveFishWeightBracket(fishWt + liveBase);
    courier += (r.liveFish?.[bracket]?.[zone]||0);
    if(packing.box==="thermacol") thermacol += thermacolCharge(bracket, settings);
    else if(packing.box==="carton") carton += cartonCharge(bracket, settings);
  }
  if(dryItems.length){
    // Per-option weight wins when the product has options (a 1kg feed pack vs a 100g one),
    // falling back to the product's own packing weight.
    const itemWt = dryItems.reduce((s,i)=>s+((Number(i.variantPackagingWeight!=null?i.variantPackagingWeight:i.packagingWeight)||0.1)*i.qty),0);
    const bracket = getWeightBracket(itemWt+basePackagingWeight(r,"dry",itemWt));
    courier += (r.dryGoods?.[bracket]?.[zone]||0);
    // Standard (base) packing — carton box / courier bag. Only when no live fish already drives the box.
    if(!fishItems.length) carton += cartonCharge(bracket, settings);
  }
  if(wantSpecial) special += speedCourierForZone(zone, settings, cart);
  if(freeShip){ courier = 0; thermacol = 0; carton = 0; }
  return { courier, thermacol, carton, special, total: courier+thermacol+carton+special, freeShip };
}
function calcShipping(cart, zone, opts, settings){
  const b = shippingBreakdown(cart, zone, opts, settings);
  return b ? b.total : null;
}
/* Live delivery estimate. Admin sets etaDays (+ etaSetAt = the day it was given);
   we recompute a real target date and a day-by-day countdown on every render so it
   counts down on its own as the days pass. Returns null when no ETA is set. */
function etaInfo(o){
  if(!o||o.etaDays===""||o.etaDays==null) return null;
  const days=Number(o.etaDays); if(!isFinite(days)) return null;
  const anchor=o.etaSetAt||o.updatedAt||o.placedAt;
  const a=anchor?new Date(anchor):new Date();
  const start=new Date(a.getFullYear(),a.getMonth(),a.getDate());
  const target=new Date(start.getTime()+days*864e5);
  const now=new Date(); const t0=new Date(now.getFullYear(),now.getMonth(),now.getDate());
  const daysLeft=Math.round((target.getTime()-t0.getTime())/864e5);
  const dateLabel=target.toLocaleDateString("en-IN",{weekday:"short",day:"2-digit",month:"short"});
  return {target,daysLeft,dateLabel};
}
/* Open a courier's tracking page for an order. If the saved track URL contains a
   {awb}/{tracking}/{number} placeholder it's filled with the consignment number;
   otherwise the number is copied to the clipboard so the customer can paste it. */
function trackParcelUrl(o){
  let url=(o&&o.courierTrackUrl)||"";
  const num=((o&&o.trackingNumber)||"").trim();
  if(url && /\{(awb|tracking|number|id|consignment)\}/i.test(url)){
    url=url.replace(/\{(awb|tracking|number|id|consignment)\}/ig, encodeURIComponent(num));
  }
  return url;
}
function trackParcel(o){
  const url=trackParcelUrl(o);
  if(!url) return;
  const num=((o&&o.trackingNumber)||"").trim();
  if(num && !/\{(awb|tracking|number|id|consignment)\}/i.test(o.courierTrackUrl||"")){
    try{ navigator.clipboard.writeText(num); }catch(e){}
  }
  try{ window.open(url,"_blank","noopener"); }catch(e){ try{ location.href=url; }catch(_){} }
}
function validateCoupon(code, settings, userOrders, cartTotal){
  if(!code||!code.trim()) return {ok:false, msg:""};
  const want=code.trim().toUpperCase();
  const c = migrateCoupons(settings||{}).find(x=>x.code&&x.code===want&&x.active);
  if(!c) return {ok:false, msg:"Invalid coupon code"};
  if(couponExpired(c)) return {ok:false, msg:"This coupon has expired"};
  if(c.firstOrderOnly && hasPriorOrder(userOrders)) return {ok:false, msg:"This code is for first orders only"};
  if(c.minOrder>0 && (cartTotal||0) < c.minOrder){
    return {ok:false, msg:`Minimum cart value ₹${c.minOrder} required for this coupon (add ₹${c.minOrder-(cartTotal||0)} more)`};
  }
  /* A cancelled order used nothing. hasPriorOrder above already ignores cancelled orders when
     deciding whether someone is still a first-time buyer; this check did not, so a customer
     whose order was cancelled — by them or by the store — could never use that code again. */
  const already = (userOrders||[]).some(o=>o&&o.status!=="Cancelled"&&o.coupon&&String(o.coupon).toUpperCase()===want);
  if(already) return {ok:false, msg:"Coupon already used on this account"};
  return {ok:true, coupon:c};
}
/* The ceiling on everything combined. Returns the trimmed amounts plus whether a cap bit, so
   checkout can say so instead of silently handing back less than the codes promised.
   Loyalty is trimmed first (the shopper keeps unspent coins), then referral, then coupon. */
function applyDiscountCaps({coupon=0,referral=0,loyalty=0,subtotal=0,settings={},loyaltyVal=1}){
  const pct=Number(settings.maxDiscountPct||0);
  const rs=Number(settings.maxDiscountRs||0);
  const caps=[pct>0?Math.floor(subtotal*pct/100):Infinity, rs>0?rs:Infinity];
  const cap=Math.min(...caps);
  let over=(coupon+referral+loyalty)-cap;
  if(!(over>0)) return {coupon,referral,loyalty,capped:false,coinsUsed:loyalty>0?Math.ceil(loyalty/loyaltyVal):0};
  const dLoy=Math.min(loyalty,over); loyalty-=dLoy; over-=dLoy;
  const dRef=Math.min(referral,over); referral-=dRef; over-=dRef;
  const dCoup=Math.min(coupon,over); coupon-=dCoup; over-=dCoup;
  return {coupon,referral,loyalty,capped:true,coinsUsed:loyalty>0?Math.ceil(loyalty/loyaltyVal):0};
}
/* The nearest coupon threshold, either just missed or just cleared.
   Returns {need, off, code, minOrder, unlocked} — "add ₹need more to get <off>", or the
   unlocked banner once they are over the line — or null when there is nothing to chase.

   Three things were wrong with this before, which is why it was never wired to anything:
   it read `c.discount` while normalizeCoupon writes `value`, so every nudge said "undefined
   off"; it read settings.coupons raw, so the Welcome Offer — the one coupon most stores have,
   synthesised by migrateCoupons from the legacy fields — was invisible to it; and it went
   silent the moment a threshold was cleared, exactly when telling someone they have earned
   something is worth most. */
function nextDiscountNudge(cartTotal, settings, orders){
  const t=Number(cartTotal)||0;
  /* usableCoupons already knows about expiry, secrecy and whether a first-order coupon still
     applies to this shopper — so a returning customer is never dangled a welcome offer they
     cannot have. */
  const usable=usableCoupons(settings,orders,"checkout")
    .filter(c=>c.type!=="coins" && c.value>0 && c.minOrder>0);
  if(!usable.length) return null;
  const offOf=(c)=>c.type==="percent"
    ? `${c.value}% off${c.maxDiscount>0?` (up to ₹${c.maxDiscount})`:""}`
    : `₹${c.value} off`;
  // Nearest threshold still ahead; failing that, the best one already cleared.
  const ahead=usable.filter(c=>t<c.minOrder).sort((a,b)=>a.minOrder-b.minOrder)[0];
  if(ahead) return { need:Math.max(0,Math.ceil(ahead.minOrder-t)), off:offOf(ahead), code:ahead.code, minOrder:ahead.minOrder, unlocked:false };
  const won=usable.sort((a,b)=>b.minOrder-a.minOrder)[0];
  return won ? { need:0, off:offOf(won), code:won.code, minOrder:won.minOrder, unlocked:true } : null;
}


