async function delMedia(id)  { await mediaDel("nemo-img-"+id); await mediaDel("nemo-vid-"+id); if(FB_OK){ try{ await FB_DB.ref("media/img-"+id).remove(); }catch(e){} } }

/* ── Orphaned posters ────────────────────────────────────────────────────────────────
   A poster and the guide that shows it are stored apart: the image at `media/img-<id>`, the
   title and category in the `guides` node. So losing the guides node does NOT lose the posters
   — it only loses the thing that pointed at them. They sit in `media` with nothing referencing
   their ids, invisible and un-deletable through the UI, which is exactly what happened when a
   store's guides went missing and three sample guides were published over the gap.

   Read SHALLOW. Values under `media` are Storage URLs for recent uploads but base64 for older
   ones, so an ordinary .get() on the node downloads megabytes of image data purely to learn the
   key names. `?shallow=true` returns the keys alone. `media` is world-readable, so this needs no
   auth — though only the admin can act on what it finds. */
/* Every place a poster can still be, listed by NAME only — never by value. A poster is written
   to as many as three places, and losing one does not lose the others:

     Firebase Storage   media/img-<id>.jpg   the uploaded file itself (recent uploads)
     Realtime Database  media/img-<id>       a Storage URL, or base64 for older uploads
     this device (IDB)  nemo-img-<id>        the cache written at upload time

   The first attempt at this read the database over plain REST with ?shallow=true. That is the
   cheapest way to get key names, but under App Check enforcement an unauthenticated REST call is
   refused — so it returned nothing and looked exactly like "there is nothing to find". It is kept
   as a bonus source, but the two that go through the SDK carry the App Check token and are the
   ones to trust. Storage listAll() is the best of them: it returns file names, so it costs
   nothing to enumerate even when the images are megabytes each. */
async function listMediaKeysREST(){
  try{
    const base=FIREBASE_CONFIG.databaseURL;
    if(!base) return null;
    const r=await withTimeout(fetch(base+"/media.json?shallow=true",{cache:"no-store"}),8000);
    if(!r||!r.ok) return null;
    const v=await r.json();
    return (v&&typeof v==="object")?Object.keys(v):[];
  }catch(e){ return null; }
}
async function listStoragePosterIds(){
  if(!FB_STORAGE) return null;
  try{
    const res=await withTimeout(FB_STORAGE.ref("media").listAll(),12000);
    if(!res||!res.items) return null;
    return res.items.map(it=>String(it.name||""))
      .filter(n=>n.indexOf("img-")===0)
      .map(n=>n.replace(/^img-/,"").replace(/\.(jpg|jpeg|png|webp)$/i,""));
  }catch(e){ return null; }
}
async function listCachedPosterIds(){
  if(!HAS_IDB) return null;
  try{
    const keys=await IDB.keys();
    return (keys||[]).map(String).filter(k=>k.indexOf("nemo-img-")===0).map(k=>k.slice(9));
  }catch(e){ return null; }
}
/* Poster ids nothing in the store refers to any more, gathered from all three places.

   Products, requests and guides all key a legacy single image as `img-<their id>`, so every id
   in play is subtracted rather than guessing which kind an orphan used to be. Returns the ids
   plus which sources could actually be read, because "found none" and "could not look" call for
   opposite reactions and a silent failure already cost this store one search. */
async function findOrphanPosters(lists){
  const [store,cache,rest]=await Promise.all([
    listStoragePosterIds(), listCachedPosterIds(), listMediaKeysREST(),
  ]);
  const restIds=rest===null?null:rest.filter(k=>k.indexOf("img-")===0).map(k=>k.slice(4));
  const sources={ storage:store!==null, device:cache!==null, database:restIds!==null };
  if(!sources.storage && !sources.device && !sources.database) return {ids:null,sources};
  const taken=new Set();
  (lists||[]).forEach(list=>(list||[]).forEach(x=>{ if(x&&x.id!=null) taken.add(String(x.id)); }));
  const all=new Set([...(store||[]),...(cache||[]),...(restIds||[])]);
  return { ids:[...all].filter(id=>id&&!taken.has(id)), sources };
}
/* A poster can survive in Storage while the database pointer that made it visible is gone. The
   file is useless to the app in that state — loadImg only looks at the cache and media/<key> —
   so restoring re-points the database at the file it already has, rather than re-uploading. */
async function repairPosterPointer(id){
  if(!FB_OK||!FB_STORAGE) return false;
  try{
    const existing=await fbGetObj("media/img-"+id);
    if(existing) return true;                       // pointer is fine; nothing to repair
    const url=await withTimeout(FB_STORAGE.ref("media/img-"+id+".jpg").getDownloadURL(),12000);
    if(!url) return false;
    await fbWrite(FB_DB.ref("media/img-"+id), url);
    await mediaSet("nemo-img-"+id,url);
    return true;
  }catch(e){ return false; }
}

/* ── Multi-media (per-product gallery): base64 stored in RTDB `media/<key>` + IndexedDB cache ── */
/* Upload a compressed image (JPEG data-URL) to Firebase Storage and return its public URL.
   Returns null if Storage isn't available/enabled or the upload fails — callers then fall
   back to storing the base64 in the Realtime Database (the original behaviour). */
const FB_UPLOAD_MS = 45000;   // generous — a photo on slow mobile data still needs a while
const UPLOAD_TIMED_OUT = {};  // sentinel, distinct from any value putString can resolve to
async function uploadToStorage(path, dataUrl){
  if(!FB_STORAGE || typeof dataUrl!=="string" || !dataUrl.startsWith("data:")) return null;
  let failed=null;
  const task=(async()=>{
    const ref=FB_STORAGE.ref(path);
    await ref.putString(dataUrl, "data_url");
    return await ref.getDownloadURL();
  })().catch(e=>{ failed=e||new Error("upload failed"); return null; });
  // Bounded so a stalled upload can't spin the save forever. A timeout is NOT treated as
  // "Storage is off" — the connection was just slow, so Storage stays enabled for next time.
  const url=await Promise.race([task, new Promise(r=>setTimeout(()=>r(UPLOAD_TIMED_OUT), FB_UPLOAD_MS))]);
  if(url===UPLOAD_TIMED_OUT){ console.warn("Storage upload timed out — using base64 path:", path); return null; }
  if(failed){
    // On the free (Spark) plan Storage isn't enabled, so every upload 401s. After the first
    // failure, disable Storage for this session so we go straight to the base64 path (no waiting
    // on doomed uploads, no console spam). Resets on reload if Storage is later enabled.
    FB_STORAGE=null;
    console.warn("Storage unavailable — using free-plan base64 path:", failed.message);
    return null;
  }
  return url;
}
async function saveMediaItem(key,b64){
  await mediaSet("nemo-m-"+key,b64);
  if(FB_OK){
    // Prefer Storage: keep only a tiny URL in the DB (huge speed win on load/sync).
    const url=await uploadToStorage("media/"+key+".jpg", b64);
    if(url){ await fbWrite(FB_DB.ref("media/"+key), url); await mediaSet("nemo-m-"+key,url); return true; }
    // Fallback: store base64 in the DB (original behaviour) so nothing breaks if Storage is off.
    // Base64 rows are big, so give this one a longer leash than an ordinary write.
    try{ await withTimeout(FB_DB.ref("media/"+key).set(b64), FB_UPLOAD_MS, false); }catch(e){ console.warn("saveMediaItem",e&&e.message); }
  }
  return true;
}
async function loadMediaItem(key){
  // Check local (IndexedDB) cache first — avoids a 6-second Firebase timeout on every image load
  const cached=await mediaGet("nemo-m-"+key); if(cached)return cached;
  // Then the CDN copy, which costs the database nothing. See CDN_MEDIA_KEYS above.
  const cdn=cdnMediaPath(key); if(cdn) return cdn;
  if(FB_OK){ try{ const s=await withTimeout(FB_DB.ref("media/"+key).get(),6000); const v=s&&s.val(); if(v){ mediaSet("nemo-m-"+key,v); return v; } }catch(e){} }
  return null;
}
async function delMediaItem(key){
  await mediaDel("nemo-m-"+key);
  if(FB_OK){ try{ await FB_DB.ref("media/"+key).remove(); }catch(e){} }
}
/* Compress an image file to a JPEG data-URL (keeps RTDB + sync light) */
function compressImage(file, maxDim=1100, quality=0.82){
  return new Promise((resolve,reject)=>{
    if(file.type==="image/gif"){ const r=new FileReader(); r.onload=e=>resolve(e.target.result); r.onerror=reject; r.readAsDataURL(file); return; }
    const img=new Image(); const url=URL.createObjectURL(file);
    img.onload=()=>{
      let {width:w,height:h}=img;
      if(w>maxDim||h>maxDim){ const s=maxDim/Math.max(w,h); w=Math.round(w*s); h=Math.round(h*s); }
      const cv=document.createElement("canvas"); cv.width=w; cv.height=h;
      cv.getContext("2d").drawImage(img,0,0,w,h);
      URL.revokeObjectURL(url);
      resolve(cv.toDataURL("image/jpeg",quality));
    };
    img.onerror=(err)=>{ URL.revokeObjectURL(url); reject(err); }; img.src=url;
  });
}
/* A tank photo lives as base64 INSIDE the database, in a node every visitor reads, and the free
   plan's download allowance is what stands between this shop and being cut off for the rest of
   the billing cycle. 650,000 characters was roughly half a megabyte per photo — sized against
   what the rules would accept rather than against what the gallery shows, which is a card a few
   hundred pixels wide. 200,000 characters is about 150 KB and still comfortably sharper than the
   card it is drawn in. The rules keep their own larger ceiling as a backstop against a client
   that ignores this one. */
const MAX_TANK_IMAGE_CHARS=200000;
async function compressTankImage(file){
  let latest="";
  for(const [maxDim,quality] of [[900,.74],[780,.66],[660,.58]]){
    latest=await compressImage(file,maxDim,quality);
    if(typeof latest==="string"&&latest.length<=MAX_TANK_IMAGE_CHARS) return latest;
  }
  throw new Error(latest?"tank-image-too-large":"tank-image-unreadable");
}
/* Make a small catalog thumbnail (JPEG data-URL) from a full-size image data-URL.
   Used so the product grid downloads ~tiny images instead of full-res ones — the
   single biggest first-load win. Returns null for anything that isn't a data-URL image. */
function makeThumb(dataUrl, maxDim=560, quality=0.82){
  return new Promise(resolve=>{
    try{
      if(typeof dataUrl!=="string" || !dataUrl.startsWith("data:image")){ resolve(null); return; }
      const img=new Image();
      img.onload=()=>{ try{
        let w=img.width, h=img.height;
        if(w>h){ if(w>maxDim){ h=Math.round(h*maxDim/w); w=maxDim; } }
        else   { if(h>maxDim){ w=Math.round(w*maxDim/h); h=maxDim; } }
        const cv=document.createElement("canvas"); cv.width=w; cv.height=h;
        const ctx=cv.getContext("2d"); ctx.imageSmoothingQuality="high"; ctx.drawImage(img,0,0,w,h);
        resolve(cv.toDataURL("image/jpeg",quality));
      }catch(e){ resolve(null); } };
      img.onerror=()=>resolve(null);
      img.src=dataUrl;
    }catch(e){ resolve(null); }
  });
}
/* Like makeThumb but also accepts a remote (Storage) URL. Remote draws need CORS on the
   bucket; if that's not configured the canvas read throws and we return null (caller skips). */
async function makeThumbFromAny(src, maxDim=560, quality=0.82){
  if(typeof src!=="string") return null;
  if(src.startsWith("data:")) return makeThumb(src, maxDim, quality);
  return new Promise(resolve=>{
    const img=new Image(); img.crossOrigin="anonymous";
    img.onload=()=>{ try{
      let w=img.width, h=img.height;
      if(w>h){ if(w>maxDim){ h=Math.round(h*maxDim/w); w=maxDim; } }
      else   { if(h>maxDim){ w=Math.round(w*maxDim/h); h=maxDim; } }
      const cv=document.createElement("canvas"); cv.width=w; cv.height=h;
      const ctx=cv.getContext("2d"); ctx.imageSmoothingQuality="high"; ctx.drawImage(img,0,0,w,h);
      resolve(cv.toDataURL("image/jpeg",quality));
    }catch(e){ resolve(null); } };
    img.onerror=()=>resolve(null);
    img.src=src;
  });
}
/* Persist ONE gallery image the major-ecommerce way and return {url, thumbUrl} to embed
   directly on the product record. Bytes go to Firebase Storage (CDN); only short URLs touch
   the database. If Storage is unavailable it falls back to the legacy base64-in-RTDB path so
   nothing breaks \u2014 callers then get an empty object and readers use the media/<key> cache. */
async function persistImage(key, b64, withThumb=true){
  const out={};
  if(FB_STORAGE){
    // The thumbnail is made from the same bytes we already hold and lands at its own path, so
    // it does not need the full-size upload to finish first. Sending both at once saves a whole
    // upload + getDownloadURL round trip on the one image that carries a thumbnail.
    const mainUp=uploadToStorage("media/"+key+".jpg", b64);
    const thumbUp=withThumb
      ? makeThumb(b64).then(t=>t?uploadToStorage("media/"+key+"_thumb.jpg",t).then(tu=>({t,tu})):null).catch(()=>null)
      : Promise.resolve(null);
    const [url,thumb]=await Promise.all([mainUp,thumbUp]);
    if(url){
      out.url=url; try{ await mediaSet("nemo-m-"+key, url); }catch(e){}
      if(thumb&&thumb.tu){ out.url_thumb=thumb.tu; out.thumbData=thumb.t; }
      return out;
    }
  }
  // FREE plan (Storage off) — base64 in the Realtime Database, plus a small base64 thumbnail
  // so the catalog grid stays light (full image only loads on the product page).
  await saveMediaItem(key, b64);
  if(withThumb){
    const t=await makeThumb(b64);
    if(t){ await saveMediaItem(key+"_thumb", t); out.thumbData=t; }
  }
  return out;
}
/* Thumbnail for one cart line. Cart items are snapshots taken at add-to-cart time and
   deliberately carry no image (the cart is persisted to localStorage, and a base64 thumb
   would blow the quota), so resolve it from the live catalog by id at render time. */
function getCartLineImg(item, products, cache){
  if(!item) return null;
  const p=(products||[]).find(x=>x.id===item.id);
  return p?getCardImg(p,cache||{}):null;
}
/* Cart lines and order lines are snapshots taken at add-to-cart / checkout time, so they
   carry no link back to the catalogue. Resolve the live product by id so tapping a line
   can open its page. Returns null for a product that has since been removed (or a demo
   line), and the caller then renders the line as plain, untappable text. */
function lineProduct(item, products){
  if(!item||!item.id) return null;
  return (products||[]).find(p=>p.id===item.id)||null;
}
/* What this cart line can be bought as RIGHT NOW, as opposed to when it was added.
   A line is a snapshot — name, price and stockCount as they were at the time — which is what
   keeps a cart stable while the shop changes underneath it. That is right for the price and
   wrong for availability: a payment window that runs out, or a busy hour, can sell the last
   one while the line sits in the basket. Returns -1 for a product that has left the catalogue
   entirely, which is a different thing to say than "none left". */
function lineLiveStock(item, products){
  const p=lineProduct(item,products);
  if(!p) return -1;
  if(p.comingSoon) return 0;
  const v=(productVariants(p)||[]).find(x=>x&&(x.id===item.variantId||x.label===item.variantLabel));
  return v?variantStockOf(p,v):(p.stockCount??DEFAULT_STOCK);
}
/* Resolve a product's gallery from the media cache (with backward-compat) */
function getProductMedia(p, cache={}){
  const images=[]; let video=null;
  if(Array.isArray(p.media)&&p.media.length){
    // Prefer the URL embedded on the product (zero extra DB reads — the major-ecommerce pattern);
    // fall back to the per-key media cache for legacy items whose URL isn't embedded yet.
    p.media.forEach(m=>{ const src=m.url||cache["m-"+m.key]; if(m.type==="video"){ if(src)video=src; } else if(src)images.push(src); });
  }
  if(!images.length){ // legacy single-image fields
    if(p.imageUrl) images.push(p.imageUrl);
    else if(cache["img-"+p.id]) images.push(cache["img-"+p.id]);
  }
  if(!video && cache["vid-"+p.id]) video=cache["vid-"+p.id];
  return {images, video};
}
/* Catalog-card image: prefer the small thumbnail so the grid stays light. Order: an
   instant just-saved local thumbnail → the stored thumbnail URL → full image URL → legacy cache. */
function getCardImg(p, cache={}){
  if(Array.isArray(p.media)&&p.media.length){
    const first=p.media.find(m=>m.type!=="video");
    if(first){
      if(first.thumb && cache["thumb-"+first.key]) return cache["thumb-"+first.key];
      if(first.thumbUrl) return first.thumbUrl;
      if(first.url) return first.url;
    }
  }
  return getProductMedia(p,cache).images[0];
}

async function loadReviews(pid){
  if(FB_OK){ const a=await fbGetColl("reviews/"+pid); if(a) return a.sort((x,y)=>(y.date||"").localeCompare(x.date||"")); }
  const r=await dbGet("nemo-rev-"+pid); return r?JSON.parse(r):[];
}
/* Aggregate every review-attached photo across all products → the "Arrived Alive" wall.
   One cloud read; returns newest-first {photo, name, rating, pid}. */
async function loadArrivedAlivePhotos(limit=24){
  let byPid={};
  if(FB_OK){ try{ const s=await withTimeout(FB_DB.ref("reviews").get(),6000); const v=s&&s.val(); if(v) byPid=v; }catch(e){} }
  const out=[];
  Object.keys(byPid||{}).forEach(pid=>{
    const coll=byPid[pid]; if(!coll) return;
    Object.values(coll).forEach(r=>{
      if(r&&Array.isArray(r.photos)&&r.photos.length){
        r.photos.forEach(ph=>out.push({photo:ph,name:r.name||"Customer",rating:r.rating||0,date:r.date||"",pid}));
      }
    });
  });
  out.sort((a,b)=>(b.date||"").localeCompare(a.date||""));
  return out.slice(0,limit);
}
async function saveReviews(pid,list){ await dbSet("nemo-rev-"+pid,JSON.stringify(list)); if(FB_OK) await fbSetColl("reviews/"+pid,list); }
async function appendReview(pid,rev){
  // Write ONLY this review to its own node — never overwrite the whole collection (a whole-node .set wiped concurrent reviewers' entries)
  if(FB_OK){ await fbWrite(FB_DB.ref("reviews/"+pid+"/"+rev.id), rev); }
  const list=await loadReviews(pid);
  const next=list.some(r=>r.id===rev.id)?list:[rev,...list];
  await dbSet("nemo-rev-"+pid,JSON.stringify(next)); // local cache only
  return next;
}
async function deleteReview(pid,rid){
  if(FB_OK){ try{ await FB_DB.ref("reviews/"+pid+"/"+rid).remove(); }catch(e){} } // remove just this review, not the whole node
  const list=await loadReviews(pid);
  const next=list.filter(r=>r.id!==rid);
  await dbSet("nemo-rev-"+pid,JSON.stringify(next));
  return next;
}

