function fileToBase64(f){ return new Promise((res,rej)=>{ const r=new FileReader(); r.onload=e=>res(e.target.result); r.onerror=rej; r.readAsDataURL(f); }); }
/* ── Short product clips ──────────────────────────────────────────────────────
   A phone video of a fish is 20–100MB, so "pick a file under 5MB" was a rule
   nothing off a camera could satisfy — the upload simply never worked. Instead of
   asking for a smaller file, the chosen range is re-encoded here in the browser:
   frames are drawn to a downscaled canvas and recorded off canvas.captureStream(),
   which yields a small, web-friendly clip. The recorder is only ever handed the
   canvas — no microphone, no audio track from the source — so the sound is dropped
   by design rather than muted at playback, and a noisy shop recording never ships
   with the product. */
/* What the video picker offers. MIME types only: this once read `video/*,.gif`,
   and mixing a wildcard with a bare extension is a well-known way to have
   Android's file chooser quietly narrow the list. */
const VIDEO_ACCEPT = [
  "video/mp4",        // what essentially every phone records
  "video/quicktime",  // .mov, iPhone
  "video/webm",
  "video/x-matroska", // .mkv
  "video/3gpp",       // older Android
  "video/*",          // backstop for anything not named above
  "image/gif",
].join(",");

/* Second line of defence, for pickers that ignore `accept` and hand back
   whatever was tapped. Deliberately generous: Android pickers frequently report
   no MIME type at all, and an owner holding an obviously-named .mp4 must not be
   turned away because their file manager said nothing about it. Something that
   gets through and still cannot be decoded fails later with its own message —
   a wrong guess here is recoverable, a refusal is not. */
const VIDEO_EXT_RE = /\.(mp4|m4v|mov|qt|webm|mkv|3gp|3g2|avi|wmv|flv|mpe?g|mts|m2ts|ts|hevc|gif)$/i;
function looksLikeVideo(file){
  if(!file) return false;
  const type=(file.type||"").toLowerCase();
  if(type.startsWith("video/")) return true;
  if(type==="image/gif") return true;
  // No type, or a generic one the picker made up: fall back to the name.
  if(!type||type==="application/octet-stream") return VIDEO_EXT_RE.test(file.name||"");
  return false;
}
const CLIP_MAX_SEC = 15;
const CLIP_MAX_BYTES = 5*1024*1024;   // every clip is encoded to fit under this, never rejected for it
const CLIP_SHORT_SIDE = 720;          // 720p on the short side — 540p read as soft on a big screen
const CLIP_BITRATE = 2000000;         // ~3.8MB for a full 15s clip, so 720p still fits the budget
function clipMimeType(){
  if(typeof MediaRecorder==="undefined") return "";
  return ["video/webm;codecs=vp9","video/webm;codecs=vp8","video/webm","video/mp4"]
    .find(t=>{ try{ return MediaRecorder.isTypeSupported(t); }catch(e){ return false; } }) || "";
}
function canTrimVideo(){
  return typeof MediaRecorder!=="undefined"
    && typeof document!=="undefined"
    && !!document.createElement("canvas").captureStream
    && !!clipMimeType();
}
function loadVideoEl(src){
  return new Promise((res,rej)=>{
    const v=document.createElement("video");
    v.preload="metadata"; v.muted=true; v.playsInline=true; v.setAttribute("playsinline","");
    v.onloadedmetadata=()=>res(v);
    v.onerror=()=>rej(new Error("This video format can't be read on this device"));
    v.src=src;
  });
}
async function exportClip(src,start,end,opts={}){
  const {maxShort=CLIP_SHORT_SIDE, fps=30, bitrate=CLIP_BITRATE, onProgress} = opts;
  const v=await loadVideoEl(src);
  const sw=v.videoWidth||maxShort, sh=v.videoHeight||maxShort;
  // "720p" is the SHORT side, so a landscape clip lands at 1280x720 and a portrait phone clip at
  // 720x1280 — capping the width instead would quietly halve the resolution of every portrait
  // video, which is most of what a phone shoots.
  const scale=Math.min(1,maxShort/Math.min(sw,sh));
  const canvas=document.createElement("canvas");
  // Even dimensions keep every encoder happy.
  canvas.width=Math.max(2,Math.round(sw*scale/2)*2);
  canvas.height=Math.max(2,Math.round(sh*scale/2)*2);
  const ctx=canvas.getContext("2d");
  const mime=clipMimeType();
  const stream=canvas.captureStream(fps);
  const rec=new MediaRecorder(stream, mime?{mimeType:mime,videoBitsPerSecond:bitrate}:{videoBitsPerSecond:bitrate});
  const chunks=[];
  rec.ondataavailable=e=>{ if(e.data&&e.data.size) chunks.push(e.data); };
  const stopped=new Promise(r=>{ rec.onstop=r; });
  v.currentTime=Math.max(0,start);
  await new Promise(r=>{ v.onseeked=r; setTimeout(r,1200); });   // don't hang on a seek that never reports
  rec.start();
  try{ await v.play(); }catch(e){ /* autoplay refusal on a muted, off-screen element is harmless */ }
  await new Promise(res=>{
    const tick=()=>{
      ctx.drawImage(v,0,0,canvas.width,canvas.height);
      if(onProgress) onProgress(Math.min(1,(v.currentTime-start)/Math.max(0.1,end-start)));
      if(v.currentTime>=end || v.ended){ res(); return; }
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  });
  try{ v.pause(); }catch(e){}
  rec.stop();
  await stopped;
  return new Blob(chunks,{type:mime||"video/webm"});
}
/* Encode the selection so it lands UNDER a byte budget, whatever the phone shot.
   The first pass sizes the bitrate from the budget and the clip length, which alone is enough
   for a 15s clip; if the encoder overshoots anyway, each further pass drops the bitrate by the
   overshoot and shrinks the frame, so the answer converges instead of failing. */
async function exportClipUnderSize(src,start,end,targetBytes,opts={}){
  const {onProgress,onPass}=opts;
  const dur=Math.max(0.5,end-start);
  let short=CLIP_SHORT_SIDE;
  // 78% of the budget: WebM container overhead plus the encoder's own rate wobble.
  let bitrate=Math.max(220000,Math.round(Math.min(CLIP_BITRATE,(targetBytes*8*0.78)/dur)));
  let blob=null;
  for(let pass=1;pass<=3;pass++){
    if(onPass) onPass(pass);
    blob=await exportClip(src,start,end,{maxShort:short,bitrate,onProgress});
    if(!blob||!blob.size) throw new Error("Nothing was recorded — try a shorter selection");
    if(blob.size<=targetBytes) return blob;
    const over=blob.size/targetBytes;
    bitrate=Math.max(180000,Math.round(bitrate/over*0.78));
    short=Math.max(360,Math.round(short*0.78));
  }
  return blob;
}
function fmtClock(sec){
  const s=Math.max(0,Math.floor(sec||0));
  return Math.floor(s/60)+":"+String(s%60).padStart(2,"0");
}
function uid(pfx="p"){ return pfx+Date.now()+Math.random().toString(36).slice(2,5); }
function fmtSize(b){ if(b<1024)return b+"B"; if(b<1048576)return(b/1024).toFixed(0)+"KB"; return(b/1048576).toFixed(1)+"MB"; }
function fmtDate(iso){ return new Date(iso).toLocaleDateString("en-IN",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}); }
function orderId(id){ return "#NA-"+id.slice(-6).toUpperCase(); }
function orderDayKey(ms){ const d=new Date(ms||Date.now()); const p=n=>String(n).padStart(2,"0"); return `${d.getFullYear()}${p(d.getMonth()+1)}${p(d.getDate())}`; }
/* Sequential, human-friendly order number: NAS-YYYYMMDD-#### (resets daily).
   Uses an atomic Firebase counter so the numbers are unique & ordered across devices. */
async function nextOrderNo(placedAtMs){
  const day=orderDayKey(placedAtMs);
  if(FB_OK && FB_DB){
    try{
      const res=await withTimeout(FB_DB.ref("orderSeq/"+day).transaction(cur=>(Number(cur)||0)+1), 6000);
      const seq=res&&res.snapshot&&res.snapshot.val();
      if(seq) return `NAS-${day}-${String(seq).padStart(4,"0")}`;
    }catch(e){}
  }
  // Offline / no cloud: time-based suffix keeps it unique & sortable within the day.
  const d=new Date(placedAtMs||Date.now()); const p=n=>String(n).padStart(2,"0");
  return `NAS-${day}-${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`;
}
function normalizePhone(p){ return (p||"").replace(/\D/g,"").slice(-10); }
function hasPurchased(orders, user, productId){
  if(!user) return false;
  const uk = userKey(user);
  const ph = normalizePhone(user.phone||"");
  const ok = new Set(["Delivered"]); // only a delivered order makes a verified reviewer
  return orders.some(o =>
    ( (uk && o.userUid===uk) || (user.uid && o.userUid===user.uid) || (ph && normalizePhone(o.address?.phone)===ph) )
    && ok.has(o.status)
    && o.items.some(i=>i.id===productId));
}

