/* ═══════════════════ MINI COUNTDOWN (product cards + detail) ═══════════════════ */
function MiniCountdown({endsAt,compact=false}){
  const [now,setNow]=useState(Date.now());
  useEffect(()=>{
    const end=new Date(endsAt).getTime();
    if(end<=Date.now())return;
    const t=setInterval(()=>setNow(Date.now()),1000);
    return()=>clearInterval(t);
  },[endsAt]);
  const ms=Math.max(0,new Date(endsAt).getTime()-now);
  if(ms<=0)return null;
  const h=Math.floor(ms/3600000);
  const m=Math.floor((ms%3600000)/60000);
  const s=Math.floor((ms%60000)/1000);
  const fmt=n=>String(n).padStart(2,"0");
  if(compact)return(
    <div style={{display:"inline-flex",alignItems:"center",gap:4,background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:8,padding:"3px 7px",marginTop:4}}>
      <span style={{fontSize:9,color:"#c2410c"}}>⏱</span>
      <span style={{fontFamily:PRICE_FONT,fontSize:10,fontWeight:800,color:"#c2410c",letterSpacing:.5}}>
        {h>0?`${fmt(h)}h `:""}{fmt(m)}:{fmt(s)}
      </span>
      <span style={{fontSize:9,color:"#9a3412",fontWeight:600}}>left</span>
    </div>
  );
  return(
    <div style={{display:"flex",alignItems:"center",gap:10,background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:12,padding:"9px 14px",marginBottom:10}}>
      <span style={{fontSize:18}}>⏱</span>
      <div>
        <div style={{fontSize:10,color:"#9a3412",fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>Flash sale ends in</div>
        <div style={{fontFamily:PRICE_FONT,fontSize:18,fontWeight:800,color:"#c2410c",letterSpacing:1}}>
          {h>0&&<span>{fmt(h)}<span style={{fontSize:10,fontWeight:600,marginRight:4}}>h</span></span>}
          {fmt(m)}<span style={{fontSize:10,fontWeight:600,marginRight:4}}>m</span>
          {fmt(s)}<span style={{fontSize:10,fontWeight:600}}>s</span>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════ OFFER BANNERS ═══════════════════ */
/* One component for what used to be two: the first-order welcome banner and the
   seasonal/festival banner. Every coupon flagged `showOnWelcome` renders here, so an owner
   can run as many as they like — a Diwali offer and a first-order offer side by side — and
   each decides its own audience through `firstOrderOnly` and its own expiry through
   `endsAt`. A coupon with no code is an announcement: it still shows, with nothing to copy. */
function OfferBanners({settings,orders=[]}){
  const list=usableCoupons(settings,orders,"welcome");
  const [copied,setCopied]=useState("");
  const [open,setOpen]=useState(false);
  const promoDay=()=>{ try{return new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Kolkata",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());}catch(e){return new Date().toISOString().slice(0,10);} };
  useEffect(()=>{
    if(!list.length) return;
    const day=promoDay();
    try{
      if(localStorage.getItem("nemo-promo-popup-day-v1")===day) return;
      localStorage.setItem("nemo-promo-popup-day-v1",day);
    }catch(e){}
    const timer=setTimeout(()=>setOpen(true),220);
    return()=>clearTimeout(timer);
  },[list.map(c=>c.id).join("|")]);
  if(!list.length||!open) return null;
  const close=()=>setOpen(false);
  const copy=(code)=>{ try{ navigator.clipboard.writeText(code); }catch(e){} setCopied(code); setTimeout(()=>setCopied(""),1600); };
  return(
    <div onClick={close} role="presentation" style={{position:"fixed",top:0,left:0,right:0,height:"100dvh",minHeight:"100vh",zIndex:4200,background:"rgba(15,23,42,.56)",backdropFilter:"blur(4px)",display:"flex",alignItems:"center",justifyContent:"center",padding:18}}>
      <div onClick={e=>e.stopPropagation()} role="dialog" aria-modal="true" aria-label="Today's promotions" className="fade-rise" style={{position:"relative",width:"min(92vw,430px)",maxHeight:"82vh",overflowY:"auto",background:C.card,borderRadius:20,padding:"18px",boxShadow:"0 24px 70px rgba(15,23,42,.32)"}}>
        <button className="press" onClick={close} aria-label="Close promotion" style={{position:"absolute",right:10,top:9,width:36,height:36,borderRadius:20,border:`1px solid ${C.border}`,background:"rgba(255,255,255,.94)",fontSize:20,fontWeight:800,color:C.text,zIndex:2}}>×</button>
        <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:800,fontSize:18,color:C.text,paddingRight:38,marginBottom:12}}>Today at Nemo</div>
        {list.map(c=>{
          const bg=c.bg||"#7c3aed";
          const worth=c.type==="coins"?`${c.value} reward coins`:c.type==="percent"?`${c.value}% off${c.maxDiscount>0?` (up to ₹${c.maxDiscount})`:""}`:`₹${c.value} off`;
          return(
            <div key={c.id} style={{background:`linear-gradient(135deg,${bg},${bg}cc)`,borderRadius:20,padding:"18px 16px",marginBottom:12,textAlign:"center",boxShadow:`0 8px 22px ${bg}33`}}>
              <div style={{fontSize:28,lineHeight:1}}>{c.emoji||"🎉"}</div>
              <div style={{fontSize:13,fontWeight:800,color:"rgba(255,255,255,.92)",marginTop:6,letterSpacing:.3}}>{c.name||"Special offer"}</div>
              {c.value>0&&<div style={{fontFamily:PRICE_FONT,fontSize:24,fontWeight:800,color:"white",lineHeight:1.15,marginTop:2}}>{worth}</div>}
              {(c.minOrder>0||c.firstOrderOnly)&&<div style={{fontSize:11,color:"rgba(255,255,255,.85)",marginTop:4}}>{c.firstOrderOnly?"First order":""}{c.firstOrderOnly&&c.minOrder>0?" · ":""}{c.minOrder>0?`On orders above ₹${c.minOrder}`:""}</div>}
              {c.code&&<div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:8,marginTop:11,flexWrap:"wrap"}}>
                <div style={{background:"rgba(255,255,255,.2)",borderRadius:8,padding:"5px 14px",border:"1px dashed rgba(255,255,255,.6)"}}><span style={{fontFamily:"monospace",fontSize:14,fontWeight:800,color:"white",letterSpacing:2}}>{c.code}</span></div>
                <button className="press" onClick={()=>copy(c.code)} style={{background:"rgba(255,255,255,.2)",border:"1px solid rgba(255,255,255,.4)",borderRadius:12,padding:"7px 13px",color:"white",fontSize:11,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>{copied===c.code?"✓ Copied":"Copy"}</button>
              </div>}
            </div>
          );
        })}
        <div style={{fontSize:10,color:C.textSub,textAlign:"center"}}>Shown once per day. Tap outside this card or × to close.</div>
      </div>
    </div>
  );
}

/* ═══════════════════ LOYALTY POINTS WIDGET ═══════════════════ */
function LoyaltyWidget({points,settings,onRedeem,redeemApplied,subtotal=0}){
  const enabled=settings.loyaltyEnabled;
  const min=Number(settings.loyaltyRedeemMin||100);
  const val=Number(settings.loyaltyRedeemValue||1);
  const maxCoins=walletCoinCap(settings);
  const minOrder=Number(settings.walletMinOrder||0);
  if(!enabled||points==null)return null;
  const orderOk=subtotal>=minOrder;
  const canRedeem=points>=min&&orderOk&&!redeemApplied;
  const usedCoins=Math.min(points,maxCoins);
  const worth=Math.floor(usedCoins*val);
  const totalWorth=Math.floor(points*val);
  return(
    <div className="points-pop" style={{background:"linear-gradient(135deg,#1d4ed8 0%,#7c3aed 100%)",borderRadius:12,padding:"10px 12px",marginBottom:12,boxShadow:"0 4px 14px rgba(124,58,237,.18)"}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,marginBottom:redeemApplied?0:5}}>
        <div style={{display:"flex",alignItems:"center",gap:7,minWidth:0}}>
          <span style={{fontSize:18}}>👛</span>
          <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:13,fontWeight:800,color:"white",lineHeight:1.2,whiteSpace:"nowrap"}}>
            {points} coins <span style={{fontWeight:600,opacity:.82}}>· ₹{totalWorth}</span>
          </div>
        </div>
        {!redeemApplied&&(
          <button className="press" onClick={onRedeem} disabled={!canRedeem}
            style={{background:canRedeem?"rgba(255,255,255,.2)":"rgba(255,255,255,.08)",border:`1px solid ${canRedeem?"rgba(255,255,255,.5)":"rgba(255,255,255,.2)"}`,borderRadius:8,padding:"6px 9px",color:canRedeem?"white":"rgba(255,255,255,.55)",fontSize:10,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:canRedeem?"pointer":"not-allowed",whiteSpace:"nowrap"}}>
            {points<min?`Need ${min-points} coins`:!orderOk?`Min. order ₹${minOrder}`:`Use ₹${worth}`}
          </button>
        )}
      </div>
      {redeemApplied&&(
        <div style={{fontSize:10,color:"rgba(255,255,255,.9)",fontWeight:700}}>✓ ₹{worth} wallet applied{points>maxCoins?` · max ${maxCoins} coins/order`:""}</div>
      )}
      {!redeemApplied&&canRedeem&&points>maxCoins&&(
        <div style={{fontSize:9,color:"rgba(255,255,255,.8)",marginTop:3}}>Up to {maxCoins} coins (₹{Math.floor(maxCoins*val)}) per order</div>
      )}
      {!redeemApplied&&!canRedeem&&(
        <div style={{background:"rgba(0,0,0,.15)",borderRadius:8,height:3,overflow:"hidden",marginTop:3}}>
          <div style={{height:"100%",background:"rgba(255,255,255,.6)",borderRadius:8,width:`${Math.min(100,(points/min)*100)}%`,transition:"width .4s ease"}}/>
        </div>
      )}
    </div>
  );
}

/* ═══════════════════ CUSTOMER TANK SHOWCASE ═══════════════════ */
/* A tank's photos, advancing on their own. The point is that the gallery is readable without
   opening anything: a customer scrolling past sees every photo of every tank, and only taps in
   when they want to vote. Single-photo entries render as a plain image — no timer, no dots. */
function TankSlides({imgs,alt,height,rounded=0,ms=3000,paused=false}){
  const [i,setI]=useState(0);
  const n=imgs.length;
  useEffect(()=>{
    if(n<2||paused) return;
    const t=setInterval(()=>setI(v=>(v+1)%n),ms);
    return ()=>clearInterval(t);
  },[n,ms,paused]);
  useEffect(()=>{ if(i>=n) setI(0); },[n,i]);
  if(!n) return null;
  return(
    <div style={{position:"relative",width:"100%",height:height||"100%",overflow:"hidden",borderRadius:rounded}}>
      {imgs.map((src,k)=>(
        <img key={k} src={src} alt={k===0?alt:""} loading="lazy" decoding="async"
          style={{position:"absolute",inset:0,width:"100%",height:"100%",objectFit:"cover",
                  opacity:k===i?1:0,transition:"opacity .6s ease"}}/>
      ))}
      {n>1&&(
        <div style={{position:"absolute",bottom:5,left:0,right:0,display:"flex",justifyContent:"center",gap:4}}>
          {imgs.map((_,k)=>(
            <span key={k} style={{width:k===i?12:5,height:5,borderRadius:99,background:k===i?"#fff":"rgba(255,255,255,.55)",transition:"width .3s ease",boxShadow:"0 0 3px rgba(0,0,0,.4)"}}/>
          ))}
        </div>
      )}
    </div>
  );
}

function TankShowcaseSection({showcase,user,settings,onSubmit,onVote,votes={},previousWinners=null,mode="full"}){
  const [preview,setPreview]=useState([]);
  const [ownerName,setOwnerName]=useState(user?.name||"");
  const [caption,setCaption]=useState("");
  const [note,setNote]=useState("");
  const [fullImg,setFullImg]=useState(null);
  const swipeStartX=useRef(null);
  const [uploading,setUploading]=useState(false);
  const [voting,setVoting]=useState("");
  const [rulesOpen,setRulesOpen]=useState(false);
  const [clock,setClock]=useState(Date.now());
  const [streak,setStreak]=useState(()=>user?loadTankStreakLocal(user.uid):null);
  const approvedMineKey=user?.uid?(showcase||[]).filter(s=>s&&s.userUid===user.uid&&showcaseApproved(s)).map(s=>s.id).sort().join("|"):"";
  useEffect(()=>{ const id=setInterval(()=>setClock(Date.now()),60000); return ()=>clearInterval(id); },[]);
  useEffect(()=>{
    let alive=true;
    if(!user?.uid){ setStreak(null); return ()=>{alive=false;}; }
    loadTankUploadStreak(user.uid).then(v=>{if(alive)setStreak(v);});
    return ()=>{alive=false;};
  },[user?.uid,approvedMineKey]);
  // ── Sync name field with the signed-in Google account.
  // Functional updater preserves any name the user has already typed manually.
  useEffect(()=>{
    if(user?.name) setOwnerName(n=>n||user.name);
  },[user?.name]);
  if(!settings.showcaseEnabled)return null;
  const now=clock;
  const contest=tankVoteRewardOn(settings);
  const streakReward=tankStreakRewardOn(settings);
  const anyReward=contest||streakReward;
  const month=totmMonthOf(now);
  const liveShowcase=(showcase||[]).filter(s=>showcaseApproved(s)&&!showcaseExpired(s,now));
  const ranked=contest?totmStandings(liveShowcase,month,votes):liveShowcase;
  const moveFullTank=dir=>{
    if(!fullImg||ranked.length<2) return;
    const idx=ranked.findIndex(entry=>entry.id===fullImg.id);
    if(idx>=0) setFullImg(ranked[(idx+dir+ranked.length)%ranked.length]);
  };
  const minePending=user&&(showcase||[]).find(s=>s.userUid===user.uid&&!showcaseApproved(s));
  const mineApproved=user&&(showcase||[]).find(s=>s.userUid===user.uid&&showcaseApproved(s)&&!showcaseExpired(s,now));
  const mine=minePending||mineApproved;
  const previousMonth=previousTotmMonth(now);
  const monthlyStreak=streak?monthUploadStats(streak.dates,month):null;
  const votesFor=e=>voteCount(e,votes);
  const showGallery = mode!=="upload";
  const showUpload  = mode!=="gallery" && !!user;
  // Nothing to show: gallery with no live photos & no pending submission, or upload with no signed-in user.
  if(showGallery && !showUpload && ranked.length===0 && !mine && !(previousWinners&&(previousWinners.vote||previousWinners.streak))) return null;
  if(!showGallery && !showUpload) return null;

  /* One photo per entry. Three of them rode inside a single database record, in a node that
     every visitor downloads in full, and the entry duplicated the first one on top of that (see
     submit below) — so a customer sharing three pictures cost four. The gallery shows one card
     per customer anyway; the others were only visible after a tap. */
  const MAX_IMGS=1;
  const handleFiles=async files=>{
    const list=Array.from(files||[]).slice(0,MAX_IMGS-preview.length);
    if(!list.length) return;
    setNote("Processing…");
    try{
      const out=[];
      for(const f of list) out.push(await compressTankImage(f));
      setPreview(p=>[...p,...out].slice(0,MAX_IMGS));
      setNote("✓ Photo ready");
    }catch(e){ setNote("⚠ Couldn't read that image — try a JPG or PNG"); }
  };
  const submit=async()=>{
    if(!preview.length){setNote("⚠ Please add at least one photo");return;}
    const finalName=(user?.name||ownerName||"Aquarist").trim();
    setUploading(true);
    try{
      const entryId=minePending?.id||(user?.uid?(user.uid+"_"+Date.now().toString(36)):uid("sc"));
      const submittedAt=Date.now();
      /* `imgs` is not written any more. It used to carry the whole preview list WHILE imgData
         carried preview[0] as well, so every entry stored its first photo twice. showcaseImgs
         still reads `imgs` first, so entries posted before this — none of which outlive their
         24-hour window — keep rendering all of theirs. */
      const uploaded=await onSubmit({id:entryId,imgData:preview[0],ownerName:finalName,caption:caption.trim(),
        createdAt:new Date(submittedAt).toISOString(),pendingExpiresAt:submittedAt+SHOWCASE_PENDING_TTL,
        approved:false,userUid:user?.uid||(user?userKey(user):""),...(contest?{month}:{})});
      if(!uploaded) throw new Error("tank-upload-failed");
      if(user?.uid) loadTankUploadStreak(user.uid).then(setStreak);
      setPreview([]);setCaption("");setOwnerName(user?.name||"");setNote("📩 Submitted! We'll review it soon.");
      setTimeout(()=>setNote(""),4000);
    }catch(e){
      setNote("⚠ Upload failed. Your photo is still here — tap Share my tank to retry.");
    }finally{
      setUploading(false);
    }
  };
  const vote=async(entry)=>{
    if(!user){ setNote("⚠ Sign in to vote"); return; }
    if(entry.userUid===user.uid){ setNote("⚠ You can't vote for your own tank"); return; }
    if(hasVotedForTank(entry,user.uid,votes)){ setNote("⚠ You already voted for this tank"); return; }
    setVoting(entry.id);
    await onVote(entry);
    setVoting("");
  };

  return(
    <div style={{marginBottom:26}}>
      {showGallery&&<React.Fragment>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:4}}>
        <span style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:18,fontWeight:800,color:C.text}}>{contest?"🏆 Tank of the Month":"🪸 Customer Tanks"}</span>
        {ranked.length>0&&<span style={{fontSize:11,color:C.textSub,fontWeight:600}}>{ranked.length} live</span>}
      </div>

      {minePending&&(
        <div style={{background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:12,padding:"10px 13px",marginBottom:12,display:"flex",alignItems:"center",gap:10}}>
          <img src={showcaseImgs(mine)[0]} alt="" style={{width:38,height:38,borderRadius:8,objectFit:"cover",flexShrink:0}}/>
          <div style={{fontSize:11,color:"#9a3412",fontWeight:600,lineHeight:1.45}}>⏳ Your new tank is awaiting approval. {mineApproved?"Your current approved photo stays live unless this replacement is approved.":"It will go live only after it meets the store rules and is approved."}</div>
        </div>
      )}
      {mineApproved&&(
        <div style={{background:"#ecfdf5",border:"1px solid #a7f3d0",borderRadius:12,padding:"10px 13px",marginBottom:12,display:"flex",alignItems:"center",gap:10}}>
          <img src={showcaseImgs(mineApproved)[0]} alt="" style={{width:38,height:38,borderRadius:8,objectFit:"cover",flexShrink:0}}/>
          <div style={{fontSize:11,color:"#15803d",fontWeight:600,lineHeight:1.45}}>
            ✓ Your current tank is live{contest?<> · <b>🗳️ {votesFor(mineApproved)}</b></>:null}{showcaseHoursLeft(mineApproved,now)>0?<> · <b>🕒 {showcaseHoursLeft(mineApproved,now)}h</b></>:null}{minePending?" · replacement pending":""}.
          </div>
        </div>
      )}
      {ranked.length>0&&(
        <div style={{display:"flex",gap:10,overflowX:"auto",paddingBottom:6,marginBottom:12}}>
          {ranked.map((s,idx)=>{
            const imgs=showcaseImgs(s);
            const n=votesFor(s);
            const voted=hasVotedForTank(s,user&&user.uid,votes);
            return(
              <div key={s.id} className="showcase-slide" style={{flexShrink:0,width:142,borderRadius:16,overflow:"hidden",background:C.card,border:`1px solid ${contest&&voted?C.primary:C.border}`,cursor:"pointer"}} onClick={()=>setFullImg(s)}>
                <div style={{position:"relative",height:104}}>
                  <TankSlides imgs={imgs} alt={s.ownerName} height={104}/>
                  {contest&&idx===0&&n>0&&<span style={{position:"absolute",top:6,left:6,background:"rgba(251,191,36,.95)",color:"#7c2d12",fontSize:9,fontWeight:800,borderRadius:20,padding:"2px 7px"}}>LEADING</span>}
                  {imgs.length>1&&<span style={{position:"absolute",top:6,right:6,background:"rgba(0,0,0,.55)",color:"#fff",fontSize:9,fontWeight:700,borderRadius:20,padding:"2px 6px"}}>{imgs.length} 📷</span>}
                </div>
                <div style={{padding:"7px 8px"}}>
                  <div style={{fontSize:11,fontWeight:700,color:C.text,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{s.ownerName}</div>
                  {s.caption&&<div style={{fontSize:10,color:C.textSub,lineHeight:1.3,marginTop:2,overflow:"hidden",display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical"}}>{s.caption}</div>}
                  <div style={{fontSize:10,color:contest&&voted?C.primary:C.textSub,fontWeight:700,marginTop:3}}>🗳️ {n} · 🕒 {showcaseHoursLeft(s,now)}h</div>
                </div>
              </div>
            );
          })}
        </div>
      )}
      </React.Fragment>}
      {showUpload&&(
        <div style={{background:C.card,borderRadius:16,padding:"14px",border:`1.5px dashed ${C.accent}`}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,marginBottom:4}}>
            <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:13,fontWeight:800,color:C.text}}>📸 {minePending?"Update pending photos":mineApproved?"Submit replacement photos":"Customer Tank Showcase"}</div>
            <button type="button" className="press" disabled={!anyReward} onClick={()=>{if(anyReward)setRulesOpen(true);}}
              title={anyReward?"View customer tank reward rules":"Both monthly rewards are off"}
              style={{background:anyReward?"#eff6ff":C.bg,color:anyReward?C.primary:C.textSub,border:`1px solid ${anyReward?C.accent:C.border}`,borderRadius:20,padding:"5px 10px",fontSize:10,fontWeight:800,flexShrink:0,cursor:anyReward?"pointer":"not-allowed",opacity:anyReward?1:.65}}>Rules</button>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:7,marginBottom:9}}>
            <div style={{fontSize:10,fontWeight:800,color:contest?"#15803d":C.textSub,background:contest?"#ecfdf5":C.bg,border:`1px solid ${contest?"#a7f3d0":C.border}`,borderRadius:8,padding:"7px 8px",lineHeight:1.35}}>
              🏆 Tank of the month: {contest?"ON":"OFF"}
            </div>
            <div style={{fontSize:10,fontWeight:800,color:streakReward?"#15803d":C.textSub,background:streakReward?"#ecfdf5":C.bg,border:`1px solid ${streakReward?"#a7f3d0":C.border}`,borderRadius:8,padding:"7px 8px",lineHeight:1.35}}>
              🔥 Streak reward: {streakReward?"ON":"OFF"}
            </div>
          </div>
          {streakReward&&streak&&(
            <div style={{fontSize:11,color:"#9a3412",background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:12,padding:"8px 10px",marginBottom:9,lineHeight:1.45}}>
              🔥 <b>{Number(monthlyStreak&&monthlyStreak.current)||0}-day streak</b> · Best {Number(monthlyStreak&&monthlyStreak.best)||0}
            </div>
          )}
          {preview.length>0&&(
            <div style={{display:"flex",gap:7,marginBottom:8,flexWrap:"wrap"}}>
              {preview.map((src,i)=>(
                <div key={i} style={{position:"relative",width:82,height:62,borderRadius:12,overflow:"hidden"}}>
                  <img src={src} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>
                  <button onClick={()=>setPreview(p=>p.filter((_,k)=>k!==i))} style={{position:"absolute",top:3,right:3,background:"rgba(0,0,0,.6)",color:"white",border:"none",borderRadius:8,padding:"1px 6px",fontSize:11,fontWeight:700,cursor:"pointer"}}>×</button>
                </div>
              ))}
            </div>
          )}
          {preview.length<MAX_IMGS&&(
            <label style={{display:"flex",flexDirection:"column",alignItems:"center",gap:5,border:`1.5px dashed ${C.border}`,borderRadius:12,padding:"14px",cursor:"pointer",marginBottom:8,background:C.bg}}>
              <span style={{fontSize:24}}>🐡</span>
              <span style={{fontSize:12,fontWeight:700,color:C.primary}}>Tap to add your tank photo</span>
              <input type="file" accept="image/*" style={{display:"none"}} onChange={e=>{const chosen=Array.from(e.target.files||[]);e.target.value="";void handleFiles(chosen);}}/>
            </label>
          )}
          <div style={{display:"flex",alignItems:"center",gap:8,width:"100%",borderRadius:12,border:`1.5px solid ${C.border}`,padding:"9px 12px",fontSize:13,background:C.bg,marginBottom:6,color:C.text}}>
            <span style={{fontSize:14}}>🐠</span>
            <span style={{fontWeight:700,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{user.name||"Aquarist"}</span>
          </div>
          <input value={caption} onChange={e=>setCaption(e.target.value.slice(0,100))} placeholder="Describe your tank… (optional)"
            style={{width:"100%",borderRadius:12,border:`1.5px solid ${C.border}`,padding:"9px 12px",fontSize:13,outline:"none",background:"white",marginBottom:6}}/>
          {note&&<div style={{fontSize:11,color:note[0]==="⚠"?C.danger:note[0]==="🎉"?C.success:C.primary,fontWeight:600,marginBottom:6}}>{note}</div>}
          <button className="press" onClick={submit} disabled={uploading}
            style={{width:"100%",background:uploading?"#9ca3af":C.primary,color:"white",border:"none",borderRadius:12,padding:"11px",fontSize:13,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
            {uploading?"Uploading…":(minePending?"Update pending tank 🐠":mineApproved?"Send replacement for review 🐠":"Share my tank 🐠")}
          </button>
        </div>
      )}
      {showUpload&&previousWinners&&(previousWinners.vote||previousWinners.streak)&&(
        <div style={{background:"linear-gradient(135deg,#fef3c7,#fde68a)",border:"1px solid #fcd34d",borderRadius:16,padding:"13px",marginTop:10}}>
          <div style={{fontSize:11,color:"#92400e",fontWeight:800,marginBottom:9}}>🏆 {totmMonthLabel(previousMonth)} rewards issued</div>
          <div style={{display:"flex",flexDirection:"column",gap:8}}>
            {previousWinners.vote&&(
              <div style={{background:"rgba(255,255,255,.72)",borderRadius:12,padding:"10px 11px",color:"#78350f",lineHeight:1.5}}>
                <div style={{fontSize:12,fontWeight:800}}>Tank of the month</div>
                <div style={{fontSize:11}}>Receiver's name: <b>{previousWinners.vote.name}</b></div>
                <div style={{fontSize:11}}>Reward coins: <b>{Number(previousWinners.vote.rewardCoins)||0}</b></div>
              </div>
            )}
            {previousWinners.streak&&(
              <div style={{background:"rgba(255,255,255,.72)",borderRadius:12,padding:"10px 11px",color:"#78350f",lineHeight:1.5}}>
                <div style={{fontSize:12,fontWeight:800}}>Longest streak of the month</div>
                <div style={{fontSize:11}}>Receiver name: <b>{previousWinners.streak.name}</b></div>
                <div style={{fontSize:11}}>Reward coins: <b>{Number(previousWinners.streak.rewardCoins)||0}</b></div>
              </div>
            )}
          </div>
        </div>
      )}
      {rulesOpen&&anyReward&&(
        <Portal><div onClick={()=>setRulesOpen(false)} style={{position:"fixed",inset:0,background:"rgba(8,30,33,.65)",zIndex:10000,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
          <div onClick={e=>e.stopPropagation()} className="fade-in" style={{width:"100%",maxWidth:390,maxHeight:"78vh",overflowY:"auto",background:"white",borderRadius:20,padding:"20px",boxShadow:"0 20px 60px rgba(0,0,0,.3)"}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,marginBottom:10}}>
              <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:18,fontWeight:800,color:C.text}}>Customer Tank Reward Rules</div>
              <button type="button" onClick={()=>setRulesOpen(false)} aria-label="Close rules" style={{border:"none",background:C.bg,borderRadius:99,width:32,height:32,fontSize:18,cursor:"pointer"}}>×</button>
            </div>
            <div style={{whiteSpace:"pre-wrap",fontSize:12,lineHeight:1.65,color:C.text}}>{String(settings.tankRewardRules||DEFAULT_SETTINGS.tankRewardRules)}</div>
            <div style={{marginTop:14,background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:12,padding:"10px 12px",fontSize:11,color:"#9a3412",lineHeight:1.5}}>Only photos approved by the store count toward your streak and monthly vote total. Rejected submissions do not count.</div>
          </div>
        </div></Portal>
      )}
      {fullImg&&(()=>{
        const imgs=showcaseImgs(fullImg);
        const n=votesFor(fullImg);
        const voted=hasVotedForTank(fullImg,user&&user.uid,votes);
        const own=user&&fullImg.userUid===user.uid;
        return(
        <Portal>
        <div onClick={()=>setFullImg(null)} style={{position:"fixed",inset:0,background:"rgba(0,0,0,.88)",zIndex:9999,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:20}}>
          <div onClick={e=>e.stopPropagation()}
            onTouchStart={e=>{ swipeStartX.current=e.touches[0]?.clientX??null; }}
            onTouchEnd={e=>{
              if(swipeStartX.current==null) return;
              const dx=(e.changedTouches[0]?.clientX??swipeStartX.current)-swipeStartX.current;
              swipeStartX.current=null;
              if(Math.abs(dx)>45) moveFullTank(dx<0?1:-1);
            }}
            style={{width:"100%",maxWidth:420,display:"flex",flexDirection:"column",alignItems:"center",touchAction:"pan-y"}}>
            <div style={{width:"100%",height:"46vh",borderRadius:16,overflow:"hidden"}}>
              <TankSlides key={fullImg.id} imgs={imgs} alt={fullImg.ownerName} height="100%"/>
            </div>
            {imgs.length>1&&(
              <div style={{display:"flex",gap:6,marginTop:10,overflowX:"auto",width:"100%",justifyContent:"center"}}>
                {imgs.map((src,i)=><img key={i} src={src} alt="" style={{width:52,height:40,objectFit:"cover",borderRadius:8,flexShrink:0,border:"1px solid rgba(255,255,255,.25)"}}/>)}
              </div>
            )}
            <div style={{marginTop:14,textAlign:"center"}}>
              <div style={{color:"white",fontWeight:700,fontSize:14}}>🐠 {fullImg.ownerName}{fullImg.winner?" 🏆":""}</div>
              {fullImg.caption&&<div style={{color:"rgba(255,255,255,.8)",fontSize:12,marginTop:4}}>{fullImg.caption}</div>}
            </div>
            {contest&&(
              <div style={{width:"100%",marginTop:14}}>
                <button className="press" disabled={!!own||voted||voting===fullImg.id} onClick={()=>vote(fullImg)}
                  style={{width:"100%",background:own?"rgba(255,255,255,.14)":voted?"rgba(255,255,255,.92)":C.primary,color:own?"rgba(255,255,255,.7)":voted?C.success:"#fff",
                          border:"none",borderRadius:16,padding:"13px",fontSize:13,fontWeight:800,
                          fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:(own||voted)?"default":"pointer"}}>
                  {own?`🗳️ ${n}`
                     : voting===fullImg.id?"…"
                     : voted?`✓ 🗳️ ${n}`
                     : `🗳️ Vote · ${n}`}
                </button>
                {!user&&<div style={{color:"rgba(255,255,255,.75)",fontSize:11,marginTop:7,textAlign:"center"}}>Sign in to vote.</div>}
              </div>
            )}
          </div>
          <button onClick={()=>setFullImg(null)} style={{marginTop:16,background:"rgba(255,255,255,.18)",border:"1px solid rgba(255,255,255,.3)",borderRadius:12,color:"white",padding:"9px 20px",fontSize:13,fontWeight:700,cursor:"pointer"}}>Close</button>
        </div>
        </Portal>
        );
      })()}
    </div>
  );
}

/* ═══════════════════ TESTIMONIALS ═══════════════════ */
function TestimonialsSection({testimonials=[],user,onSubmit,onSignIn}){
  const [text,setText]=useState("");
  const [rating,setRating]=useState(0);
  const [busy,setBusy]=useState(false);
  const [note,setNote]=useState("");
  const mine=user&&(testimonials||[]).find(t=>t.uid&&t.uid===userKey(user));
  const submit=async()=>{
    const body=text.trim();
    if(!rating){ setNote("⚠ Please select a star rating."); return; }
    if(body.length<4){ setNote("⚠ Please write a few words."); return; }
    setBusy(true); setNote("");
    const t={ id:"ts-"+Date.now()+"-"+Math.random().toString(36).slice(2,6),
      uid:userKey(user)||"", name:(user.name||"Customer").slice(0,40), text:body.slice(0,280),
      rating:Number(rating), createdAt:new Date().toISOString() };
    try{ await onSubmit(t); setText(""); setNote("🎉 Thanks — your testimonial is live!"); }
    catch(e){ setNote("⚠ Couldn't reach our server — please check your connection and try again."); }
    setBusy(false);
  };
  // Every testimonial is public as soon as it is written. Rows left over from when this waited
  // for approval are shown too — the store moderates by deleting, not by holding things back.
  const list=(testimonials||[]).slice(0,12);
  if(!list.length && !user) return null;
  return(
    <div style={{marginBottom:26}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:14}}>
        <span style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:18,fontWeight:800,color:C.text}}>💬 Testimonials</span>
        {list.length>0&&<span style={{fontSize:11,color:C.textSub,fontWeight:600}}>{list.length} from our customers</span>}
      </div>
      {list.length>0&&(
        <div style={{display:"flex",gap:12,overflowX:"auto",paddingBottom:6,marginBottom:12,WebkitOverflowScrolling:"touch"}}>
          {list.map(t=>(
            <div key={t.id} style={{flexShrink:0,width:240,background:C.card,border:`1px solid ${C.border}`,borderRadius:16,padding:"14px 15px",display:"flex",flexDirection:"column",gap:8}}>
              <div style={{display:"flex",gap:2}}>
                {[1,2,3,4,5].map(s=><span key={s} className={s<=(t.rating||5)?"stars":"stars-dim"} style={{fontSize:13}}>★</span>)}
              </div>
              <div style={{fontSize:13,color:C.text,lineHeight:1.5,fontStyle:"italic"}}>“{t.text}”</div>
              <div style={{display:"flex",alignItems:"center",gap:7,marginTop:"auto"}}>
                <span style={{width:24,height:24,borderRadius:"50%",background:C.primary,color:"white",display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,fontWeight:800,flexShrink:0}}>{(t.name||"C").charAt(0).toUpperCase()}</span>
                <span style={{fontSize:12,fontWeight:700,color:C.text}}>{t.name||"Customer"}</span>
              </div>
            </div>
          ))}
        </div>
      )}
      {user?(
        mine?(
          <div style={{background:"#ecfdf5",border:"1px solid #a7f3d0",borderRadius:16,padding:"12px 14px",fontSize:12,color:"#15803d",fontWeight:700}}>✓ Thanks for your testimonial, {(user.name||"").split(" ")[0]||"friend"}! It's live on our home page.</div>
        ):(
          <div style={{background:C.card,borderRadius:16,padding:"14px",border:`1.5px dashed ${C.accent}`}}>
            <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:13,fontWeight:800,color:C.text,marginBottom:8}}>Share review</div>
            <div style={{display:"flex",gap:4,marginBottom:8}}>
              {[1,2,3,4,5].map(s=>(
                <button key={s} onClick={()=>setRating(s)} style={{background:"none",border:"none",cursor:"pointer",fontSize:22,padding:0,lineHeight:1,color:s<=rating?"#f59e0b":"#d1d5db"}}>★</button>
              ))}
            </div>
            <textarea value={text} onChange={e=>setText(e.target.value.slice(0,280))} placeholder="How was your experience with Nemo Aqua Store?"
              rows={3} style={{width:"100%",borderRadius:12,border:`1.5px solid ${C.border}`,padding:"10px 12px",fontSize:13,outline:"none",background:"white",marginBottom:6,resize:"vertical",fontFamily:"'Plus Jakarta Sans',sans-serif"}}/>
            {note&&<div style={{fontSize:11,color:note[0]==="⚠"?C.danger:C.success,fontWeight:600,marginBottom:6}}>{note}</div>}
            <button className="press" onClick={submit} disabled={busy}
              style={{width:"100%",background:busy?"#9ca3af":C.primary,color:"white",border:"none",borderRadius:12,padding:"11px",fontSize:13,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
              {busy?"Posting…":"Share Review"}
            </button>
          </div>
        )
      ):(
        <button className="press" onClick={onSignIn}
          style={{width:"100%",background:C.card,color:C.primary,border:`1.5px dashed ${C.accent}`,borderRadius:12,padding:"12px",fontSize:13,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
          Sign in to write a testimonial
        </button>
      )}
    </div>
  );
}

/* ═══════════════════ BACK ARROW ═══════════════════ */
/* One back arrow for the whole app. It used to be the text character "←", which renders in
   whatever the system font gives it — a hairline next to headings set at weight 800, and a
   different thickness on every platform. Worse, being text it scaled with each button's own
   fontSize, so the same control was a different size on the header, the sheet and the policy
   pages. A stroked path is the same weight and the same size wherever it is placed, and
   inherits `color` so every existing button keeps its own colour. */
function BackArrow({size=20,stroke=2.6}){
  return(
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor"
      strokeWidth={stroke} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"
      style={{display:"block",flexShrink:0}}>
      <path d="M19 12H5"/>
      <path d="M12 19l-7-7 7-7"/>
    </svg>
  );
}

/* One label style for every field in the Admin forms. There were three, all in the same
   scrolling column: 12px uppercase with wide tracking on the product form and two of the
   settings helpers, 10.5px uppercase with narrower tracking on the discount caps, and 11px
   sentence case everywhere else. Uppercase also reads badly on the labels that are a whole
   phrase — "MAX TOTAL DISCOUNT PER ORDER (% OF SUBTOTAL)" is a sentence shouted. */
const ADMIN_LABEL={fontSize:11,fontWeight:800,color:C.textSub,letterSpacing:.1,marginBottom:5};

/* An Admin settings hint is doing two jobs at once: reminding you what a field does while you
   are setting it, and explaining a rule you need to read exactly once. Printed in full under
   every field, the second job crowds out the first — the panel becomes a wall of prose with the
   controls buried inside it, and the owner reported it as most of the screen's text. Not one
   word is cut; the paragraph moves one tap away, where it is still there the day you need it. */
function Hint({children,label="What this does"}){
  const [open,setOpen]=useState(false);
  return(
    <div style={{marginTop:5}}>
      <button className="press" type="button" onClick={()=>setOpen(o=>!o)} aria-expanded={open}
        style={{display:"inline-flex",alignItems:"center",gap:5,background:"none",border:"none",padding:0,cursor:"pointer",fontSize:10,fontWeight:800,color:C.primary,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
        <span aria-hidden="true" style={{display:"inline-flex",alignItems:"center",justifyContent:"center",width:14,height:14,borderRadius:99,border:`1.5px solid ${C.primary}`,fontSize:9,fontWeight:800,lineHeight:1,flexShrink:0}}>i</span>
        {open?"Hide":label}
      </button>
      {open&&<div style={{fontSize:11,color:C.textSub,lineHeight:1.55,marginTop:6,background:C.bg,borderRadius:8,padding:"9px 11px"}}>{children}</div>}
    </div>
  );
}

/* ═══════════════════ PAGE HERO HEADER ═══════════════════ */
/* The coloured banner every secondary page opens with. There were five hand-rolled copies of
   it — Care Guides, About, Contact, a policy page and Request a Product — and they had drifted
   the way copies do: titles at 24 and 25, a decorative circle 130px wide in four of them and
   120px in the fifth at a different opacity, bottom padding of 16, 24 and 26, and a back button
   of 36px, which is under the 44px a thumb can reliably hit. None of it is visible on any one
   screen; all of it is visible moving between them, which is exactly what "unorganised" looks
   like. One component now, with the parts that genuinely differ passed in. */
function HeroHeader({title,subtitle,onBack,right,gradient,children}){
  return(
    <div className="vh-head" style={{background:gradient||`linear-gradient(150deg,${C.primaryDark},${C.primary})`,padding:"52px 18px 20px",color:"white",position:"relative",overflow:"hidden"}}>
      <div aria-hidden="true" style={{position:"absolute",top:-30,right:-20,width:130,height:130,borderRadius:"50%",background:"rgba(255,255,255,.08)",pointerEvents:"none"}}/>
      <div style={{display:"flex",alignItems:"center",gap:12,position:"relative"}}>
        {onBack&&(
          <button className="press" onClick={onBack} aria-label="Back"
            style={{display:"flex",alignItems:"center",justifyContent:"center",background:"rgba(255,255,255,.18)",border:"none",borderRadius:12,width:44,height:44,color:"white",flexShrink:0,cursor:"pointer"}}>
            <BackArrow/>
          </button>
        )}
        <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:22,fontWeight:800,flex:1,minWidth:0,lineHeight:1.2}}>{title}</div>
        {right&&<div style={{flexShrink:0}}>{right}</div>}
      </div>
      {subtitle&&<div style={{fontSize:13,opacity:.9,lineHeight:1.55,maxWidth:340,marginTop:9,position:"relative"}}>{subtitle}</div>}
      {children}
    </div>
  );
}

/* ═══════════════════ RESTOCK ALERT BUTTON ═══════════════════ */
function RestockBtn({product,user,restockSet,onSubscribe}){
  const already=restockSet.includes(product.id);
  if((product.stockCount??DEFAULT_STOCK)>0||product.comingSoon)return null;
  return(
    <button className="press" onClick={()=>{if(!already&&onSubscribe)onSubscribe(product);}} disabled={already}
      style={{display:"flex",alignItems:"center",justifyContent:"center",gap:6,width:"100%",background:already?"#dcfce7":"#fff7ed",color:already?"#15803d":"#c2410c",border:`1.5px solid ${already?"#86efac":"#fed7aa"}`,borderRadius:12,padding:"10px 14px",fontSize:12,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif",marginTop:8}}>
      {already?"🔔 You'll be alerted when it's back!":"🔔 Notify me when back in stock"}
    </button>
  );
}

/* ═══════════════════ CARE GUIDE NOTIFICATION TOGGLE ═══════════════════ */
/* Browser permission is one-way: a page can ask for it, but nothing on the page can hand it
   back. So keying the UI off Notification.permission alone meant that the moment a customer
   said yes, the control became the static words "Notifications on" with no way to change
   their mind — permanently, since clearing it requires digging through browser site settings.
   The switch the customer actually operates is kept here instead. It is a preference, storable
   in every state — granted-but-off, denied, and on a surface with no Notification API at all —
   and the permission only decides whether a note appears explaining that nothing can be
   delivered yet. Nothing about the browser's answer can leave the control stuck. */
const GUIDE_NOTIF_KEY="nemo-guide-notif";
function guideNotifOn(){ try{ return localStorage.getItem(GUIDE_NOTIF_KEY)==="1"; }catch(e){ return false; } }
function setGuideNotifPref(on){ try{ localStorage.setItem(GUIDE_NOTIF_KEY,on?"1":"0"); }catch(e){} }
function GuideNotifBtn(){
  const [perm,setPerm]=useState(notifPermNow);
  const [on,setOn]=useState(guideNotifOn);
  const [note,setNote]=useState("");
  /* The switch shows the customer's own preference, not the browser permission. Those are two
     different facts, and tying the visible state to the permission is what made this control
     dead in the Android app: a WebView has no Notification API at all, so the permission reads
     "unsupported", the button was rendered disabled, and tapping it did nothing in EITHER
     direction with no explanation. The preference is ours and always settable; whether it can
     be delivered right now is a separate line of text underneath. */
  const active = on;
  /* The preference is local so it survives being signed out; the subscription is the server's
     copy of it, and only that can actually reach a phone. Both move together. */
  /* A rejected subscription is reported over whatever the local outcome said. "Saved" is true
     of the preference and useless on its own — the customer wants the notification, not the
     preference, and the server not having the subscription is the one failure that produces
     silence with nothing on screen to explain it. Re-read the stored preference inside the
     callback rather than trusting `v`: a fast on-then-off must not land a warning on a switch
     that is now off. */
  const apply=(v)=>{ setOn(v); setGuideNotifPref(v); syncGuideSub(v,report); };
  const signedIn=()=>{ try{ return !!(FB_AUTH&&FB_AUTH.currentUser); }catch(e){ return false; } };
  /* A refused subscription outranks anything the browser has to say, and must not be overwritten
     by a permission answer that happens to arrive later — the two callbacks race, and losing
     that race hides the only failure that produces silence with no other symptom. Held in a ref
     rather than state because the permission callback reads it at the moment it fires. */
  const subFailed=useRef(false);
  const report=(why)=>{
    subFailed.current = why==="rejected";
    if(subFailed.current&&guideNotifOn()) setNote(NOT_SUBSCRIBED);
  };
  const permNote=(p)=>{ setPerm(p); if(!subFailed.current) setNote(noteFor(p)); };

  /* A preference set before signing in has no owner to file it under. Firebase resolving auth
     is the moment it gets one, so re-file it then — otherwise switching this on and signing in
     afterwards leaves a switch that reads ON and a server that has never heard of you. */
  useEffect(()=>{
    const push=()=>{ if(guideNotifOn()) syncGuideSub(true,report); };
    push();
    window.addEventListener("nemo-fb-ready",push);
    return()=>window.removeEventListener("nemo-fb-ready",push);
  },[]);

  /* Permission can change outside the page — in browser site settings, or in Android's app
     settings for the installed app. Re-read it when the tab comes back and, where the
     Permissions API exists, the moment it actually changes. Without this the control kept
     showing a stale "blocked" after the customer had just allowed it and returned. */
  useEffect(()=>{
    const sync=()=>setPerm(notifPermNow());
    document.addEventListener("visibilitychange",sync);
    let status=null;
    try{
      if(navigator.permissions&&navigator.permissions.query){
        navigator.permissions.query({name:"notifications"})
          .then(st=>{ status=st; st.onchange=sync; }).catch(()=>{});
      }
    }catch(e){}
    return()=>{ document.removeEventListener("visibilitychange",sync); if(status) status.onchange=null; };
  },[]);

  /* One line each. These sit in the corner of a header, not in a paragraph of body text, and
     a sentence that wraps to four lines there reads as an error rather than a receipt. The
     preference is already saved by the time any of them appears — all they have to say is
     what is standing between it and an actual notification. */
  const BLOCKED="Saved. Turn on notifications in settings.";
  /* Inside the app this used to read "the app can't show notifications yet", which is no longer
     true: the installed app receives these through FCM and draws them natively, with no
     Notification API involved. It is only untrue of a build older than the one that added push,
     and for those the useful thing to say is how to fix it. */
  const UNSUPPORTED=(typeof window!=="undefined"&&window.nemoInApp)
    ? "Saved. Update the app to get these."
    : "Saved. This browser can't show notifications.";
  const SIGNED_OUT="Saved. Sign in to get these.";
  /* The server refused the subscription — in practice a missing guideSubs rule. Worded for a
     customer, but it is the owner this is really for: it is the only way to tell a published
     rule from an unpublished one without a console. */
  const NOT_SUBSCRIBED="Saved. Couldn't subscribe you on the server.";
  const noteFor=(p)=> p==="granted"?"" : p==="denied"?BLOCKED : p==="unsupported"?UNSUPPORTED
    : "Saved. Allow it when your browser asks.";
  const toggle=()=>{
    // Turning OFF is only ever a local preference, so it must work in every state.
    if(on){ apply(false); setNote(""); return; }
    /* Turning ON records the preference FIRST and unconditionally. Asking the browser is a
       best effort on top of it: where the API is missing or already denied there is nothing to
       ask, and refusing to store the preference just left the customer tapping a switch that
       never moved. The note says what will actually happen. */
    apply(true);
    /* Signed out there is nobody to send to: the subscription is keyed on the account, not on
       this device, so the preference is kept and nothing else can happen yet. */
    if(!signedIn()){ setNote(SIGNED_OUT); return; }
    /* The installed app is reached through FCM. Its missing Notification API has nothing to do
       with whether this works, so do not ask the browser and do not apologise for it. */
    if(pushCapable()){ setNote(""); return; }
    if(perm==="granted"){ setNote(""); return; }
    if(perm==="denied"||perm==="unsupported"){ setNote(noteFor(perm)); return; }
    setNote("");
    requestNotifPerm(permNote);
  };
  return(
    <div style={{display:"flex",flexDirection:"column",alignItems:"flex-end",gap:5}}>
      <button className="press" onClick={toggle} role="switch" aria-checked={active}
        aria-label={active?"Turn off new-guide notifications":"Turn on new-guide notifications"}
        style={{display:"flex",alignItems:"center",gap:8,background:active?"#dcfce7":C.accentLight,border:`1px solid ${active?"#86efac":C.border}`,borderRadius:12,padding:"7px 12px",fontSize:11,fontWeight:700,color:active?"#15803d":C.primary,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>
        <span>{active?"🔔":"🔕"}</span>
        {/* One word. The switch beside it is what says on or off — spelling that out again in
            the label made a control the size of a sentence, and the aria-label still carries
            the full meaning for anyone who cannot see the track. */}
        <span>Notification</span>
        {/* A visible track, so it reads as something that can be switched back */}
        <span style={{width:26,height:15,borderRadius:99,background:active?"#22c55e":"#cbd5e1",position:"relative",flexShrink:0,transition:"background .2s ease"}}>
          <span style={{position:"absolute",top:2,left:active?13:2,width:11,height:11,borderRadius:"50%",background:"#fff",transition:"left .2s ease"}}/>
        </span>
      </button>
      {/* This switch lives in the Care Guides header, which is a blue gradient. C.textSub is a
          grey chosen to sit on the off-white page background and is close to unreadable there,
          so the note carries its own contrast instead of borrowing the page's. */}
      {note&&<div role="status" style={{fontSize:10,color:"#ffffff",fontWeight:700,lineHeight:1.45,maxWidth:200,textAlign:"right",background:"rgba(2,32,71,.34)",borderRadius:8,padding:"5px 8px"}}>{note}</div>}
    </div>
  );
}

function StockBadge({stockCount}){
  // Show the exact count only once it drops below 10 (low-stock urgency). Otherwise just "In Stock".
  const m = stockCount<=0 ? {c:"#dc2626",bg:"#fee2e2",l:"✕ Out of Stock"}
          : stockCount<10 ? {c:"#c2410c",bg:"#fff7ed",l:`⚠ Only ${stockCount} left`}
          : {c:"#15803d",bg:"#dcfce7",l:"● In Stock"};
  return <span style={{fontSize:10,fontWeight:700,color:m.c,background:m.bg,padding:"3px 9px",borderRadius:20}}>{m.l}</span>;
}
function StatusBadge({status}){
  const m={"Awaiting Payment":{c:"#b45309",bg:"#fef3c7",icon:"⏳"},"Payment Review":{c:"#7c3aed",bg:"#ede9fe",icon:"🔎"},Placed:{c:"#1d4ed8",bg:"#dbeafe",icon:"📋"},Confirmed:{c:"#15803d",bg:"#dcfce7",icon:"✅"},Shipped:{c:"#c2410c",bg:"#fff7ed",icon:"🚚"},Delivered:{c:"#15803d",bg:"#dcfce7",icon:"🎉"},Cancelled:{c:"#b91c1c",bg:"#fee2e2",icon:"✕"}};
  const s=m[status]||m.Placed;
  return <span style={{fontSize:10,fontWeight:700,color:s.c,background:s.bg,padding:"3px 10px",borderRadius:20}}>{s.icon} {status}</span>;
}
/* The stage badge answers "where has my order got to?". An order nobody has paid for has not
   got anywhere — badging it "Orders Placed" told the customer the store was already acting on
   it, which is exactly what "Pay later" means it is not. While payment is still outstanding the
   badge shows the payment state instead. Only the badge changes: the order still groups under
   Orders Placed in the tabs, which is where a customer goes looking for it. The override is
   scoped to that one stage so a cancelled or archived order can never be relabelled as pending. */
/* The stage names are tab headings and are plural on purpose -- "Orders Placed" is a drawer
   with orders in it. On one order the badge has to name that order, so it is looked up here
   rather than printed straight from the stage. */
const ORDER_BADGE={
  "Order Placed":{c:"#1d4ed8",bg:"#dbeafe",icon:"📦"},
  Shipped:{c:"#c2410c",bg:"#fff7ed",icon:"🚚"},
  Delivered:{c:"#15803d",bg:"#dcfce7",icon:"✓"},
  Returned:{c:"#7c3aed",bg:"#ede9fe",icon:"↩️"},
  Replaced:{c:"#0369a1",bg:"#e0f2fe",icon:"🔁"},
  Refunded:{c:"#0369a1",bg:"#e0f2fe",icon:"₹"},
  Cancelled:{c:"#b91c1c",bg:"#fee2e2",icon:"✕"},
  Closed:{c:"#475569",bg:"#f1f5f9",icon:"🗂️"},
};
const STAGE_BADGE_LABEL={"Orders Placed":"Order Placed","Past Orders":"Closed"};
function CustomerStageBadge({order}){
  const stage=customerOrderStage(order);
  const unpaid=stage==="Orders Placed"?{
    "Awaiting Payment":{c:"#b45309",bg:"#fef3c7",icon:"⏳"},
    "Payment Review":{c:"#7c3aed",bg:"#ede9fe",icon:"🔎"},
  }[order&&order.status]:null;
  /* Once an order has reached the customer, the outcome is more use than the stage: a
     cancelled, returned or replaced order was badged "Past Orders" alongside one that was
     simply delivered and left alone. "Closed" is only the fallback for an order that was
     filed away without ever reaching any of those endings. */
  const outcome=(stage==="Past Orders"||stage==="Delivered")?customerOrderOutcome(order):"";
  const label=unpaid?order.status:(outcome||STAGE_BADGE_LABEL[stage]||stage);
  const m=unpaid||ORDER_BADGE[label]||ORDER_BADGE.Closed;
  return <span style={{display:"inline-flex",alignItems:"center",gap:5,background:m.bg,color:m.c,borderRadius:20,padding:"4px 10px",fontSize:10,fontWeight:800,whiteSpace:"nowrap"}}>{m.icon} {label}</span>;
}
function CategoryPills({selected,onSelect,all,counts}){
  const cats=shopCategories();
  const list=all?["All",...cats]:cats;
  const icons={All:"🌊",...Object.fromEntries(cats.map(c=>[c,CAT_META[c].emoji]))};
  return(
    <div style={{display:"flex",gap:8,overflowX:"auto",paddingBottom:4}}>
      {list.map(c=>(
        <button key={c} className="press" onMouseMove={magnetMove} onMouseLeave={magnetLeave} onClick={()=>onSelect(c)} style={{
          flexShrink:0,background:selected===c?"#ffffff":"#f8fafc",color:selected===c?C.text:C.textSub,
          border:`2px solid ${selected===c?C.accent:"transparent"}`,borderRadius:99,padding:"8px 16px",
          fontSize:12,fontWeight:selected===c?700:600,fontFamily:"'Plus Jakarta Sans',sans-serif",transition:"all .3s cubic-bezier(0.34,1.56,0.64,1)",
          boxShadow:selected===c?"0 6px 18px rgba(14,165,233,.16)":"none",
          display:"flex",alignItems:"center",gap:5}}>
          <span>{icons[c]}</span>{c}
          {counts&&<span style={{marginLeft:3,background:selected===c?"rgba(14,165,233,.14)":C.border,color:selected===c?C.primary:C.textSub,borderRadius:12,padding:"0 6px",fontSize:10,fontWeight:800,minWidth:14,textAlign:"center"}}>{counts[c]||0}</span>}
        </button>
      ))}
    </div>
  );
}

/* ═══════════════════ REVIEW COMPONENTS ═══════════════════ */
function ReviewStars({value,onChange,size=18}){
  const [hov,setHov]=useState(0);
  const interactive=!!onChange;
  return(
    <div style={{display:"flex",gap:3}}>
      {[1,2,3,4,5].map(s=>(
        <span key={s}
          onClick={()=>onChange&&onChange(s)}
          onMouseEnter={()=>interactive&&setHov(s)}
          onMouseLeave={()=>interactive&&setHov(0)}
          style={{fontSize:size,cursor:interactive?"pointer":"default",transition:"color .12s",
            color:s<=(hov||value)?"#f59e0b":"#d1d5db",lineHeight:1,display:"block"}}>★</span>
      ))}
    </div>
  );
}

function RatingSummary({reviews,avgRating}){
  const counts=[5,4,3,2,1].map(s=>({star:s,count:reviews.filter(r=>r.rating===s).length}));
  const total=reviews.length;
  return(
    <div style={{display:"flex",gap:16,alignItems:"center",background:C.card,borderRadius:16,padding:"16px",border:`1px solid ${C.border}`,marginBottom:16}}>
      {/* Big score */}
      <div style={{textAlign:"center",flexShrink:0}}>
        <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:40,fontWeight:800,color:C.text,lineHeight:1}}>{avgRating.toFixed(1)}</div>
        <ReviewStars value={Math.round(avgRating)} size={14}/>
        <div style={{fontSize:11,color:C.textSub,marginTop:4}}>{total} review{total!==1?"s":""}</div>
      </div>
      {/* Bar breakdown */}
      <div style={{flex:1}}>
        {counts.map(({star,count})=>{
          const pct=total>0?(count/total)*100:0;
          return(
            <div key={star} style={{display:"flex",alignItems:"center",gap:6,marginBottom:5}}>
              <span style={{fontSize:10,color:C.textSub,minWidth:10,textAlign:"right"}}>{star}</span>
              <span style={{fontSize:10,color:"#f59e0b"}}>★</span>
              <div style={{flex:1,height:6,borderRadius:4,background:C.border,overflow:"hidden"}}>
                <div style={{height:"100%",borderRadius:4,background:"#f59e0b",width:pct+"%",transition:"width .4s ease"}}/>
              </div>
              <span style={{fontSize:10,color:C.textSub,minWidth:16,textAlign:"right"}}>{count}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ReviewForm({onSubmit,onCancel,user,orderId:oid,preset=0}){
  const [rating,setRating]   = useState(preset||0);
  const [aspects,setAspects] = useState({}); // optional per-aspect stars: health/packing/speed/value
  const [comment,setComment] = useState("");
  const [photos,setPhotos]   = useState([]); // array of compressed JPEG data-URLs
  const [photoBusy,setPhotoBusy]=useState(false);
  const [errs,setErrs]       = useState({});
  const [saving,setSaving]   = useState(false);
  const name = user?.name || "";
  const MAX_PHOTOS=3;

  const addPhotos=async(files)=>{
    const list=Array.from(files||[]).slice(0,MAX_PHOTOS-photos.length);
    if(!list.length) return;
    setPhotoBusy(true);
    const out=[];
    for(const f of list){ try{ out.push(await compressImage(f,900,0.72)); }catch(e){} }
    setPhotos(p=>[...p,...out].slice(0,MAX_PHOTOS));
    setPhotoBusy(false);
  };

  const validate=()=>{
    const e={};
    if(!rating)e.rating="Please select a star rating";
    // Written review is optional — a star rating alone is enough.
    setErrs(e);
    return !Object.keys(e).length;
  };

  const submit=async()=>{
    if(!validate())return;
    setSaving(true);
    const asp={}; Object.keys(aspects).forEach(k=>{ if(aspects[k]>0) asp[k]=aspects[k]; });
    // finally, so a failed write can never leave the button spinning with no way out
    try{
      await onSubmit({id:uid("rev"),name:name||"Customer",rating,comment:comment.trim(),photos,date:new Date().toISOString(),orderId:oid,verified:true,...(Object.keys(asp).length?{aspects:asp}:{})});
    }catch(err){ console.error("review submit",err); setErrs({submit:"Couldn't post your review — please try again"}); }
    finally{ setSaving(false); }
  };

  return(
    <div className="slide-up" style={{background:C.card,borderRadius:20,padding:"18px",border:`1.5px solid ${C.border}`,marginBottom:16}}>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}>
        <span style={{fontSize:10,fontWeight:800,color:C.success,background:"#dcfce7",padding:"3px 9px",borderRadius:20}}>✓ VERIFIED PURCHASE</span>
      </div>
      <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:16,fontWeight:800,color:C.text,marginBottom:14}}>Write a Review</div>

      {/* Star picker */}
      <div style={{marginBottom:14}}>
        <div style={{fontSize:11,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:8}}>Your Rating</div>
        <ReviewStars value={rating} onChange={setRating} size={34}/>
        <div style={{fontSize:11,color:"#f59e0b",fontWeight:600,marginTop:6,minHeight:16}}>
          {rating===1?"😐 Poor":rating===2?"🙁 Fair":rating===3?"😊 Good":rating===4?"😄 Great":rating===5?"🤩 Excellent":""}
        </div>
        {errs.rating&&<div style={{fontSize:11,color:C.danger,fontWeight:600}}>{errs.rating}</div>}
      </div>

      {/* Aspect ratings — optional, Flipkart-style */}
      <div style={{marginBottom:16,background:"#f8fafc",border:`1px solid ${C.border}`,borderRadius:16,padding:"12px 14px"}}>
        <div style={{fontSize:11,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:10}}>Rate the details <span style={{fontWeight:400,textTransform:"none"}}>(optional)</span></div>
        {[["health","🐟 Fish / Product Condition"],["packing","📦 Packing Quality"],["speed","🚚 Delivery Speed"],["value","💰 Value for Money"]].map(([k,label])=>(
          <div key={k} style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,marginBottom:8}}>
            <span style={{fontSize:12,color:C.text,fontWeight:600}}>{label}</span>
            <ReviewStars value={aspects[k]||0} onChange={v=>setAspects(a=>({...a,[k]:v}))} size={19}/>
          </div>
        ))}
      </div>

      {/* Comment */}
      <div style={{marginBottom:16}}>
        <div style={{fontSize:11,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:6}}>Your Review <span style={{fontWeight:400,textTransform:"none",letterSpacing:0}}>(optional)</span></div>
        <textarea value={comment} onChange={e=>setComment(e.target.value.slice(0,500))} rows={4}
          placeholder="Optional — share how the quality & condition were, if you'd like."
          style={{width:"100%",borderRadius:12,border:`1.5px solid ${errs.comment?C.danger:C.border}`,padding:"11px 14px",fontSize:13,outline:"none",resize:"none",lineHeight:1.6,background:C.bg}}/>
        <div style={{display:"flex",justifyContent:"space-between",marginTop:3}}>
          {errs.comment?<span style={{fontSize:11,color:C.danger,fontWeight:600}}>{errs.comment}</span>:<span/>}
          <span style={{fontSize:11,color:C.textSub}}>{comment.length}/500</span>
        </div>
      </div>

      {/* Photo upload */}
      <div style={{marginBottom:16}}>
        <div style={{fontSize:11,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:8}}>Add Photos <span style={{textTransform:"none",letterSpacing:0,fontWeight:600,color:C.textSub}}>(optional · shows others your fish arrived happy)</span></div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          {photos.map((src,i)=>(
            <div key={i} style={{position:"relative",width:64,height:64,borderRadius:12,overflow:"hidden",border:`1px solid ${C.border}`}}>
              <img src={src} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>
              <button className="press" onClick={()=>setPhotos(p=>p.filter((_,j)=>j!==i))}
                style={{position:"absolute",top:2,right:2,width:18,height:18,borderRadius:"50%",background:"rgba(0,0,0,.6)",color:"white",border:"none",fontSize:11,lineHeight:1,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>×</button>
            </div>
          ))}
          {photos.length<MAX_PHOTOS&&(
            <label style={{width:64,height:64,borderRadius:12,border:`1.5px dashed ${C.border}`,background:C.bg,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",cursor:"pointer",color:C.textSub,gap:2}}>
              {photoBusy?<Spinner/>:<><span style={{fontSize:18,lineHeight:1}}>📷</span><span style={{fontSize:9,fontWeight:700}}>Add</span></>}
              <input type="file" accept="image/*" multiple style={{display:"none"}} onChange={e=>{addPhotos(e.target.files);e.target.value="";}}/>
            </label>
          )}
        </div>
      </div>

      <div style={{display:"flex",gap:10}}>
        <button className="press" onClick={onCancel}
          style={{flex:1,padding:"12px",borderRadius:12,border:`1.5px solid ${C.border}`,background:"transparent",color:C.textSub,fontSize:13,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
          Cancel
        </button>
        {errs.submit&&<div style={{fontSize:12,color:C.danger,fontWeight:700,marginBottom:8,textAlign:"center"}}>{errs.submit}</div>}
        <button className="press" onClick={submit} disabled={saving}
          style={{flex:2,padding:"12px",borderRadius:12,border:"none",background:C.primary,color:"white",fontSize:13,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif",display:"flex",alignItems:"center",justifyContent:"center",gap:8,opacity:saving?.7:1}}>
          {saving?<><Spinner/>Submitting…</>:"⭐ Submit Review"}
        </button>
      </div>
    </div>
  );
}

/* ═══════════════════ COUNTDOWN BANNER ═══════════════════ */
function CountdownBanner({endsAt, title="Limited Time Offer", subtitle="Don't miss out on this exclusive deal!", stockNote, onShop}){
  const [now,setNow]=useState(Date.now());
  useEffect(()=>{const i=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(i);},[]);
  const end = new Date(endsAt).getTime();
  const diff = Math.max(0, end-now);
  const d = Math.floor(diff/(1000*60*60*24));
  const h = Math.floor((diff/(1000*60*60))%24);
  const m = Math.floor((diff/(1000*60))%60);
  const s = Math.floor((diff/1000)%60);
  const pad = n => String(n).padStart(2,"0");
  const cells = [{v:pad(d),l:"Days"},{v:pad(h),l:"Hours"},{v:pad(m),l:"Mins"},{v:pad(s),l:"Secs"}];
  if(diff<=0) return null;
  return(
    <div style={{background:`linear-gradient(135deg,${C.coral} 0%,#ff8a40 100%)`,borderRadius:20,padding:"18px 16px",color:"white",position:"relative",overflow:"hidden"}}>
      <div style={{position:"absolute",top:-30,right:-30,width:120,height:120,borderRadius:"50%",background:"rgba(255,255,255,.1)"}}/>
      <div style={{position:"absolute",bottom:-40,left:-30,width:100,height:100,borderRadius:"50%",background:"rgba(255,255,255,.08)"}}/>
      <div style={{position:"relative"}}>
        <div style={{display:"inline-block",background:"rgba(0,0,0,.18)",borderRadius:20,padding:"3px 10px",fontSize:10,fontWeight:800,letterSpacing:1.5,marginBottom:8}}>⚡ OFFER</div>
        <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:20,fontWeight:800,marginBottom:2}}>{title}</div>
        <div style={{fontSize:12,opacity:.88,marginBottom:14}}>{subtitle}</div>
        <div style={{fontSize:11,fontWeight:700,opacity:.85,marginBottom:6,letterSpacing:.8}}>Ends in:</div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:6,marginBottom:stockNote?12:14}}>
          {cells.map((c,i)=>(
            <div key={i} className={c.l==="Secs"?"countdown-cell":""} style={{background:"rgba(255,255,255,.95)",color:C.coral,borderRadius:12,padding:"8px 4px",textAlign:"center"}}>
              <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:20,fontWeight:800,lineHeight:1}}>{c.v}</div>
              <div style={{fontSize:9,fontWeight:700,color:"#7a1a08",marginTop:3,textTransform:"uppercase",letterSpacing:.8}}>{c.l}</div>
            </div>
          ))}
        </div>
        {stockNote&&<div style={{fontSize:12,fontWeight:700,marginBottom:12,opacity:.95}}>🔥 {stockNote}</div>}
        <button className="press" onClick={onShop}
          style={{background:"white",color:C.coral,border:"none",borderRadius:12,padding:"11px 22px",fontSize:13,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",boxShadow:"0 4px 14px rgba(0,0,0,.18)"}}>
          Shop Now →
        </button>
      </div>
    </div>
  );
}

/* ═══════════════════ VARIANT PICKER ═══════════════════ */
function VariantPicker({product, variants, selectedId, onSelect, cart=[], addToCart}){
  const onSale=activeDiscount(product)>0;
  // Each option is its own cart line (same key format addToCart uses), so a shopper can build an
  // order of several different options without going back and forth between them.
  const qtyOf=v=>(cart.find(i=>i.key===product.id+"|"+v.id)?.qty)||0;
  const stop=e=>{ e.stopPropagation(); };
  const stepBtn={background:"none",border:"none",fontSize:16,fontWeight:700,lineHeight:1,cursor:"pointer",padding:"0 2px"};
  return(
    <div style={{marginBottom:18}}>
      <div style={{fontSize:12,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:10}}>{variantHeading(product)}</div>
      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        {variants.map(v=>{
          const sel = v.id===selectedId;
          const price = variantEffPrice(product, v);
          const orig  = variantBasePrice(product, v);
          // Sold out = flagged by the admin OR run down to zero on its own count.
          const out  = variantSoldOut(product, v);
          const left = hasVariantStock(product) ? variantStockOf(product, v) : null;
          const q    = qtyOf(v);
          const maxV = Math.max(0, Math.min(variantStockOf(product, v), MAX_PER_ORDER));
          // A row is no longer a <button>: it holds the +/- controls, and a button can't nest
          // buttons. Kept keyboard-reachable and announced as a radio in its place.
          return(
            <div key={v.id} role="radio" aria-checked={sel} aria-disabled={out} tabIndex={out?-1:0}
              onClick={()=>!out&&onSelect&&onSelect(v)}
              onKeyDown={e=>{ if(!out&&(e.key==="Enter"||e.key===" ")){ e.preventDefault(); onSelect&&onSelect(v); } }}
              style={{
                width:"100%",textAlign:"left",
                background: out?"#f3f4f6":sel?C.accentLight:C.card,
                border:`1.5px solid ${sel?C.primary:C.border}`,
                borderRadius:16, padding:"12px 14px",
                display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,
                opacity:out?.55:1,cursor:out?"not-allowed":"pointer",
                fontFamily:"'Plus Jakarta Sans',sans-serif",
              }}>
              <div style={{display:"flex",alignItems:"center",gap:10,flex:1,minWidth:0}}>
                <div style={{width:20,height:20,borderRadius:"50%",border:`2px solid ${sel?C.primary:C.border}`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                  {sel&&<div style={{width:10,height:10,borderRadius:"50%",background:C.primary}}/>}
                </div>
                <div style={{minWidth:0}}>
                  <div style={{fontSize:13,fontWeight:600,color:C.text,lineHeight:1.3}}>{v.label}</div>
                  {!out&&(
                    <div style={{display:"flex",alignItems:"center",gap:6,marginTop:3,flexWrap:"wrap"}}>
                      {onSale&&<span style={{fontSize:11,color:C.textSub,textDecoration:"line-through"}}>₹{orig}</span>}
                      <span style={{fontFamily:PRICE_FONT,fontSize:14,fontWeight:800,color:C.primary}}>₹{price}</span>
                      {left!=null&&left<=3&&<span style={{fontSize:10,fontWeight:800,color:C.coral}}>Only {left} left</span>}
                    </div>
                  )}
                </div>
              </div>
              {out
                ? <span style={{fontSize:11,fontWeight:700,color:C.danger,flexShrink:0}}>Sold out</span>
                : !addToCart
                  ? null
                  : q>0
                    ? <div onClick={stop} style={{display:"flex",alignItems:"center",gap:9,background:C.bg,borderRadius:99,padding:"5px 11px",border:`1.5px solid ${C.border}`,flexShrink:0}}>
                        <button className="press" aria-label={`Remove one ${v.label}`} onClick={e=>{stop(e);addToCart(product,-1,v);}}
                          style={{...stepBtn,color:C.primary}}>−</button>
                        <span style={{fontSize:14,fontWeight:800,color:C.text,minWidth:14,textAlign:"center"}}>{q}</span>
                        <button className="press" aria-label={`Add another ${v.label}`} disabled={q>=maxV} onClick={e=>{stop(e);onSelect&&onSelect(v);addToCart(product,1,v);}}
                          style={{...stepBtn,color:q>=maxV?C.textSub:C.primary,opacity:q>=maxV?.5:1,cursor:q>=maxV?"default":"pointer"}}>+</button>
                      </div>
                    : <button className="press" aria-label={`Add ${v.label} to cart`} onClick={e=>{stop(e);onSelect&&onSelect(v);addToCart(product,1,v);}}
                        style={{flexShrink:0,background:C.primary,color:"white",border:"none",borderRadius:99,padding:"7px 14px",fontSize:12,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>+ Add</button>}
            </div>
          );
        })}
      </div>
      {/* What this option set adds up to, so a mixed order is legible before checkout. */}
      {(()=>{
        const lines=variants.map(v=>({v,q:qtyOf(v)})).filter(x=>x.q>0);
        if(lines.length<2) return null;
        const units=lines.reduce((a,x)=>a+x.q,0);
        const sum=lines.reduce((a,x)=>a+x.q*variantEffPrice(product,x.v),0);
        return(
          <div style={{marginTop:10,padding:"9px 13px",background:C.accentLight,border:`1px solid ${C.border}`,borderRadius:12,display:"flex",alignItems:"center",justifyContent:"space-between",gap:10}}>
            <span style={{fontSize:11,fontWeight:700,color:C.text}}>{lines.length} options · {units} item{units!==1?"s":""} in cart</span>
            <span style={{fontFamily:PRICE_FONT,fontSize:14,fontWeight:800,color:C.primary}}>₹{sum}</span>
          </div>
        );
      })()}
    </div>
  );
}

/* ═══════════════════ GOOGLE AUTH ═══════════════════ */
function PhoneAuth({onSuccess, onBack, mode="signin", settings}){
  const [busy,setBusy]   = useState(false);
  const [err,setErr]     = useState("");
  const [showDemo,setShowDemo] = useState(false);

  const doGoogle = async () => {
    setErr(""); setBusy(true);
    try{
      const u = await googleSignIn();
      onSuccess({...u, keep:true});
    }catch(e){
      const code = e?.code||e?.message||"";
      if(String(code).includes("redirecting")) return; // page is navigating to Google
      if(code==="offline" || !FB_OK){
        /* googleSignIn already waited out the SDK load, so reaching here on a deployed site
           means the connection is genuinely down — not that this is a preview build. Telling a
           real customer to "use a demo account" was nonsense on the live store, so the demo
           accounts are offered only where they make sense: a local/preview host. */
        const preview=/^(localhost|127\.0\.0\.1)$/.test(location.hostname)||location.protocol==="file:";
        setShowDemo(preview);
        setErr(preview
          ? "Google sign-in needs the live (deployed) site. Use a demo account below to preview."
          : "Couldn't reach Google sign-in — check your connection and try again in a moment.");
      } else if(String(code).includes("popup-closed") || String(code).includes("cancelled")){
        setErr("Sign-in cancelled. Please try again.");
      } else if(String(code).includes("unauthorized-domain")){
        setErr("This domain isn't authorized yet. Add it in Firebase → Authentication → Settings → Authorized domains.");
      } else if(String(code).includes("network-request-failed")){
        setErr("Network hiccup during sign-in. Please try again.");
      } else if(String(code).includes("account-exists-with-different-credential")){
        setErr("That email is already registered with a different sign-in method.");
      } else if(String(code).includes("user-disabled")){
        setErr("This account has been disabled. Please contact us on WhatsApp.");
      } else if(String(code).includes("too-many-requests")){
        setErr("Too many attempts. Please wait a minute and try again.");
      } else {
        setErr("Couldn't sign in. Please try again.");
      }
    }finally{ setBusy(false); }
  };

  return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",minHeight:"100%",background:C.bg,padding:"56px 22px 32px",position:"relative"}}>
      <button className="press" onClick={onBack} style={{position:"absolute",top:20,left:14,background:"none",border:"none",fontSize:24,color:C.textSub,width:44,height:44,display:"flex",alignItems:"center",justifyContent:"center"}}><BackArrow/></button>

      <div style={{textAlign:"center",marginBottom:30,marginTop:20}}>
        <img src={STORE_LOGO} alt="Nemo" onError={e=>{if(!e.target.dataset.fb){e.target.dataset.fb='1';e.target.src=NEMO_FALLBACK;}}} style={{width:130,height:130,objectFit:"contain",margin:"0 auto",display:"block",filter:"drop-shadow(0 10px 24px rgba(8,54,64,.35))"}}/>
        <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:24,fontWeight:800,color:C.text,marginTop:16,marginBottom:6}}>
          {mode==="checkout"?"Sign in to checkout":"Welcome to Nemo"}
        </div>
        <div style={{fontSize:13,color:C.textSub,lineHeight:1.55,maxWidth:300,margin:"0 auto"}}>
          Sign in with Google to place orders, track delivery, and review your purchases.
        </div>
      </div>

      <div style={{maxWidth:360,width:"100%",margin:"0 auto"}}>
        <button className="press" onClick={doGoogle} disabled={busy}
          style={{width:"100%",display:"flex",alignItems:"center",justifyContent:"center",gap:12,background:"white",border:`1.5px solid ${C.border}`,borderRadius:16,padding:"15px",cursor:"pointer",fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:14,fontWeight:700,color:C.text,boxShadow:"0 2px 10px rgba(0,0,0,.05)",opacity:busy?.7:1}}>
          {busy?<Spinner/>:<svg width="22" height="22" viewBox="0 0 48 48"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg>}
          {/* The spinner alone left the label reading "Continue with Google" while the tap was
              already being handled, which on a slow connection looks like nothing happened and
              invites a second tap. Say what is going on. */}
          {busy?"Signing you in…":"Continue with Google"}
        </button>

        {err&&<div style={{fontSize:12,color:showDemo?C.textSub:C.danger,fontWeight:500,marginTop:14,textAlign:"center",lineHeight:1.5,background:showDemo?C.accentLight:"transparent",borderRadius:12,padding:showDemo?"10px 14px":0}}>{err}</div>}

        {!showDemo&&(
          <button className="press" onClick={()=>setShowDemo(true)}
            style={{width:"100%",marginTop:12,display:"flex",alignItems:"center",justifyContent:"center",gap:8,background:"transparent",border:`1.5px dashed ${C.border}`,borderRadius:16,padding:"13px",cursor:"pointer",fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:13,fontWeight:700,color:C.textSub}}>
            👀 Explore with a demo account
          </button>
        )}
        {showDemo&&(
          <div style={{fontSize:11,color:C.textSub,textAlign:"center",marginTop:14,lineHeight:1.5,background:C.accentLight,borderRadius:12,padding:"10px 14px"}}>
            Demo mode — browse and try every feature. Demo orders are simulated on this device only and are <b>not</b> real purchases.
          </div>
        )}
        {showDemo&&(
          <div style={{marginTop:16}}>
            {DEMO_GOOGLE_ACCOUNTS.map(acc=>(
              <button key={acc.email} className="press" onClick={()=>onSuccess({name:acc.name,phone:acc.phone,email:acc.email,method:"demo",loginAt:new Date().toISOString(),keep:true})}
                style={{width:"100%",display:"flex",alignItems:"center",gap:12,background:"white",border:`1.5px solid ${C.border}`,borderRadius:16,padding:"12px 14px",marginBottom:10,cursor:"pointer",fontFamily:"'Plus Jakarta Sans',sans-serif",textAlign:"left"}}>
                <span style={{width:34,height:34,borderRadius:"50%",background:acc.color,color:"white",display:"flex",alignItems:"center",justifyContent:"center",fontSize:14,fontWeight:800,flexShrink:0}}>{acc.name.charAt(0)}</span>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontSize:13,fontWeight:700,color:C.text}}>{acc.name}</div>
                  <div style={{fontSize:11,color:C.textSub,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{acc.email}</div>
                </div>
              </button>
            ))}
          </div>
        )}

        <div style={{fontSize:11,color:C.textSub,textAlign:"center",marginTop:18,lineHeight:1.55}}>
          By continuing you agree to our terms.<br/>We'll use your details only for orders &amp; delivery updates.
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════ SORT · FILTER SHEET ═══════════════════ */
function SortFilterSheet({open, onClose, sort, setSort, priceMax, priceCap, setPriceMax, availability, setAvailability, onClear, count}){
  if(!open) return null;
  return(
    <Portal>
    <div onClick={onClose} className="drawer-overlay" style={{position:"fixed",inset:0,background:"rgba(10,36,38,.42)",zIndex:9000,display:"flex",alignItems:"stretch",justifyContent:"flex-start",animation:"fadeIn .18s ease"}}>
      <div onClick={e=>e.stopPropagation()} className="drawer-panel"
        style={{background:C.card,width:"86%",maxWidth:340,height:"100%",padding:"22px 20px 28px",overflowY:"auto",boxShadow:"4px 0 30px rgba(10,36,38,.25)"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18}}>
          <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:20,fontWeight:800,color:C.text}}>Filter &amp; Sort</div>
          <button className="press" onClick={onClose} style={{background:C.bg,border:`1px solid ${C.border}`,borderRadius:12,width:34,height:34,fontSize:16,color:C.textSub,cursor:"pointer"}}>✕</button>
        </div>
        <button className="press" onClick={onClear} style={{background:"none",border:"none",fontSize:12,fontWeight:700,color:C.accent,fontFamily:"'Plus Jakarta Sans',sans-serif",padding:0,marginBottom:18,cursor:"pointer"}}>↺ Clear all filters</button>

        <div style={{fontSize:11,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:8}}>Sort by</div>
        <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:22}}>
          {SORT_OPTS.map(o=>(
            <button key={o.id} className="press" onClick={()=>setSort(o.id)}
              style={{padding:"8px 14px",borderRadius:20,border:`1.5px solid ${sort===o.id?C.primary:C.border}`,background:sort===o.id?C.primary:"transparent",color:sort===o.id?"white":C.textSub,fontSize:12,fontWeight:600,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
              {o.label}
            </button>
          ))}
        </div>

        <div style={{fontSize:11,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:8}}>Availability</div>
        <div style={{display:"flex",gap:8,marginBottom:22}}>
          {[{id:"all",l:"All"},{id:"instock",l:"In stock"},{id:"limited",l:"Limited"}].map(o=>(
            <button key={o.id} className="press" onClick={()=>setAvailability(o.id)}
              style={{flex:1,padding:"9px 12px",borderRadius:16,border:`1.5px solid ${availability===o.id?C.primary:C.border}`,background:availability===o.id?C.primary:"transparent",color:availability===o.id?"white":C.textSub,fontSize:12,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
              {o.l}
            </button>
          ))}
        </div>

        <div style={{fontSize:11,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:8}}>Max Price</div>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:6}}>
          <span style={{fontSize:12,color:C.textSub}}>₹0</span>
          <span style={{fontFamily:PRICE_FONT,fontSize:16,fontWeight:800,color:C.primary}}>₹{priceMax}</span>
          <span style={{fontSize:12,color:C.textSub}}>₹{priceCap}</span>
        </div>
        <input type="range" min={0} max={priceCap} step={50} value={priceMax} onChange={e=>setPriceMax(Number(e.target.value))}
          style={{width:"100%",accentColor:C.primary,marginBottom:24}}/>

        <button className="press" onClick={onClose}
          style={{width:"100%",background:C.primary,color:"white",border:"none",borderRadius:16,padding:"15px",fontSize:14,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
          Show {count} result{count!==1?"s":""}
        </button>
      </div>
    </div>
    </Portal>
  );
}

/* Order history asks for product reviews only. Opening an item takes the customer to its
   public product page, where the existing review form collects the product, packing and
   shipping aspects together and publishes the result with that product. */
function ProductReviewPrompt({order, products=[], mediaCache={}, reviewedSet=[], onWriteReview}){
  const prodItems=[]; const seenP={};
  (order.items||[]).forEach(it=>{ if(seenP[it.id]) return; const prod=products.find(p=>p.id===it.id); if(prod){ seenP[it.id]=1; prodItems.push({prod,item:it}); } });
  if(!prodItems.length) return null;
  return(
    <div style={{marginTop:10,borderTop:`1px dashed ${C.border}`,paddingTop:10}}>
      <div style={{fontSize:12,fontWeight:800,color:C.text,marginBottom:6}}>✍️ Share review</div>
      {prodItems.map(({prod,item})=>{
        const m=CAT_META[item.category]||CAT_META["Live Fish"];
        const already=reviewedSet.includes(prod.id);
        const img=getCardImg(prod,mediaCache);
        return(
          <button key={prod.id} className="press" onClick={()=>onWriteReview&&onWriteReview(prod)}
            style={{width:"100%",display:"flex",alignItems:"center",gap:10,background:"white",border:`1px solid ${C.border}`,borderRadius:12,padding:"9px 11px",marginBottom:7,textAlign:"left",fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>
            <div style={{width:38,height:38,borderRadius:8,flexShrink:0,overflow:"hidden",background:`linear-gradient(135deg,${m.c1},${m.c2})`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:16}}>
              {img?<img src={img} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>:m.emoji}
            </div>
            <div style={{flex:1,minWidth:0,fontSize:12,fontWeight:700,color:C.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{item.name}</div>
            {already
              ? <span style={{fontSize:11,fontWeight:700,color:C.success,flexShrink:0}}>✓ View review →</span>
              : <span style={{fontSize:11,fontWeight:800,color:C.primary,flexShrink:0}}>Review →</span>}
          </button>
        );
      })}
    </div>
  );
}

/* ═══════════════════ ORDER HISTORY PAGE ═══════════════════ */
/* Customer self-cancel button — shown only while the order is inside the cancel window */
function SelfCancelBtn({o, onCancel}){
  const [confirm,setConfirm]=useState(false);
  const paid=!!o.paidAt||["Payment Review","Confirmed"].includes(o.status);
  if(!confirm) return(
    <div style={{marginTop:10}}>
      <button className="press" onClick={()=>setConfirm(true)}
        style={{width:"100%",background:"#fff",color:C.danger,border:`1.5px solid ${C.danger}`,borderRadius:12,padding:"11px",fontSize:12,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
        ✕ Cancel this order
      </button>
      <div style={{fontSize:10,color:C.textSub,textAlign:"center",marginTop:5,lineHeight:1.4}}>You can cancel any time until we confirm your order.</div>
    </div>
  );
  return(
    <div style={{marginTop:10,background:"#fef2f2",border:`1.5px solid ${C.danger}`,borderRadius:12,padding:"12px"}}>
      <div style={{fontSize:12,fontWeight:800,color:C.danger,marginBottom:4}}>Cancel this order?</div>
      <div style={{fontSize:11,color:"#7f1d1d",lineHeight:1.5,marginBottom:10}}>{paid?"Your order will be cancelled and a refund of the paid amount will be processed to your original payment method.":"Your order will be cancelled."} This can't be undone.</div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
        <button className="press" onClick={()=>setConfirm(false)} style={{background:"white",color:C.text,border:`1px solid ${C.border}`,borderRadius:12,padding:"11px",fontSize:12,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>Keep order</button>
        <button className="press" onClick={()=>{setConfirm(false);onCancel&&onCancel(o);}} style={{background:C.danger,color:"white",border:"none",borderRadius:12,padding:"11px",fontSize:12,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>Yes, cancel</button>
      </div>
    </div>
  );
}

/* Customer return / replacement request — raise, then (once approved) submit courier details */
function ReturnRequestBlock({o, products=[], ownerWA, settings={}, onRequestReturn, onSubmitReturnShipment}){
  const rr=o.returnReq;
  const returnable=(o.items||[]).filter(isReturnableItem);
  const [open,setOpen]=useState(false);
  const [sel,setSel]=useState([]);
  const [reason,setReason]=useState("");
  const [resolution,setResolution]=useState("refund");
  const [photo,setPhoto]=useState("");
  const [busy,setBusy]=useState(false);
  const [courier,setCourier]=useState("");
  const [consign,setConsign]=useState("");
  const within=returnWindowOpen(o);
  const toggle=id=>setSel(p=>p.includes(id)?p.filter(x=>x!==id):[...p,id]);
  const pickPhoto=async(file)=>{ if(!file)return; setBusy(true); try{ const d=await compressImage(file,1100,.8); setPhoto(d); }catch(e){} setBusy(false); };
  const submit=async()=>{ if(!sel.length)return; await onRequestReturn(o,{itemIds:sel,reason:reason.trim(),resolution,photo}); setOpen(false); };
  const disclaimer=(
    <div style={{fontSize:10,color:"#9a3412",lineHeight:1.55,background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:8,padding:"9px 11px",marginBottom:10}}>
      <b>Eligible only for damaged dry goods.</b> Item must be unused and returned with all parts in the original packing cover. <b>Feeds, medicines, live fish, plants, pumps &amp; tubes are not eligible.</b> Refunds/coins exclude packing &amp; shipping charges.
    </div>
  );
  const STAT={
    Requested:"Submitted — under review by our team.",
    Approved:"Approved ✓ — please courier the item back using the details below.",
    Shipped:"We've noted your courier details — we'll verify the parcel on arrival.",
    Declined:"Reviewed — this request was not approved.",
    "Received & Verified":"Parcel received & verified ✓ — your resolution is being processed.",
    // A replacement is not a refund, and telling someone their refund has been processed when a
    // parcel is on the way is the kind of message that turns into a WhatsApp conversation.
    Resolved:(rr&&(rr.adminResolution||rr.resolution))==="replacement"
      ? "Resolved ✓ — a replacement has been arranged. Thank you!"
      : "Resolved ✓ — your refund / coins have been processed. Thank you!",
  };
  if(rr){
    const tone=rr.status==="Declined"?{bg:"#fef2f2",bd:"#fecaca"}:rr.status==="Resolved"?{bg:"#ecfdf5",bd:"#a7f3d0"}:{bg:"#eff6ff",bd:"#bfdbfe"};
    const retAddr=(rr&&String(rr.returnAddress||"").trim())||settings.returnAddress||"Please contact us on WhatsApp for the return shipping address before sending the parcel.";
    return(
      <div style={{marginTop:10,borderTop:`1px dashed ${C.border}`,paddingTop:10}}>
        <div style={{background:tone.bg,border:`1px solid ${tone.bd}`,borderRadius:12,padding:"11px 12px"}}>
          <div style={{fontSize:12,fontWeight:800,color:C.text,marginBottom:3}}>↩️ Return / Replacement request</div>
          <div style={{fontSize:11,color:C.textSub,lineHeight:1.55}}>{STAT[rr.status]||"Submitted."}</div>
          {rr.note&&<div style={{fontSize:11,color:C.text,marginTop:6,lineHeight:1.5}}><b>Note from store:</b> {rr.note}</div>}
          {rr.status==="Approved"&&(
            <div style={{marginTop:10}}>
              <div style={{fontSize:11,fontWeight:800,color:C.text,marginBottom:4}}>📦 Courier it back to{rr.returnAddrLabel?` — ${rr.returnAddrLabel}`:""}:</div>
              <div style={{fontSize:11,color:C.text,whiteSpace:"pre-wrap",lineHeight:1.5,background:"white",border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 10px",marginBottom:10}}>{retAddr}</div>
              <div style={{fontSize:11,color:C.textSub,marginBottom:8,lineHeight:1.5}}>Attach the consignment bill inside/with the parcel, then enter your courier partner &amp; consignment number below.</div>
              <input value={courier} onChange={e=>setCourier(e.target.value)} placeholder="Courier partner (e.g. DTDC, ST Courier)"
                style={{width:"100%",boxSizing:"border-box",borderRadius:12,border:`1.5px solid ${C.border}`,padding:"10px 12px",fontSize:13,outline:"none",background:"white",marginBottom:8}}/>
              <input value={consign} onChange={e=>setConsign(e.target.value)} placeholder="Consignment / tracking number"
                style={{width:"100%",boxSizing:"border-box",borderRadius:12,border:`1.5px solid ${C.border}`,padding:"10px 12px",fontSize:13,outline:"none",background:"white",marginBottom:10,fontFamily:"monospace"}}/>
              <button className="press" disabled={!courier.trim()||!consign.trim()} onClick={()=>onSubmitReturnShipment(o,{courier:courier.trim(),consignment:consign.trim()})}
                style={{width:"100%",background:(courier.trim()&&consign.trim())?C.primary:"#cbd5e1",color:"white",border:"none",borderRadius:12,padding:"11px",fontSize:12,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>Submit return shipment details</button>
            </div>
          )}
          {(rr.status==="Shipped"||rr.status==="Received & Verified"||rr.status==="Resolved")&&(rr.courier||rr.consignment)&&(
            <div style={{fontSize:11,color:C.textSub,marginTop:8}}>Sent via <b style={{color:C.text}}>{rr.courier||"courier"}</b>{rr.consignment?<> · <span style={{fontFamily:"monospace"}}>{rr.consignment}</span></>:null}</div>
          )}
          {/* The store's replacement parcel. Deliberately a separate line from the customer's own
              return shipment above — on a replacement two parcels are in the air at once, and one
              "tracking number" for both is the fastest way to have the customer chase the wrong one. */}
          {/* Gated on the resolution as well as the data. The shipment record is kept even if
              the store later resolves the case a different way — a parcel that really went out
              is a fact — but a customer being refunded should not still be told a replacement
              is on its way. */}
          {(rr.adminResolution||rr.resolution)==="replacement"&&(rr.replacementCourier||rr.replacementConsignment)&&(
            <div style={{marginTop:10,background:"#ecfdf5",border:"1px solid #a7f3d0",borderRadius:12,padding:"10px 12px"}}>
              <div style={{fontSize:12,fontWeight:800,color:"#065f46",marginBottom:3}}>🔁 Your replacement is on its way</div>
              <div style={{fontSize:11,color:"#047857",lineHeight:1.55}}>Sent via <b>{rr.replacementCourier||"courier"}</b>{rr.replacementConsignment?<> · <span style={{fontFamily:"monospace"}}>{rr.replacementConsignment}</span></>:null}</div>
              {rr.replacementTrackUrl&&rr.replacementConsignment&&(
                <button className="press" onClick={()=>trackParcel({courierTrackUrl:rr.replacementTrackUrl,trackingNumber:rr.replacementConsignment})}
                  style={{width:"100%",marginTop:8,background:"#0c2b30",color:"white",border:"none",borderRadius:12,padding:"9px",fontSize:12,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
                  🚚 Track replacement{rr.replacementCourier?` · ${rr.replacementCourier}`:""}
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    );
  }
  if(!within) return null; // 3-day window closed
  return(
    <div style={{marginTop:10,borderTop:`1px dashed ${C.border}`,paddingTop:10}}>
      {!open?(
        <button className="press" onClick={()=>setOpen(true)}
          style={{background:"none",border:"none",padding:0,color:C.textSub,fontSize:11,fontWeight:600,fontFamily:"'Plus Jakarta Sans',sans-serif",textDecoration:"underline",cursor:"pointer"}}>
          Return/Replacement
        </button>
      ):(
        <div style={{background:C.bg,border:`1px solid ${C.border}`,borderRadius:12,padding:"13px"}}>
          <div style={{fontSize:12,fontWeight:800,color:C.text,marginBottom:8}}>↩️ Return / Replacement (damaged item)</div>
          {disclaimer}
          <div style={{fontSize:11,fontWeight:700,color:C.textSub,marginBottom:6}}>Which item(s)?</div>
          <div style={{display:"flex",flexDirection:"column",gap:6,marginBottom:10}}>
            {returnable.map(it=>(
              <label key={it.id} style={{display:"flex",alignItems:"center",gap:9,fontSize:12,color:C.text,cursor:"pointer"}}>
                <input type="checkbox" checked={sel.includes(it.id)} onChange={()=>toggle(it.id)} style={{width:17,height:17,accentColor:C.primary}}/>
                {it.name} <span style={{color:C.textSub}}>· Qty {it.qty}</span>
              </label>
            ))}
          </div>
          <textarea value={reason} onChange={e=>setReason(e.target.value)} rows={2} placeholder="Describe the damage…"
            style={{width:"100%",boxSizing:"border-box",borderRadius:12,border:`1.5px solid ${C.border}`,padding:"10px 12px",fontSize:13,outline:"none",resize:"none",background:"white",marginBottom:10}}/>
          <div style={{fontSize:11,fontWeight:700,color:C.textSub,marginBottom:6}}>Photo proof</div>
          {photo?(
            <div style={{position:"relative",display:"inline-block",marginBottom:10}}>
              <img src={photo} alt="" style={{width:84,height:84,objectFit:"cover",borderRadius:12,border:`1px solid ${C.border}`}}/>
              <button onClick={()=>setPhoto("")} style={{position:"absolute",top:-6,right:-6,width:22,height:22,borderRadius:"50%",background:"rgba(0,0,0,.6)",color:"white",border:"none",fontSize:13,cursor:"pointer"}}>×</button>
            </div>
          ):(
            <label style={{display:"flex",alignItems:"center",justifyContent:"center",gap:8,borderRadius:12,border:`1.5px dashed ${C.border}`,background:"white",padding:"12px",cursor:"pointer",color:C.textSub,fontSize:12,fontWeight:600,marginBottom:10}}>
              <input type="file" accept="image/*" style={{display:"none"}} onChange={e=>{pickPhoto(e.target.files[0]);e.target.value="";}}/>
              {busy?"Processing…":"📷 Add a photo of the damage"}
            </label>
          )}
          <div style={{fontSize:11,fontWeight:700,color:C.textSub,marginBottom:6}}>Preferred resolution</div>
          <div style={{display:"flex",gap:8,marginBottom:12}}>
            {[["refund","💸 Refund"],["coins","🪙 Reward coins"]].map(([k,l])=>(
              <button key={k} type="button" className="press" onClick={()=>setResolution(k)}
                style={{flex:1,padding:"9px",borderRadius:12,border:`1.5px solid ${resolution===k?C.primary:C.border}`,background:resolution===k?C.primary:"white",color:resolution===k?"white":C.textSub,fontSize:12,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>{l}</button>
            ))}
          </div>
          <div style={{display:"flex",gap:8}}>
            <button className="press" onClick={()=>setOpen(false)} style={{background:"white",color:C.textSub,border:`1px solid ${C.border}`,borderRadius:12,padding:"11px 14px",fontSize:12,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>Cancel</button>
            <button className="press" disabled={!sel.length||busy} onClick={submit}
              style={{flex:1,background:sel.length?C.primary:"#cbd5e1",color:"white",border:"none",borderRadius:12,padding:"11px",fontSize:12,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>Submit request</button>
          </div>
        </div>
      )}
    </div>
  );
}

/* One live-fish line's Dead-on-Arrival claim.
   Replaces a single order-level "Report DOA" link that could not say WHICH fish died, so the
   store had to work it out from a free-text sentence. Each live line now carries its own
   button, its own cause, and its own count — and the claims accumulate on the order, so a
   customer who opens two bags an hour apart can report each as they find it. */
function ItemDoaBlock({order, item, claim, windowOpen, hoursLeft, ownerWA, onReportDoa}){
  const [open,setOpen]=useState(false);
  const [cause,setCause]=useState("");
  const [note,setNote]=useState("");
  const [qty,setQty]=useState(1);
  const [reso,setReso]=useState("refund");
  const maxQty=Math.max(1,Number(item.qty)||1);

  if(claim) return(
    <div style={{marginTop:6,background:"#ecfdf5",border:"1px solid #a7f3d0",borderRadius:8,padding:"8px 10px"}}>
      <div style={{fontSize:11,fontWeight:800,color:"#065f46"}}>🐟 DOA reported · {claim.qty||1} fish</div>
      {claim.cause&&<div style={{fontSize:10,color:"#047857",marginTop:2,lineHeight:1.45}}>{claim.cause}</div>}
      <button className="press" onClick={()=>openWA(ownerWA,encodeURIComponent(`Hi, regarding my DOA request for order ${order.orderNo||orderId(order.id)} — item: ${item.name}. Here is my unboxing video.`))}
        style={{marginTop:7,background:"#25D366",color:"white",border:"none",borderRadius:8,padding:"7px 11px",fontSize:10,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>💬 Send video</button>
    </div>
  );
  if(!windowOpen) return null;

  if(!open) return(
    <button className="press" onClick={()=>setOpen(true)}
      style={{marginTop:6,background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:8,padding:"7px 11px",fontSize:10,fontWeight:800,color:"#9a3412",fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>
      {/* The countdown only appears once delivery has been recorded; before that there is no
          deadline running and quoting one would be a lie. */}
      🐟 Report this fish as Dead on Arrival{hoursLeft>0?` · ${hoursLeft}h left`:""}
    </button>
  );
  const ready=!!cause && (cause!=="Other (explain below)" || note.trim().length>0);
  return(
    <div style={{marginTop:8,background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:12,padding:"11px"}}>
      <div style={{fontSize:11,fontWeight:800,color:"#9a3412",marginBottom:7}}>DOA — {item.name}</div>

      <div style={{fontSize:10,fontWeight:800,color:"#9a3412",marginBottom:5}}>How many arrived dead?</div>
      <div style={{display:"flex",alignItems:"center",gap:10,background:"#fff",borderRadius:8,padding:"5px 10px",border:"1px solid #fed7aa",width:"fit-content",marginBottom:10}}>
        <button className="press" onClick={()=>setQty(q=>Math.max(1,q-1))} style={{background:"none",border:"none",fontSize:16,color:"#9a3412",fontWeight:800,lineHeight:1,cursor:"pointer"}}>−</button>
        <span style={{fontSize:12,fontWeight:800,color:"#9a3412",minWidth:14,textAlign:"center"}}>{qty}</span>
        <button className="press" onClick={()=>setQty(q=>Math.min(maxQty,q+1))} disabled={qty>=maxQty}
          style={{background:"none",border:"none",fontSize:16,color:qty>=maxQty?"#fdba74":"#9a3412",fontWeight:800,lineHeight:1,cursor:qty>=maxQty?"default":"pointer"}}>+</button>
        <span style={{fontSize:10,color:"#c2410c",fontWeight:700}}>of {maxQty}</span>
      </div>

      <div style={{fontSize:10,fontWeight:800,color:"#9a3412",marginBottom:5}}>Reason for dead arrival?</div>
      <div style={{display:"flex",flexDirection:"column",gap:5,marginBottom:9}}>
        {DOA_CAUSES.map(c=>(
          <label key={c} style={{display:"flex",alignItems:"center",gap:8,fontSize:11,color:"#7c2d12",cursor:"pointer",lineHeight:1.4}}>
            <input type="radio" name={`doacause-${order.id}-${item.id}`} checked={cause===c} onChange={()=>setCause(c)}
              style={{width:15,height:15,accentColor:"#9a3412",flexShrink:0}}/>
            {c}
          </label>
        ))}
      </div>
      <textarea value={note} onChange={e=>setNote(e.target.value.slice(0,300))} rows={2}
        placeholder={cause==="Other (explain below)"?"Please describe what happened (required)":"Anything else we should know? (optional)"}
        style={{width:"100%",boxSizing:"border-box",borderRadius:8,border:"1.5px solid #fed7aa",padding:"8px 10px",fontSize:11,outline:"none",resize:"none",lineHeight:1.5,background:"white",marginBottom:9,fontFamily:"'Plus Jakarta Sans',sans-serif"}}/>

      <div style={{fontSize:10,fontWeight:800,color:"#9a3412",marginBottom:5}}>Choose your resolution</div>
      <div style={{display:"flex",gap:6,marginBottom:10}}>
        {[["refund","💸 Refund"],["coins","🪙 Reward coins"]].map(([k,l])=>(
          <button key={k} type="button" className="press" onClick={()=>setReso(k)}
            style={{flex:1,padding:"8px 4px",borderRadius:8,border:`1.5px solid ${reso===k?"#9a3412":"#fed7aa"}`,background:reso===k?"#9a3412":"white",color:reso===k?"white":"#9a3412",fontSize:10,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>{l}</button>
        ))}
      </div>
      <div style={{fontSize:10,color:"#9a3412",lineHeight:1.5,marginBottom:9}}>
        Send ONE clear, continuous unboxing video (from the sealed package) on WhatsApp within <b>2 hours</b> of delivery — that video is what the claim is judged on, so film the unboxing before anything else. Claims close {DOA_WINDOW_HOURS} hours after delivery. If approved, your choice of <b>refund or reward coins</b> for the affected fish value will be used.
      </div>
      <div style={{display:"flex",gap:7}}>
        <button className="press" disabled={!ready} onClick={()=>{
            const full=[cause,note.trim()].filter(Boolean).join(" — ");
            openWA(ownerWA,encodeURIComponent(`Hi, Dead on Arrival report for order ${order.orderNo||orderId(order.id)}.\nItem: ${item.name}${item.variantLabel?` (${item.variantLabel})`:""}\nHow many dead: ${qty}\nReason: ${full}\nI'm sharing my unboxing video for review.`));
            onReportDoa&&onReportDoa(order,{resolution:reso,reason:full,cause,note:note.trim(),qty,itemId:item.id,itemName:item.name});
            setOpen(false);
          }}
          style={{flex:1,background:ready?"#25D366":"#bbf7d0",color:"white",border:"none",borderRadius:8,padding:"10px",fontSize:11,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:ready?"pointer":"not-allowed"}}>💬 Share video on WhatsApp</button>
        <button className="press" onClick={()=>setOpen(false)}
          style={{background:"white",color:C.textSub,border:`1px solid ${C.border}`,borderRadius:8,padding:"10px 12px",fontSize:11,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>Cancel</button>
      </div>
    </div>
  );
}

function OrderHistoryPage({user, orders, products, mediaCache, nav, onLogout, onDeleteAccount, onWriteReview, reviewedSet=[], onCancelled, onCancelPayment, onReportDoa, onCancelByCustomer, onRequestReturn, onSubmitReturnShipment, addToCart, settings={}, favorites=[]}){
  const [openId,setOpenId]=useState(null); // which order is expanded (list shows summaries; details open on tap)
  // Re-add the exact option that was bought (the 10" net, not whichever size happens to be first).
  const reorder=(o)=>{ let n=0; (o.items||[]).forEach(it=>{ const prod=products.find(p=>p.id===it.id); if(prod&&!prod.comingSoon&&(prod.stockCount??DEFAULT_STOCK)>0&&addToCart){
    const vs=productVariants(prod);
    const want=it.variantId&&vs?vs.find(v=>v.id===it.variantId&&!v.soldOut):null;
    addToCart(prod,it.qty||1,want||null); n++; } }); nav("cart"); };
  const uk = userKey(user);
  const [payOpen,setPayOpen]=useState(null);
  const [delOpen,setDelOpen]=useState(false);
  const [delAck,setDelAck]=useState(false);
  const [delBusy,setDelBusy]=useState(false);
  // Refresh hourly so the live delivery countdown rolls over as the day changes while the app is left open.
  const [,setDayTick]=useState(0);
  useEffect(()=>{ const id=setInterval(()=>setDayTick(t=>t+1),3600000); return ()=>clearInterval(id); },[]);
  const myOrders = orders.filter(o =>
    !cancelledByCustomer(o) && (
      (o.userUid && uk && o.userUid===uk) ||
      (user.uid && o.userUid===user.uid) ||
      (user.phone && normalizePhone(o.address?.phone)===normalizePhone(user.phone))
    )
  );
  const visibleOrders=myOrders;
  const ownerWA=(settings.ownerWhatsapp||BUSINESS_WA).replace(/\D/g,"");
  const doaStatusText={
    "Requested":"Received — please send your unboxing video on WhatsApp so we can review it.",
    "Under Review":"Your DOA video is under review by our team.",
    "Approved - Replacement":"Approved ✓ — the previously arranged replacement is being processed.",
    "Approved - Store Credit":"Approved ✓ — your chosen reward coins are being issued.",
    "Approved - Refund":"Approved ✓ — a refund of the fish amount is being processed.",
    "Declined":"Reviewed — this DOA request was not approved.",
  };
  return(
    <div className="slide-up">
      <div style={{background:C.card,padding:"52px 16px 16px",borderBottom:`1px solid ${C.border}`}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12}}>
          <div>
            <div style={{fontSize:11,color:C.textSub,fontWeight:700,letterSpacing:1,textTransform:"uppercase"}}>Signed in</div>
            <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:22,fontWeight:800,color:C.text}}>{user.name||"My Orders"}</div>
            {(user.phone||user.email)&&(
              <div style={{fontSize:12,color:C.textSub,marginTop:2}}>
                {user.phone?`+91 ${user.phone}`:user.email}
              </div>
            )}
          </div>
          <button className="press" onClick={onLogout}
            style={{background:C.bg,color:C.danger,border:`1.5px solid ${C.border}`,borderRadius:12,padding:"8px 14px",fontSize:12,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
            Logout
          </button>
        </div>
      </div>

      <div className="dt-read" style={{padding:"16px 16px 100px"}}>
        {/* Saved / Favorites — lives here under the signed-in account */}
        <button className="press" onClick={()=>nav("saved")}
          style={{width:"100%",display:"flex",alignItems:"center",gap:12,background:C.card,border:`1.5px solid ${C.border}`,borderRadius:16,padding:"14px 16px",marginBottom:16,cursor:"pointer",textAlign:"left"}}>
          <span style={{fontSize:22,color:C.coral}}>♥</span>
          <div style={{flex:1}}>
            <div style={{fontSize:14,fontWeight:800,color:C.text,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>Saved Items</div>
            <div style={{fontSize:11,color:C.textSub}}>{favorites.length>0?`${favorites.length} item${favorites.length!==1?"s":""} saved`:"Your wishlist is empty"}</div>
          </div>
          <span style={{fontSize:18,color:C.textSub}}>›</span>
        </button>
        {myOrders.length===0?(
          <div style={{textAlign:"center",padding:"60px 20px",color:C.textSub}}>
            <div style={{fontSize:60,marginBottom:14}}>📦</div>
            <div style={{fontSize:16,fontWeight:700,color:C.text,marginBottom:6}}>No orders yet</div>
            <div style={{fontSize:13,marginBottom:20}}>Your orders will appear here.</div>
            <button className="press" onClick={()=>nav("shop")} style={{background:C.primary,color:"white",border:"none",borderRadius:16,padding:"13px 28px",fontSize:13,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>Start Shopping</button>
          </div>
        ):(
          <>
          <div style={{fontSize:12,color:C.textSub,fontWeight:600,marginBottom:12}}>{visibleOrders.length} order{visibleOrders.length===1?"":"s"}</div>
          {visibleOrders.map(o=>{
            const open=openId===o.id;
            const names=(o.items||[]).map(i=>i.name).join(", ");
            const nItems=(o.items||[]).length;
            const isDelivered=o.status==="Delivered";
            const needsProductReview=(o.items||[]).some(it=>products.some(p=>p.id===it.id)&&!reviewedSet.includes(it.id));
            return(
            <div key={o.id} style={{background:C.card,borderRadius:20,padding:"16px",marginBottom:12,border:`1px solid ${open?C.accent:C.border}`}}>
              {/* Compact summary — always visible; tap to open full details, bills & invoices (#11/#12) */}
              <button className="press" onClick={()=>setOpenId(open?null:o.id)}
                style={{width:"100%",background:"none",border:"none",padding:0,cursor:"pointer",textAlign:"left",fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10}}>
                  <div style={{minWidth:0,flex:1}}>
                    <div style={{fontFamily:PRICE_FONT,fontSize:13,fontWeight:800,color:C.primary,marginBottom:3}}>{o.orderNo||orderId(o.id)}</div>
                    <div style={{fontSize:12,fontWeight:700,color:C.text,lineHeight:1.35,marginBottom:3,overflow:"hidden",display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical"}}>{names}</div>
                    <div style={{fontSize:11,color:C.textSub}}>{fmtDate(o.placedAt)} · {nItems} item{nItems!==1?"s":""} · ₹{o.amountDue??(o.total+o.fee)}</div>
                  </div>
                  <div style={{display:"flex",flexDirection:"column",alignItems:"flex-end",gap:6,flexShrink:0}}>
                    <CustomerStageBadge order={o}/>
                    <span style={{fontSize:11,fontWeight:800,color:C.primary}}>{open?"Hide ▲":"Details ▾"}</span>
                  </div>
                </div>
                {isDelivered&&needsProductReview&&!open&&(
                  <div style={{marginTop:8,fontSize:11,fontWeight:800,color:C.primary}}>☆ Share review →</div>
                )}
              </button>
              {open&&(<div style={{marginTop:12}}>
              {o.items.map((item,i)=>{
                const m=CAT_META[item.category]||CAT_META["Live Fish"];
                const prod=products.find(p=>p.id===item.id);
                const delivered = ["Confirmed","Shipped","Delivered"].includes(o.status);
                const already = reviewedSet.includes(item.id);
                // Tapping an ordered item reopens its product page — the usual way to reorder
                // or re-read the care notes. Only offered while the product still exists.
                const open=prod?()=>nav("detail",prod):null;
                return(
                  <div key={i} style={{padding:"8px 0",borderTop:i===0?"none":`1px solid ${C.border}`}}>
                  <div style={{display:"flex",gap:10,alignItems:"center"}}>
                    <div role={open?"button":undefined} tabIndex={open?0:undefined} onClick={open||undefined}
                      onKeyDown={open?(e=>{ if(e.key==="Enter"||e.key===" "){ e.preventDefault(); open(); } }):undefined}
                      aria-label={open?`View ${item.name}`:undefined}
                      style={{display:"flex",gap:10,alignItems:"center",flex:1,minWidth:0,cursor:open?"pointer":"default"}}>
                      <div style={{width:44,height:44,borderRadius:12,background:`linear-gradient(135deg,${m.c1},${m.c2})`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0,overflow:"hidden"}}>
                        {/* Order lines are snapshots and carry no image, so resolve it
                            from the live catalogue — the same helper the cart uses.
                            Reading mediaCache directly only ever worked for legacy
                            products: a modern one keeps its photo as a URL on
                            product.media[], which hydrateMedia deliberately does not
                            copy into the cache, so every order showed the category
                            emoji instead of what was bought. */}
                        {(()=>{ const src=getCartLineImg(item,products,mediaCache);
                          return src?<img src={src} alt="" loading="lazy" decoding="async" style={{width:"100%",height:"100%",objectFit:"cover"}}/>:m.emoji; })()}
                      </div>
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{fontSize:13,fontWeight:700,color:open?C.primaryDark:C.text}}>{item.name}</div>
                        <div style={{fontSize:11,color:C.textSub}}>
                          {item.variantLabel?<>{item.variantLabel} · </>:null}Qty {item.qty} · ₹{item.price*item.qty}
                        </div>
                      </div>
                    </div>
                    {delivered && prod && already && <span style={{fontSize:11,fontWeight:700,color:C.success,flexShrink:0}}>✓ Reviewed</span>}
                  </div>
                  {/* Per-item DOA, for every live line from payment until the window shuts.
                      Sits with the fish it is about rather than in one order-level box. */}
                  {item.category==="Live Fish" && o.liveGuarantee!==false && (
                    <ItemDoaBlock order={o} item={item} claim={(o.doaItems||{})[item.id]}
                      windowOpen={doaEntryOpen(o) && !((o.doa&&o.doa.status)&&o.doa.status!=="Requested")}
                      hoursLeft={doaHoursLeft(o)} ownerWA={ownerWA} onReportDoa={onReportDoa}/>
                  )}
                  </div>
                );
              })}
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",borderTop:`1px solid ${C.border}`,paddingTop:10,marginTop:8}}>
                <span style={{fontSize:12,color:C.textSub}}>Grand Total</span>
                <span style={{fontFamily:PRICE_FONT,fontSize:16,fontWeight:800,color:C.primary}}>₹{o.amountDue??(o.total+o.fee)}</span>
              </div>
              {["Confirmed","Shipped"].includes(o.status)&&!o.closed&&(()=>{
                const eta=etaInfo(o); if(!eta) return null;
                const d=eta.daysLeft;
                const headline = d>1 ? `Arriving in ${d} days` : d===1 ? "Arriving tomorrow" : d===0 ? "Arriving today" : "Arriving very soon";
                const sub = d<0 ? `Expected by ${eta.dateLabel} \u2014 should reach you any moment now` : `Expected by ${eta.dateLabel}`;
                const urgent = d<=1;
                return(
                  <div style={{marginTop:10,display:"flex",alignItems:"center",gap:11,background:urgent?"#fff7ed":C.accentLight,border:`1.5px solid ${urgent?"#fdba74":C.accent}`,borderRadius:16,padding:"11px 13px"}}>
                    <span style={{fontSize:22,lineHeight:1}}>🚚</span>
                    <div style={{flex:1,minWidth:0}}>
                      <div style={{fontSize:14,fontWeight:800,color:urgent?"#9a3412":C.primaryDark,fontFamily:"'Plus Jakarta Sans',sans-serif",lineHeight:1.15}}>{headline}</div>
                      <div style={{fontSize:11,color:urgent?"#9a3412":C.textSub,fontWeight:600,marginTop:2}}>{sub}{o.status==="Shipped"?" \u00b7 on the way":""}</div>
                    </div>
                  </div>
                );
              })()}
              {o.trackingNumber&&<div style={{fontSize:11,color:C.textSub,marginTop:6}}>Consignment: <b style={{color:C.text}}>{o.trackingNumber}</b>{o.courierName?<> · {o.courierName}</>:null}</div>}
              {(o.status==="Shipped"||o.status==="Delivered")&&o.courierTrackUrl&&(
                <button className="press" onClick={()=>trackParcel(o)}
                  style={{width:"100%",marginTop:8,background:"#0c2b30",color:"white",border:"none",borderRadius:12,padding:"10px",fontSize:12,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",display:"flex",alignItems:"center",justifyContent:"center",gap:7}}>
                  🚚 Track Parcel{o.courierName?` · ${o.courierName}`:""}
                </button>
              )}
              {o.shippingReward&&(
                <div style={{marginTop:10,background:"#ecfdf5",border:"1px solid #a7f3d0",borderRadius:12,padding:"11px 13px"}}>
                  <div style={{fontSize:12,fontWeight:800,color:"#15803d",marginBottom:3}}>🎁 Shipping refund — ₹{o.shippingReward.amount} added to your wallet!</div>
                  <div style={{fontSize:11,color:"#166534",lineHeight:1.55}}>Extra shipping paid was returned to your wallet.</div>
                </div>
              )}
              {/* Bill button */}
              <div style={{display:"flex",gap:8,marginTop:10}}>
              <button className="press" onClick={()=>openBill(o,settings)}
                style={{flex:1,background:C.bg,color:C.primary,border:`1px solid ${C.border}`,borderRadius:12,padding:"9px",fontSize:12,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif",display:"flex",alignItems:"center",justifyContent:"center",gap:6}}>
                🧾 Quick Bill
              </button>
              <button className="press" onClick={()=>openInvoice(o,settings)}
                style={{flex:1,background:C.bg,color:C.primary,border:`1px solid ${C.border}`,borderRadius:12,padding:"9px",fontSize:12,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif",display:"flex",alignItems:"center",justifyContent:"center",gap:6}}>
                📄 Invoice (PDF)
              </button>
              </div>
              {o.status==="Delivered"&&(
                <button className="press" onClick={()=>reorder(o)}
                  style={{width:"100%",marginTop:8,background:C.accentLight,color:C.primary,border:`1.5px solid ${C.accent}`,borderRadius:12,padding:"10px",fontSize:12,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
                  🔁 Reorder these items
                </button>
              )}

              {/* Payment state */}
              {o.status==="Awaiting Payment"&&(
                <div style={{marginTop:12,paddingTop:12,borderTop:`1px solid ${C.border}`}}>
                  {payOpen===o.id?(
                    <PaymentPanel order={o} compact onCancelled={onCancelled} onCheckoutCancelled={onCancelPayment}/>
                  ):(
                    <>
                      <div style={{background:"#fef3c7",border:`1px solid #fde68a`,borderRadius:12,padding:"10px 12px",marginBottom:10,fontSize:12,color:"#92400e",fontWeight:600,lineHeight:1.5}}>⏳ Payment pending — complete it to confirm this order (auto-cancels if unpaid).</div>
                      <button className="press" onClick={()=>setPayOpen(o.id)}
                        style={{width:"100%",background:C.primary,color:"white",border:"none",borderRadius:12,padding:"13px",fontSize:14,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>💳 Complete Payment · ₹{o.amountDue??(o.total+o.fee)}</button>
                    </>
                  )}
                </div>
              )}
              {o.status==="Payment Review"&&(
                <div style={{marginTop:10,background:"#ede9fe",border:`1px solid #ddd6fe`,borderRadius:12,padding:"10px 12px",fontSize:12,color:"#6d28d9",fontWeight:600,lineHeight:1.5}}>{o.gateway?(o.testPayment?`${gatewayLabel(o.gateway)} test payment recorded — not a fulfilment order.`:`${gatewayLabel(o.gateway)} payment recorded — this order still needs admin review.`):`🔎 Payment submitted${o.txnId?` (Ref: ${o.txnId})`:""} — under verification.`}</div>
              )}
              {o.status==="Cancelled"&&(
                <div style={{marginTop:10}}>
                  <div style={{background:"#fee2e2",border:`1px solid #fecaca`,borderRadius:12,padding:"10px 12px",fontSize:12,color:"#b91c1c",fontWeight:600,lineHeight:1.55}}>
                    ✕ Your order has been cancelled.{o.cancelReason?` Reason: ${o.cancelReason}.`:o.paymentStatus&&/unpaid/i.test(o.paymentStatus)?" Payment wasn't completed in time.":""}
                  </div>
                  {o.refund&&o.refund.due&&(
                    <div style={{marginTop:8,background:"#eff6ff",border:"1px solid #bfdbfe",borderRadius:12,padding:"11px 12px",fontSize:12,color:"#1e3a8a",lineHeight:1.6}}>
                      <div style={{fontWeight:800,marginBottom:3}}>💸 Refund {o.refund.status==="refunded"?"completed":o.refund.status==="processing"?"in progress":"being arranged"}</div>
                      {o.refund.method==="gateway"?(
                        <div>A refund of <b>₹{o.refund.amount}</b> {o.refund.status==="refunded"?"has been":"is being"} returned automatically to your original payment method. Please allow 3–7 working days for it to reflect.</div>
                      ):(
                        <div>A refund of <b>₹{o.refund.amount}</b> {o.refund.status==="refunded"?"has been sent":"will be sent"} to your UPI / payment account.{o.refund.refundTxnId?<> Refund Reference: <b style={{fontFamily:"monospace"}}>{o.refund.refundTxnId}</b></>:o.refund.status!=="refunded"?<> We'll share the refund reference here once it's processed.</>:null}</div>
                      )}
                    </div>
                  )}
                  {o.refund&&o.refund.due===false&&(
                    <div style={{marginTop:8,fontSize:11,color:C.textSub,lineHeight:1.5}}>No payment was collected for this order, so there's nothing to refund.</div>
                  )}
                </div>
              )}
              {o.status==="Confirmed"&&(
                <div style={{marginTop:10,background:"#dcfce7",border:`1px solid #bbf7d0`,borderRadius:12,padding:"10px 12px",fontSize:12,color:"#15803d",fontWeight:600,lineHeight:1.5}}>✅ Payment verified — your order is confirmed &amp; being prepared!</div>
              )}
              {/* Dead-on-Arrival — the claim itself is now raised per fish, up with the item it
                  concerns (see ItemDoaBlock above). What stays here is the order-level status of
                  whatever has been claimed, plus the two cases where no button appears at all. */}
              {o.items.some(it=>it.category==="Live Fish") && (()=>{
                const claims=Object.entries(o.doaItems||{});
                const win=doaEntryOpen(o), left=doaHoursLeft(o);
                if(o.liveGuarantee===false) return(
                  <div style={{marginTop:10,borderTop:`1px dashed ${C.border}`,paddingTop:10}}>
                    <div style={{fontSize:11,color:"#9a3412",background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:12,padding:"9px 11px",lineHeight:1.5}}>ℹ️ The <b>Live Arrival Guarantee (DOA cover)</b> doesn't apply to this order — a packing option below our recommendation was chosen at checkout. Per our Terms, DOA claims need the recommended (or safer) packing.</div>
                  </div>
                );
                if(!claims.length){
                  // Nothing to say before the order is paid — the claim isn't open yet.
                  if(!win && !deliveredAtOf(o)) return null;
                  return(
                  <div style={{marginTop:10,borderTop:`1px dashed ${C.border}`,paddingTop:10}}>
                    <div style={{fontSize:11,color:C.textSub,lineHeight:1.5}}>
                      {win
                        ? <>🐟 Fish arrived dead? Use the <b>Report</b> button under that fish above{left>0?` — ${left}h left to raise a claim`:""}.</>
                        : <>The {DOA_WINDOW_HOURS}-hour window to raise a Dead-on-Arrival claim for this order has closed.</>}
                    </div>
                  </div>
                  );
                }
                const st=(o.doa&&o.doa.status)||"Requested";
                return(
                  <div style={{marginTop:10,borderTop:`1px dashed ${C.border}`,paddingTop:10}}>
                    <div style={{background:st==="Declined"?"#fef2f2":st.startsWith("Approved")?"#ecfdf5":"#fff7ed",border:`1px solid ${st==="Declined"?"#fecaca":st.startsWith("Approved")?"#a7f3d0":"#fed7aa"}`,borderRadius:12,padding:"11px 12px"}}>
                      <div style={{fontSize:12,fontWeight:800,color:C.text,marginBottom:3}}>🐟 Dead-on-Arrival request · {claims.length} item{claims.length>1?"s":""}</div>
                      <div style={{fontSize:11,color:C.textSub,lineHeight:1.55}}>{doaStatusText[st]||"Submitted."}</div>
                      <div style={{marginTop:7,display:"flex",flexDirection:"column",gap:4}}>
                        {claims.map(([iid,c])=>(
                          <div key={iid} style={{fontSize:11,color:C.text,lineHeight:1.45}}>
                            • <b>{c.name||"Item"}</b> — {c.qty||1} dead{c.cause?` · ${c.cause}`:""}
                          </div>
                        ))}
                      </div>
                      {o.doa&&o.doa.note&&<div style={{fontSize:11,color:C.text,marginTop:7,lineHeight:1.5}}><b>Note from store:</b> {o.doa.note}</div>}
                      {(st==="Requested"||st==="Under Review")&&(
                        <button className="press" onClick={()=>openWA(ownerWA,encodeURIComponent(`Hi, regarding my DOA request for order ${o.orderNo||orderId(o.id)} — here is my unboxing video.`))}
                          style={{marginTop:8,background:"#25D366",color:"white",border:"none",borderRadius:8,padding:"8px 12px",fontSize:11,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>💬 Send video on WhatsApp</button>
                      )}
                      {win&&(st==="Requested")&&<div style={{fontSize:10,color:C.textSub,marginTop:6,lineHeight:1.45}}>Found another one? You can still report other fish above{left>0?` for ${left}h`:""}.</div>}
                    </div>
                  </div>
                );
              })()}
              {/* Self-cancel within the allowed window (instant) */}
              {selfCancelOpen(o)&&<SelfCancelBtn o={o} onCancel={onCancelByCustomer}/>}
              {/* Return / replacement for damaged dry goods */}
              {o.status==="Delivered"&&orderHasReturnable(o)&&(
                <ReturnRequestBlock o={o} products={products} ownerWA={ownerWA} settings={settings}
                  onRequestReturn={onRequestReturn} onSubmitReturnShipment={onSubmitReturnShipment}/>
              )}
              {o.status==="Delivered" && <ProductReviewPrompt order={o} products={products} mediaCache={mediaCache} reviewedSet={reviewedSet} onWriteReview={onWriteReview}/>}
              </div>)}
            </div>
            );})}
          </>
        )}

        {/* ── Danger zone: delete account & data (Play Store data-deletion requirement) ── */}
        <div style={{marginTop:26,borderTop:`1px solid ${C.border}`,paddingTop:16}}>
          {!delOpen?(
            <button className="press" onClick={()=>setDelOpen(true)}
              style={{background:"none",border:"none",padding:0,color:C.textSub,fontSize:12,fontWeight:600,fontFamily:"'Plus Jakarta Sans',sans-serif",textDecoration:"underline",cursor:"pointer"}}>
              Delete my account
            </button>
          ):(
            <div style={{background:"#fef2f2",border:"1px solid #fecaca",borderRadius:16,padding:"14px 16px"}}>
              <div style={{fontSize:14,fontWeight:800,color:"#b91c1c",marginBottom:6}}>Delete my account &amp; data</div>
              <div style={{fontSize:12,color:"#7f1d1d",lineHeight:1.6,marginBottom:10}}>
                This deletes your account and personal data — your profile, saved items, wallet &amp; loyalty coins, referral code and any tank photos you posted. Your past order &amp; payment records are kept only as long as tax law requires, then deleted. <b>This can't be undone.</b>
              </div>
              <label style={{display:"flex",gap:8,alignItems:"flex-start",fontSize:12,color:"#7f1d1d",fontWeight:600,marginBottom:12,cursor:"pointer"}}>
                <input type="checkbox" checked={delAck} onChange={e=>setDelAck(e.target.checked)} style={{marginTop:2,flexShrink:0}}/>
                <span>I understand my account and its data will be deleted and this can't be undone.</span>
              </label>
              <div style={{display:"flex",gap:8}}>
                <button className="press" disabled={!delAck||delBusy}
                  onClick={async()=>{ if(!delAck||delBusy)return; setDelBusy(true); try{ await onDeleteAccount(); }catch(e){ setDelBusy(false); } }}
                  style={{flex:1,background:(!delAck||delBusy)?"#f3a5a5":"#dc2626",color:"white",border:"none",borderRadius:12,padding:"11px",fontSize:13,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:(!delAck||delBusy)?"default":"pointer"}}>
                  {delBusy?"Deleting…":"Delete my account"}
                </button>
                <button className="press" disabled={delBusy} onClick={()=>{setDelOpen(false);setDelAck(false);}}
                  style={{background:"white",color:C.textSub,border:`1px solid ${C.border}`,borderRadius:12,padding:"11px 16px",fontSize:13,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>Cancel</button>
              </div>
              <div style={{fontSize:11,color:"#991b1b",marginTop:10,lineHeight:1.5}}>
                Prefer to ask us directly? <a href="/delete-account.html" style={{color:"#b91c1c",fontWeight:700}}>Other ways to request deletion →</a>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* True when a product is expected to have a photo (so we can show a shimmer placeholder
   while its image is still hydrating from IndexedDB, instead of flashing the emoji then popping). */
function productExpectsImage(p){
  if(!p) return false;
  if(Array.isArray(p.media) && p.media.some(m=>m && m.type!=="video")) return true;
  return !!p.imageUrl;
}

/* Shimmer skeleton grid — shown on a cold first load until product data hydrates */
/* Deliberately the same GEOMETRY as ProductCard, box for box, not just the same idea.
   It used to be a 120px-tall image block over three short bars, while a real card is a
   square image over a taller body — so the moment the catalogue arrived every card grew by
   about a third and the whole page below it jumped. A placeholder that changes the layout
   when it is replaced is worse than no placeholder: it moves what the shopper is reading.
   Any change to the card's image ratio, padding or block heights belongs here too. */
function SkeletonGrid({n=6}){
  return(
    <div className="prod-grid" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:16}}>
      {Array.from({length:n}).map((_,i)=>(
        <div key={i} style={{background:C.card,borderRadius:20,overflow:"hidden",border:`1px solid ${C.border}`}}>
          <div className="shimmer-bar" style={{aspectRatio:"1 / 1"}}/>
          <div style={{padding:"11px 12px 12px"}}>
            {/* category */}
            <div className="shimmer-bar" style={{height:9,borderRadius:8,marginBottom:5,width:"45%"}}/>
            {/* name — two lines inside the card's own minHeight:33 */}
            <div style={{minHeight:33,marginBottom:6}}>
              <div className="shimmer-bar" style={{height:12,borderRadius:8,marginBottom:5}}/>
              <div className="shimmer-bar" style={{height:12,borderRadius:8,width:"70%"}}/>
            </div>
            {/* price */}
            <div className="shimmer-bar" style={{height:16,borderRadius:8,width:"40%",marginBottom:6}}/>
            {/* the add-to-cart row: a 11.5px label with 7px padding, so 30px tall */}
            <div className="shimmer-bar" style={{height:30,borderRadius:99}}/>
          </div>
        </div>
      ))}
    </div>
  );
}

/* ═══════════════════ PRODUCT CARD ═══════════════════ */
/* Spring-count number — tweens from the previous value to the new one (eased) */
function AnimatedNumber({value,prefix="",suffix="",dur=480}){
  const [disp,setDisp]=useState(value);
  const fromRef=useRef(value), rafRef=useRef(0);
  useEffect(()=>{
    const from=fromRef.current, to=Number(value)||0;
    if(from===to){ setDisp(to); return; }
    if(typeof requestAnimationFrame==="undefined"){ fromRef.current=to; setDisp(to); return; }
    const start=performance.now();
    const tick=t=>{ const p=Math.min(1,(t-start)/dur); const e=1-Math.pow(1-p,3); setDisp(Math.round(from+(to-from)*e)); if(p<1){ rafRef.current=requestAnimationFrame(tick); } else { fromRef.current=to; } };
    cancelAnimationFrame(rafRef.current); rafRef.current=requestAnimationFrame(tick);
    return ()=>cancelAnimationFrame(rafRef.current);
  },[value]);
  return <>{prefix}{(Number(disp)||0).toLocaleString("en-IN")}{suffix}</>;
}

/* ── Shared live-interaction helpers (desktop fine-pointer) ── */
function _fine(){ return typeof window!=="undefined" && window.matchMedia && window.matchMedia("(pointer:fine)").matches; }
function magnetMove(e){
  if(!_fine())return;
  const el=e.currentTarget,r=el.getBoundingClientRect();
  el.style.transition="transform .12s ease-out";
  el.style.transform=`translate(${(e.clientX-r.left-r.width/2)*0.25}px,${(e.clientY-r.top-r.height/2)*0.35}px) scale(1.04)`;
}
function magnetLeave(e){ const el=e.currentTarget; el.style.transition=""; el.style.transform=""; }
/* Fly a coral burst from (x,y) into the cart icon, then pop the cart */
function flyToCart(x,y,imgSrc){
  try{
    const els=document.querySelectorAll("[data-cart-target]");
    let tgt=null; els.forEach(e=>{ if(e.offsetParent!==null) tgt=e; }); if(!tgt) tgt=els[0];
    if(!tgt) return;
    const tr=tgt.getBoundingClientRect();
    const cx=tr.left+tr.width/2, cy=tr.top+tr.height/2;
    const dot=document.createElement("div");
    dot.style.cssText=`position:fixed;left:${x-12}px;top:${y-12}px;width:24px;height:24px;border-radius:50%;background:${imgSrc?`center/cover no-repeat url("${imgSrc}")`:"#f43f5e"};box-shadow:0 6px 18px rgba(244,63,94,.45);z-index:9999;pointer-events:none;border:2px solid #fff;will-change:transform,opacity;`;
    document.body.appendChild(dot);
    const midX=(x+cx)/2, arcLift=Math.min(150, Math.abs(cx-x)*0.5+80);
    const anim=dot.animate([
      {transform:"translate(0,0) scale(1)",opacity:1,offset:0},
      {transform:`translate(${midX-x}px,${Math.min(y,cy)-y-arcLift}px) scale(1.12)`,opacity:1,offset:.55},
      {transform:`translate(${cx-x}px,${cy-y}px) scale(.22)`,opacity:.2,offset:1}
    ],{duration:760,easing:"cubic-bezier(.5,-0.05,.35,1)"});
    anim.onfinish=()=>{ try{dot.remove();}catch(_){} };
    setTimeout(()=>{ try{dot.remove();}catch(_){} },950);
    // Cart icon springs when the puck lands
    tgt.animate([
      {transform:"scale(1)"},{transform:"scale(1.42)",offset:.5},{transform:"scale(.9)",offset:.72},{transform:"scale(1.08)",offset:.86},{transform:"scale(1)"}
    ],{duration:540,delay:560,easing:"cubic-bezier(.34,1.56,.64,1)"});
  }catch(e){}
}

function ProductCard({product:p,imgSrc,onPress,onAdd,inCart=0,isFav=false,onFav,isInterested=false,onInterest}){
  const m   = CAT_META[p.category]||CAT_META["Live Fish"];
  // For an option product this is the sum of what's left across its available options, so a
  // product whose every option is gone reads as sold out rather than "In stock".
  const stk = productStockTotal(p);
  const oos = stk<=0;
  const soon = !!p.comingSoon;
  const onSale = activeDiscount(p) > 0;
  // A product with options is priced "Starts from" its cheapest one, and its Add button opens
  // the product page to choose — adding blind from the grid would pick a size for the customer.
  const multi = hasMultiOptions(p);
  const eff = multi ? variantFromPrice(p) : effectivePrice(p);
  const remaining = Math.max(0, stk - inCart);
  // Live cursor-reactive tilt + spotlight (desktop fine-pointer only; honors reduced-motion)
  const cardRef = useRef(null);
  const fine = typeof window!=="undefined" && window.matchMedia && window.matchMedia("(pointer:fine)").matches && !window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const onTilt = e=>{
    const el=cardRef.current; if(!fine||!el) return;
    const r=el.getBoundingClientRect();
    const px=(e.clientX-r.left)/r.width, py=(e.clientY-r.top)/r.height;
    el.style.transition="transform .08s ease-out"; // snappy tracking while the cursor moves
    el.style.transform=`perspective(820px) rotateX(${(0.5-py)*7}deg) rotateY(${(px-0.5)*7}deg) translateY(-6px) scale(1.02)`;
    el.style.setProperty("--mx",(px*100)+"%"); el.style.setProperty("--my",(py*100)+"%"); el.style.setProperty("--spot","1");
  };
  const onTiltEnd = ()=>{ const el=cardRef.current; if(!el) return; el.style.transition=""; el.style.transform=""; el.style.setProperty("--spot","0"); }; // springy release
  const Heart = onFav ? (
    <button className="press" onClick={e=>{e.stopPropagation();onFav(p);}} aria-label="Save"
      style={{position:"absolute",top:8,right:8,width:30,height:30,borderRadius:"50%",border:"none",background:"rgba(255,255,255,.9)",display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",boxShadow:"0 2px 8px rgba(0,0,0,.18)"}}>
      <span key={isFav?"f":"e"} className={isFav?"heart-pop":""} style={{fontSize:16,lineHeight:1,color:isFav?C.coral:"#9ca3af"}}>{isFav?"♥":"♡"}</span>
    </button>
  ) : null;
  const ShareBtn = (
    <button className="press" onClick={e=>{e.stopPropagation();shareProduct(p);}} aria-label="Share"
      style={{position:"absolute",top:8,right:onFav?44:8,width:30,height:30,borderRadius:"50%",border:"none",background:"rgba(255,255,255,.9)",display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",boxShadow:"0 2px 8px rgba(0,0,0,.18)"}}>
      {/* An arrow leaving a tray, not a chain link. A chain reads as "copy link" — or as
          nothing at all — where this is the icon every phone already draws for Share. */}
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" style={{display:"block"}}>
        <path d="M12 15.5V3.5M8.4 7L12 3.4L15.6 7" stroke="#334155" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
        <path d="M5.5 12.5V18.5a2 2 0 002 2h9a2 2 0 002-2V12.5" stroke="#334155" strokeWidth="2" strokeLinecap="round"/>
      </svg>
    </button>
  );
  return(
    <div className="lift" ref={cardRef} onClick={()=>onPress(p)} onMouseMove={onTilt} onMouseLeave={onTiltEnd}
      style={{background:C.card,borderRadius:20,overflow:"hidden",border:`1px solid ${C.border}`,boxShadow:"0 1px 2px rgba(15,23,42,.05), 0 8px 20px rgba(15,23,42,.06)",cursor:"pointer",position:"relative"}}>
      {fine&&<div style={{position:"absolute",inset:0,pointerEvents:"none",zIndex:5,opacity:"var(--spot,0)",transition:"opacity .3s ease",background:"radial-gradient(200px circle at var(--mx,50%) var(--my,50%),rgba(14,165,233,.14),transparent 62%)"}}/>}
      {/* The photo is the product — it gets a square tile (roughly 60% of the card) and is fitted
          WHOLE inside it. It used to be a 120px letterbox with object-fit:cover, which cropped a
          portrait fish photo down to a horizontal sliver and cut the animal in half. */}
      <div style={{aspectRatio:"1 / 1",display:"flex",alignItems:"center",justifyContent:"center",position:"relative",overflow:"hidden",
        background:imgSrc?"#ffffff":`linear-gradient(140deg,${m.c1},${m.c2})`}}>
        {imgSrc
          ? <SmoothImg src={imgSrc} alt={p.name} style={{width:"100%",height:"100%",objectFit:"contain",padding:6}}/>
          : productExpectsImage(p)
            ? <div className="shimmer-bar" style={{position:"absolute",inset:0}}/>
            : <span style={{fontSize:52}}>{m.emoji}</span>}
        {!imgSrc&&<div style={{position:"absolute",inset:0,pointerEvents:"none",background:"linear-gradient(to top,rgba(0,0,0,.16),transparent 40%)"}}/>}
        {p.tag&&<span style={{position:"absolute",top:8,left:8,background:"rgba(0,0,0,.32)",color:"white",fontSize:10,fontWeight:700,padding:"3px 9px",borderRadius:20,backdropFilter:"blur(4px)"}}>{p.tag}</span>}
        {onSale&&!soon&&<span style={{position:"absolute",bottom:8,left:8,background:C.coral,color:"white",fontSize:10,fontWeight:800,padding:"3px 8px",borderRadius:20}}>-{activeDiscount(p)}%</span>}
        {Heart}
        {ShareBtn}
        {soon&&<div style={{position:"absolute",inset:0,background:"rgba(8,54,64,.55)",display:"flex",alignItems:"center",justifyContent:"center"}}><span style={{color:"white",fontSize:12,fontWeight:800,letterSpacing:1,background:"rgba(0,0,0,.3)",padding:"4px 12px",borderRadius:20}}>COMING SOON</span></div>}
        {!soon&&oos&&<div style={{position:"absolute",inset:0,background:"rgba(0,0,0,.45)",display:"flex",alignItems:"center",justifyContent:"center"}}><span style={{color:"white",fontSize:12,fontWeight:700}}>Sold Out</span></div>}
      </div>
      <div style={{padding:"11px 12px 12px"}}>
        <div style={{fontSize:9,color:C.accent,fontWeight:700,textTransform:"uppercase",letterSpacing:.8,marginBottom:5}}>{p.category}</div>
        <div style={{fontSize:13,fontWeight:700,color:C.text,lineHeight:1.3,marginBottom:6,minHeight:33}}>{p.name}</div>
        {soon ? (
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:8}}>
            <div style={{fontSize:10,color:C.accent,fontWeight:700}}>Launching soon</div>
            <button className="press" onClick={e=>{e.stopPropagation();if(!isInterested&&onInterest)onInterest(p);}} disabled={isInterested}
              style={{background:isInterested?"#dcfce7":C.accent,color:isInterested?"#15803d":"white",border:"none",borderRadius:12,padding:"6px 12px",fontSize:11,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:isInterested?"default":"pointer"}}>
              {isInterested?"✓ Interested":"🔔 Interested"}
            </button>
          </div>
        ) : (<>
        <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:6}}>
          {multi&&<span style={{fontSize:10,color:C.textSub,fontWeight:700,whiteSpace:"nowrap"}}>Starts from</span>}
          <div style={{fontFamily:PRICE_FONT,fontSize:16,fontWeight:800,color:C.primary}}>₹{eff}</div>
          {onSale&&!multi&&<div style={{fontSize:11,color:C.textSub,textDecoration:"line-through"}}>₹{p.price}</div>}
        </div>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:8}}>
          <div className={!oos&&stk<=3?"festival-pulse":""} style={{fontSize:10,color:stk<10?C.coral:C.textSub,fontWeight:700}}>
            {oos?"Out of stock":stk<=3?`🔥 Only ${stk} left`:stk<10?`Only ${stk} left`:"In stock"}
          </div>
          {inCart>0 ? (
            <div style={{display:"flex",alignItems:"center",background:C.primary,borderRadius:12,padding:"3px 4px",gap:4}}>
              <button onClick={e=>{e.stopPropagation();onAdd(p,-1);}}
                style={{background:"transparent",border:"none",color:"white",fontSize:16,fontWeight:700,width:22,height:22,lineHeight:1,cursor:"pointer"}}>−</button>
              <span style={{fontSize:12,fontWeight:800,color:"white",minWidth:14,textAlign:"center"}}>{inCart}</span>
              <button onClick={e=>{e.stopPropagation();if(remaining>0)onAdd(p,1);}} disabled={remaining<=0}
                style={{background:"transparent",border:"none",color:"white",fontSize:16,fontWeight:700,width:22,height:22,lineHeight:1,cursor:remaining>0?"pointer":"not-allowed",opacity:remaining>0?1:.45}}>+</button>
            </div>
          ) : (
            <button className="cta" onClick={e=>{e.stopPropagation();if(oos)return;
                if(multi){ onPress(p); return; }            // let the customer pick the option first
                onAdd(p,1);flyToCart(e.clientX,e.clientY,imgSrc);}} disabled={oos}
              style={{background:oos?"#e5e7eb":C.coral,color:oos?C.textSub:"white",border:"none",borderRadius:99,padding:"7px 16px",fontSize:11,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:oos?"not-allowed":"pointer",whiteSpace:"nowrap"}}>
              {multi?"Select":"+ Add"}
            </button>
          )}
        </div>
        <div style={{display:"flex",alignItems:"center",gap:4,marginTop:8}}>
          {(p.reviewCount||0)>0 ? (
            <>
              {[1,2,3,4,5].map(s=><span key={s} className={s<=Math.round(p.ratingAvg||0)?"stars":"stars-dim"} style={{fontSize:11}}>★</span>)}
              <span style={{fontSize:11,color:C.textSub,marginLeft:2}}>{(p.ratingAvg||0).toFixed(1)} ({p.reviewCount})</span>
            </>
          ) : (
            <span style={{fontSize:11,color:C.textSub}}>No ratings yet</span>
          )}
        </div>
        {/* Flash sale countdown — shown when product has offerEndsAt in the future */}
        {!soon&&activeDiscount(p)>0&&p.offerEndsAt&&(
          <MiniCountdown endsAt={p.offerEndsAt} compact/>
        )}
        </>)}
      </div>
    </div>
  );
}

/* ═══════════════════ FORCE REFRESH ═══════════════════ */
/* Two separate caches can hold a device on old content, and neither clears itself
   promptly on a slow phone:
     • sw.js serves app code network-first but gives up after 1.5s and serves the
       cached copy — on a weak connection the ~900 KB bundle loses that race every
       time, so the device keeps running the previous build.
     • the catalogue paints from the "nemo-products" localStorage copy before the
       cloud answers, and a first run with no cloud reply writes DEFAULT_PRODUCTS
       there — after which the seed catalogue persists until a cloud read lands.
   This button drops everything the app controls and reloads clean. Sign-in, cart,
   orders and favourites are deliberately left alone; only cached copies of data
   that lives on the server are removed, and those come straight back on boot. */
/* Written by scripts/build.mjs into version.json and sw.js — bump it here only. */
const APP_BUILD = "v90.b8a332f9";
async function forceRefresh(){
  /* The cached copies of products, guides and settings are deliberately NOT deleted here.
     They used to be, on the reasoning that "those come straight back on boot" — which is true
     only while the cloud still has them. When it does not, this was the last copy in
     existence, and dropping it turned a quiet cloud-side gap into visible data loss on every
     device at once, the moment an update rolled out. They are overwritten by the first
     successful cloud read anyway, so deleting them bought nothing and risked everything.
     What this function is actually for — a stale BUNDLE — is handled by the cache and worker
     clearing below. */
  try{ if(window.caches){ const keys=await caches.keys(); await Promise.all(keys.map(k=>caches.delete(k))); } }catch(e){}
  // Unregistering means a brand-new worker installs and re-precaches on the next load.
  try{ if(navigator.serviceWorker){ const regs=await navigator.serviceWorker.getRegistrations(); await Promise.all(regs.map(r=>r.unregister())); } }catch(e){}
  // Reload past the browser's own HTTP cache too — clearing the SW alone does not cover it.
  try{ const u=new URL(location.href); u.searchParams.set("fresh",Date.now().toString(36)); location.replace(u.toString()); }
  catch(e){ location.reload(true); }
}
/* Drop the cache-buster from the address bar once it has done its job, so it is not
   carried into shared links or bookmarks. */
try{
  if(typeof location!=="undefined" && /[?&]fresh=/.test(location.search)){
    const u=new URL(location.href); u.searchParams.delete("fresh");
    history.replaceState(null,"",u.pathname+(u.search||"")+u.hash);
  }
}catch(e){}

/* ═══ AUTOMATIC UPDATE ═══
   Nobody should have to press Refresh to stop seeing an old build. The service worker
   serves app code network-first but falls back to the cached copy after 1.5s, so a phone
   on a weak link can boot the previous ~900 KB bundle indefinitely — the fetch that would
   have replaced it never wins the race.

   version.json is a few dozen bytes and is excluded from every cache, so it lands even
   where the bundle would not. If it names a build other than the one running, the code in
   memory is stale: drop the caches and reload into the new one. The whole check costs one
   tiny request per load.

   Capped at one automatic reload per tab. If the reload somehow comes back still stale
   (a CDN mid-purge, say), the visitor keeps browsing the old build rather than being
   trapped in a reload loop — the manual Refresh button in the menu is the way out. */
async function checkForUpdate(){
  try{
    if(!APP_BUILD) return;
    if(sessionStorage.getItem("nemo-autoreload")) return;   // already tried once in this tab
    const r=await fetch("version.json?t="+Date.now(),{cache:"no-store"});
    if(!r.ok) return;
    const v=await r.json();
    if(!v||!v.build||v.build===APP_BUILD) return;
    sessionStorage.setItem("nemo-autoreload",APP_BUILD+"->"+v.build);
    await forceRefresh();
  }catch(e){ /* offline, or version.json not deployed yet — keep serving what we have */ }
}
if(typeof window!=="undefined"){
  // After first paint: the check must never delay the store appearing.
  if(document.readyState==="complete") setTimeout(checkForUpdate,0);
  else window.addEventListener("load",()=>setTimeout(checkForUpdate,0));
  // A PWA tab can sit backgrounded for days and is reopened rather than reloaded, so the
  // load event alone would never fire again. Re-check when it comes back to the front.
  document.addEventListener("visibilitychange",()=>{ if(!document.hidden) checkForUpdate(); });
}

/* ═══════════════════ CATEGORY DRAWER (left slide-in) ═══════════════════ */
/* The referral card sits at the top of the drawer, above the category list, and resolves
   asynchronously — so its height is the one thing in the panel that can move everything else.
   Pinned, rather than left to the content. */
const REFERRAL_CARD_MIN = 116;
function ReferralDrawerCard({open,user,settings={},orders=[],nav,onClose}){
  const [status,setStatus]=useState(null);
  const [loading,setLoading]=useState(false);
  const [copied,setCopied]=useState(false);
  const uk=userKey(user);
  /* What the answer actually depends on. `orders` was in the dependency list, and it is a new
     array on most renders, so the drawer re-asked the server for a status that had not changed.
     Paid spend is the only part of it this card reads. */
  const spend=successfulSpend(orders);
  useEffect(()=>{ if(!uk||settings.referralEnabled===false) setStatus(null); },[uk,settings.referralEnabled]);
  useEffect(()=>{
    if(!open||!uk||settings.referralEnabled===false) return;
    let alive=true; setLoading(true);
    customerReferralStatus(uk,settings,orders).then(s=>{ if(alive){setStatus(s);setLoading(false);} }).catch(()=>{if(alive)setLoading(false);});
    return ()=>{alive=false;};
  },[open,uk,spend,settings.referralEnabled,settings.referralLifetimeSpendMin]);
  /* Held across closes. Clearing it when the drawer shut meant every reopen went back through
     "Loading your referral code…" and then grew into a full card, shoving the whole category
     list down the panel each time. Keeping the last answer means the second open is instant
     and still refreshes underneath. */
  if(settings.referralEnabled===false) return null;
  if(!uk) return(
    <div style={{margin:"2px 0 12px",background:"linear-gradient(135deg,#ede9fe,#eef2ff)",border:"1px solid #c4b5fd",borderRadius:16,padding:"12px"}}>
      <div style={{fontSize:12,fontWeight:800,color:"#5b21b6",marginBottom:3}}>🎟️ Your referral code</div>
      <div style={{fontSize:11,color:"#6d28d9",lineHeight:1.45,marginBottom:8}}>Sign in to see your spend progress and unlock your unique code.</div>
      <button className="press" onClick={()=>{onClose&&onClose();nav&&nav("auth");}}
        style={{width:"100%",background:"#6d28d9",color:"white",border:"none",borderRadius:8,padding:"8px",fontSize:11,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>Sign in</button>
    </div>
  );
  /* One height for all three states — loading, locked and unlocked. They are within a few
     pixels of each other, and the categories sit directly underneath: a card that grows as it
     resolves moves the thing the customer is reaching for. */
  const CARD={margin:"2px 0 12px",borderRadius:16,padding:"12px",minHeight:REFERRAL_CARD_MIN,boxSizing:"border-box"};
  if(loading&&!status) return(
    <div style={{...CARD,background:C.bg,border:`1px solid ${C.border}`}} aria-busy="true">
      <div style={{fontSize:12,fontWeight:800,color:C.textSub,marginBottom:8}}>🎟️ Your referral code</div>
      <div className="shimmer-bar" style={{height:10,borderRadius:8,marginBottom:7}}/>
      <div className="shimmer-bar" style={{height:10,borderRadius:8,width:"75%",marginBottom:12}}/>
      <div className="shimmer-bar" style={{height:31,borderRadius:8}}/>
    </div>
  );
  if(!status) return null;
  const pct=status.threshold<=0?100:Math.min(100,Math.round((status.spent/status.threshold)*100));
  return(
    <div style={{...CARD,background:status.unlocked?"linear-gradient(135deg,#7c3aed,#4f46e5)":"linear-gradient(135deg,#f5f3ff,#eef2ff)",border:`1px solid ${status.unlocked?"#7c3aed":"#c4b5fd"}`,color:status.unlocked?"white":"#4c1d95"}}>
      <div style={{fontSize:12,fontWeight:800,marginBottom:3}}>🎟️ {status.unlocked?"Your referral code":"Referral code locked"}</div>
      {status.unlocked?(
        <>
          <div style={{fontSize:11,opacity:.9,lineHeight:1.45,marginBottom:8}}>Friends get {referralOfferLine(settings)} when they use this at checkout.{referralOwnerCoins(settings)>0?` You earn ${referralOwnerCoins(settings)} reward coins once their order is delivered.`:""}</div>
          <div style={{display:"flex",alignItems:"center",gap:7}}>
            <div style={{flex:1,background:"rgba(255,255,255,.18)",border:"1px dashed rgba(255,255,255,.55)",borderRadius:8,padding:"8px 7px",fontFamily:"monospace",fontSize:13,fontWeight:800,letterSpacing:1.2,textAlign:"center"}}>{status.code}</div>
            <button className="press" onClick={()=>{ try{navigator.clipboard.writeText(status.code);}catch(e){} try{navigator.share&&navigator.share({text:`Use ${status.code} at ${STORE_NAME} and get ${referralOfferLine(settings)}.`});}catch(e){} setCopied(true);setTimeout(()=>setCopied(false),1800); }}
              style={{background:copied?"white":"rgba(255,255,255,.24)",color:copied?"#6d28d9":"white",border:"1px solid rgba(255,255,255,.4)",borderRadius:8,padding:"9px 10px",fontSize:10,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>{copied?"✓ Copied":"Share"}</button>
          </div>
        </>
      ):(
        <>
          <div style={{fontSize:11,lineHeight:1.45,marginBottom:8}}>Spend ₹{status.remaining.toLocaleString("en-IN")} more successfully to unlock your permanent code.</div>
          <div style={{height:7,background:"#ddd6fe",borderRadius:99,overflow:"hidden"}}><div style={{height:"100%",width:pct+"%",background:"#7c3aed",borderRadius:99}}/></div>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:10,fontWeight:700,marginTop:5}}><span>₹{status.spent.toLocaleString("en-IN")} spent</span><span>₹{status.threshold.toLocaleString("en-IN")} goal</span></div>
        </>
      )}
    </div>
  );
}

function CategoryDrawer({open,onClose,onSelect,recent=[],onRecent,nav,user,settings={},orders=[]}){
  const go=(to)=>{ onClose&&onClose(); nav&&nav(to); };
  /* A drawer opened with a swipe has to close with one. It lives in a Portal under <body>, so
     the shell's tab-swipe handler never sees a touch on it — this is the drawer's own. The
     vertical guard is what keeps a flick down the category list from closing it. */
  const closeFrom=useRef(null);
  const onDrawerTouchStart=(e)=>{
    closeFrom.current=(e.touches&&e.touches.length===1)?{x:e.touches[0].clientX,y:e.touches[0].clientY}:null;
  };
  const onDrawerTouchEnd=(e)=>{
    const from=closeFrom.current; closeFrom.current=null;
    if(!from||!e.changedTouches||!e.changedTouches.length) return;
    const t=e.changedTouches[0], dx=t.clientX-from.x, dy=t.clientY-from.y;
    if(dx<-70&&Math.abs(dx)>Math.abs(dy)*2) onClose&&onClose();
  };
  const [refreshing,setRefreshing]=useState(false);
  const COMPANY=[{label:"About Us",to:"about"},{label:"Care Guides",to:"guides"},{label:"Request a Product",to:"request"},{label:"Track My Orders",to:"orders"}];
  const POLICIES=policyLinks([{label:"Live Guarantee",to:"policy-guarantee"},{label:"Cancellations, Returns & Refunds",to:"policy-returns",href:"/cancellations-returns-refunds"},{label:"Terms & Conditions",to:"policy-terms"},{label:"Privacy Policy",to:"policy-privacy"},{label:"Contact Us",to:"contact",href:"/contact-us"}]);
  return(
    /* Portal: the drawer sits inside the page's .slide-up wrapper, whose held identity
       matrix traps position:fixed — the overlay was being sized to the whole home page
       (~2000px) instead of the viewport, which is what made the background jump and
       repaint on open/close. Rendering under <body> makes it truly viewport-fixed.
       `visibility` then keeps the closed drawer out of the paint tree entirely. */
    <Portal>
    <div aria-hidden={!open} onTouchStart={onDrawerTouchStart} onTouchEnd={onDrawerTouchEnd}
      style={{position:"fixed",inset:0,zIndex:300,pointerEvents:open?"auto":"none",
      visibility:open?"visible":"hidden",transition:open?"visibility 0s":"visibility 0s linear .3s"}}>
      {/* Scrim — plain opacity fade. A toggled backdrop-filter forces the browser to build a
          blur layer mid-animation, which is what "crashed" the background on the first open. */}
      <div onClick={onClose} style={{position:"absolute",inset:0,background:"rgba(7,32,35,.5)",opacity:open?1:0,transition:"opacity .28s ease",willChange:"opacity",touchAction:"none"}}/>
      {/* Panel — `overflow:hidden` here so the header can stay put and only the list scrolls */}
      <div style={{position:"absolute",top:0,bottom:0,left:0,width:"78%",maxWidth:300,background:C.card,boxShadow:"6px 0 30px rgba(0,0,0,.25)",transform:open?"translateX(0)":"translateX(-104%)",transition:"transform .3s cubic-bezier(.4,0,.2,1)",willChange:"transform",display:"flex",flexDirection:"column",overflow:"hidden"}}>
        {/* Frozen banner — stays visible while the categories below scroll */}
        <div style={{flexShrink:0,background:`linear-gradient(150deg,${C.primaryDark},${C.primary})`,padding:"46px 20px 18px",color:"white",position:"relative",zIndex:1}}>
          <button className="press" onClick={onClose} aria-label="Close menu"
            style={{position:"absolute",top:42,right:14,width:32,height:32,borderRadius:"50%",background:"rgba(255,255,255,.18)",border:"none",color:"white",fontSize:18,cursor:"pointer",lineHeight:1}}>×</button>
          <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:20,fontWeight:800}}>Browse</div>
          <div style={{fontSize:11,color:"rgba(255,255,255,.8)",marginTop:2}}>Shop by category</div>
        </div>
        {/* Only this part scrolls; `overscroll-behavior:contain` stops the flick from
            carrying through to the page behind the drawer once the list hits its end. */}
        <div className="nemo-browse-scroll" style={{flex:1,minHeight:0,overflowY:"auto",WebkitOverflowScrolling:"touch",overscrollBehavior:"contain",padding:"12px 12px 18px"}}>
          <ReferralDrawerCard open={open} user={user} settings={settings} orders={orders} nav={nav} onClose={onClose}/>
          <button className="press" onClick={()=>onSelect("All")}
            style={{display:"flex",alignItems:"center",gap:13,width:"100%",background:"transparent",border:"none",borderRadius:12,padding:"13px 12px",cursor:"pointer",fontFamily:"'Plus Jakarta Sans',sans-serif",textAlign:"left"}}>
            <span style={{fontSize:22,width:28,textAlign:"center"}}>🌊</span>
            <span style={{fontSize:14,fontWeight:800,color:C.text}}>All Products</span>
          </button>
          {shopCategories().map(cat=>(
            <button key={cat} className="press" onClick={()=>onSelect(cat)}
              style={{display:"flex",alignItems:"center",gap:13,width:"100%",background:"transparent",border:"none",borderTop:`1px solid ${C.border}`,padding:"13px 12px",cursor:"pointer",fontFamily:"'Plus Jakarta Sans',sans-serif",textAlign:"left"}}>
              <span style={{fontSize:22,width:28,textAlign:"center"}}>{CAT_META[cat].emoji}</span>
              <span style={{fontSize:14,fontWeight:700,color:C.text}}>{cat}</span>
              <span style={{marginLeft:"auto",color:C.textSub,fontSize:16}}>›</span>
            </button>
          ))}
          {recent.length>0&&(
            <div style={{marginTop:18,paddingTop:6}}>
              <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"0 12px",marginBottom:8}}>
                <span style={{fontSize:11,fontWeight:800,color:C.textSub,textTransform:"uppercase",letterSpacing:.6}}>Recent searches</span>
                <button className="press" onClick={()=>onRecent&&onRecent(null)} style={{background:"none",border:"none",color:C.textSub,fontSize:10,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>Clear</button>
              </div>
              <div style={{display:"flex",flexWrap:"wrap",gap:7,padding:"0 12px"}}>
                {recent.map(r=>(
                  <button key={r} className="press" onClick={()=>onRecent&&onRecent(r)}
                    style={{background:C.bg,border:`1px solid ${C.border}`,borderRadius:20,padding:"6px 12px",fontSize:12,fontWeight:600,color:C.text,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>
                    🔍 {r}
                  </button>
                ))}
              </div>
            </div>
          )}
          {/* Dedicated refresh — for a device stuck on an old build or a stale catalogue */}
          <div style={{marginTop:16,borderTop:`1px solid ${C.border}`,paddingTop:14}}>
            <button className="press" onClick={()=>{ if(refreshing)return; setRefreshing(true); forceRefresh(); }} disabled={refreshing}
              style={{display:"flex",alignItems:"center",gap:11,width:"100%",background:C.bg,border:`1px solid ${C.border}`,borderRadius:12,padding:"12px",cursor:refreshing?"default":"pointer",fontFamily:"'Plus Jakarta Sans',sans-serif",textAlign:"left"}}>
              <span style={{fontSize:20,width:26,textAlign:"center",flexShrink:0}}>{refreshing?"⏳":"🔄"}</span>
              <span style={{minWidth:0}}>
                <span style={{display:"block",fontSize:13,fontWeight:800,color:C.text}}>{refreshing?"Refreshing…":"Refresh app"}</span>
                <span style={{display:"block",fontSize:11,color:C.textSub,marginTop:1,lineHeight:1.35}}>Clear the cache and reload the latest products &amp; prices</span>
              </span>
            </button>
            <div style={{fontSize:10,color:C.textSub,textAlign:"center",marginTop:7,letterSpacing:.4}}>Build {APP_BUILD}</div>
          </div>
          {nav&&(
            <div style={{marginTop:18,borderTop:`1px solid ${C.border}`,paddingTop:12}}>
              <div style={{fontSize:11,fontWeight:800,color:C.textSub,textTransform:"uppercase",letterSpacing:.6,padding:"0 12px",marginBottom:4}}>Company</div>
              {COMPANY.map(l=>(
                <button key={l.label} className="press" onClick={()=>go(l.to)}
                  style={{display:"block",width:"100%",textAlign:"left",background:"none",border:"none",padding:"9px 12px",fontSize:13,fontWeight:700,color:C.text,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>{l.label}</button>
              ))}
              <div style={{fontSize:11,fontWeight:800,color:C.textSub,textTransform:"uppercase",letterSpacing:.6,padding:"0 12px",margin:"20px 0 4px",borderTop:`1px solid ${C.border}`,paddingTop:16}}>Policies</div>
              {POLICIES.map(l=>(
                <a key={l.label} className="press" href={l.href||"#"} onClick={e=>{e.preventDefault();go(l.to);}}
                  style={{display:"block",width:"100%",textAlign:"left",background:"none",border:"none",padding:"9px 12px",fontSize:13,fontWeight:700,color:C.text,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer",textDecoration:"none",boxSizing:"border-box"}}>{l.label}</a>
              ))}
            </div>
          )}
          {/* The desktop footer is hidden on phones, so the app offer lives here instead */}
          <PlayAppBlock medium="side_menu" note="Shop and track your orders from your phone."
            style={{marginTop:20,borderTop:`1px solid ${C.border}`,paddingTop:16}}
            headingStyle={{fontSize:11,fontWeight:800,color:C.textSub,textTransform:"uppercase",letterSpacing:.6,padding:"0 12px",marginBottom:4}}
            noteStyle={{fontSize:12,color:C.textSub,lineHeight:1.5,padding:"0 12px"}}
            badgeStyle={{marginLeft:3}}/>
        </div>
      </div>
    </div>
    </Portal>
  );
}

/* ═══════════════════ HOME PAGE ═══════════════════ */
/* Food re-order reminder banner — shown on home when a consumable is due to run out. */
function FoodReorderBanner({orders,products,addToCart,nav}){
  const due=useMemo(()=>foodReorderDue(orders,products,30),[orders,products]);
  const [dismissed,setDismissed]=useState(()=>{ try{ return localStorage.getItem("nemo-reorder-dismiss")===((due&&due.key)||"\u0000"); }catch{ return false; } });
  if(!due||dismissed) return null;
  const inStock=due.product&&!due.product.comingSoon&&(due.product.stockCount??DEFAULT_STOCK)>0;
  const reorder=()=>{ if(inStock){ addToCart(due.product,1); nav("cart"); } else if(due.product){ nav("detail",due.product); } };
  const dismiss=()=>{ try{ localStorage.setItem("nemo-reorder-dismiss",due.key); }catch{} setDismissed(true); };
  return(
    <div style={{marginBottom:22,background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:20,padding:"14px 30px 14px 16px",display:"flex",alignItems:"center",gap:13,position:"relative"}}>
      <div style={{width:44,height:44,borderRadius:12,background:"#ffedd5",display:"flex",alignItems:"center",justifyContent:"center",fontSize:24,flexShrink:0}}>🥣</div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:14,fontWeight:800,color:"#9a3412",lineHeight:1.2}}>Running low on fish food?</div>
        <div style={{fontSize:11,color:"#9a3412",opacity:.85,marginTop:2,lineHeight:1.4}}>You bought {due.item.name} about {due.ageDays} days ago — keep your fish well-fed.</div>
      </div>
      <button className="press" onClick={reorder}
        style={{flexShrink:0,background:C.coral,color:"white",border:"none",borderRadius:12,padding:"10px 14px",fontSize:12,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
        {inStock?"Reorder":"View"}
      </button>
      <button className="press" onClick={dismiss} aria-label="Dismiss"
        style={{position:"absolute",top:6,right:8,background:"none",border:"none",color:"#9a3412",opacity:.5,fontSize:16,cursor:"pointer",lineHeight:1,padding:4}}>×</button>
    </div>
  );
}
/* ═══════════════════ DOA INSIGHTS (admin) ═══════════════════ */
/* Aggregates Dead-on-Arrival reports across delivered live-fish orders by species,
   destination zone, and season — so the owner can spot loss patterns and act. */
function DoaInsights({orders=[]}){
  const data=useMemo(()=>{
    const seasonOf=iso=>{ const m=new Date(iso||0).getMonth(); return m>=2&&m<=5?"☀️ Summer (Mar–Jun)":m>=6&&m<=9?"🌧️ Monsoon (Jul–Oct)":"❄️ Winter (Nov–Feb)"; };
    const deliveredLive=(orders||[]).filter(o=>o.status==="Delivered"&&(o.items||[]).some(it=>it.category==="Live Fish"));
    const doaOrders=deliveredLive.filter(o=>o.doa);
    const species={},zone={},season={};
    const bump=(m,k,f)=>{ m[k]=m[k]||{d:0,doa:0}; m[k][f]++; };
    deliveredLive.forEach(o=>{
      bump(zone,o.shippingZoneLabel||"Unknown","d");
      bump(season,seasonOf(o.placedAt),"d");
      new Set((o.items||[]).filter(it=>it.category==="Live Fish").map(it=>it.name)).forEach(nm=>bump(species,nm,"d"));
    });
    doaOrders.forEach(o=>{
      bump(zone,o.shippingZoneLabel||"Unknown","doa");
      bump(season,seasonOf(o.placedAt),"doa");
      new Set((o.items||[]).filter(it=>it.category==="Live Fish").map(it=>it.name)).forEach(nm=>{ if(species[nm]) species[nm].doa++; });
    });
    return { total:deliveredLive.length, doa:doaOrders.length, species, zone, season, doaOrders };
  },[orders]);
  const [open,setOpen]=useState(false);
  if(data.total===0) return null;
  const overall=data.total?((data.doa/data.total)*100):0;
  const rateColor=r=>r>=20?"#dc2626":r>=10?"#c2410c":"#15803d";
  const rows=(map,{onlyDoa=false,sortByRate=false}={})=>{
    let arr=Object.entries(map).map(([k,v])=>({k,...v,rate:v.d?(v.doa/v.d)*100:0}));
    if(onlyDoa) arr=arr.filter(x=>x.doa>0);
    arr.sort((a,b)=> sortByRate ? b.rate-a.rate : b.doa-a.doa);
    return arr;
  };
  const Section=({title,map,opts})=>{
    const arr=rows(map,opts);
    if(!arr.length) return null;
    return(
      <div style={{marginTop:12}}>
        <div style={{fontSize:11,fontWeight:800,color:C.textSub,textTransform:"uppercase",letterSpacing:.6,marginBottom:6}}>{title}</div>
        {arr.map(x=>(
          <div key={x.k} style={{display:"flex",alignItems:"center",gap:8,padding:"7px 0",borderTop:`1px solid ${C.border}`}}>
            <span style={{flex:1,fontSize:12,fontWeight:600,color:C.text,minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{x.k}</span>
            <span style={{fontSize:11,color:C.textSub,fontWeight:600}}>{x.doa}/{x.d}</span>
            <span style={{fontSize:12,fontWeight:800,color:rateColor(x.rate),minWidth:46,textAlign:"right"}}>{x.rate.toFixed(0)}%</span>
          </div>
        ))}
      </div>
    );
  };
  return(
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:16,padding:"14px 16px",marginBottom:14}}>
      <button className="press" onClick={()=>setOpen(o=>!o)} style={{display:"flex",alignItems:"center",gap:10,width:"100%",background:"none",border:"none",padding:0,cursor:"pointer",textAlign:"left"}}>
        <span style={{fontSize:18}}>🩺</span>
        <div style={{flex:1}}>
          <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:14,fontWeight:800,color:C.text}}>DOA Insights</div>
          <div style={{fontSize:11,color:C.textSub,marginTop:1}}>{data.doa} DOA of {data.total} delivered live-fish orders</div>
        </div>
        <span style={{fontFamily:PRICE_FONT,fontSize:20,fontWeight:800,color:rateColor(overall)}}>{overall.toFixed(1)}%</span>
        <span style={{fontSize:13,color:C.textSub,marginLeft:6}}>{open?"▲":"▼"}</span>
      </button>
      {open&&(data.doa===0?(
        <div style={{marginTop:12,fontSize:12,color:"#15803d",fontWeight:600,background:"#ecfdf5",borderRadius:12,padding:"10px 12px"}}>✓ No DOA reported yet — your fish are arriving safe!</div>
      ):(
        <div>
          {/* The rates say WHERE losses cluster; this says WHICH orders they were, so a number
              that looks wrong can be traced back to the actual order instead of being taken on
              trust. Newest first — the ones still open are the ones being chased. */}
          <div style={{marginTop:12}}>
            <div style={{fontSize:11,fontWeight:800,color:C.textSub,textTransform:"uppercase",letterSpacing:.6,marginBottom:6}}>Orders with a DOA claim</div>
            {[...data.doaOrders]
              .sort((a,b)=>String(deliveredAtOf(b)||b.placedAt||"").localeCompare(String(deliveredAtOf(a)||a.placedAt||"")))
              .map(o=>{
                const st=(o.doa&&o.doa.status)||"Requested";
                const claims=Object.values(o.doaItems||{});
                const col=st==="Declined"?"#dc2626":st.startsWith("Approved")?"#15803d":"#c2410c";
                return(
                  <div key={o.id} style={{padding:"8px 0",borderTop:`1px solid ${C.border}`}}>
                    <div style={{display:"flex",alignItems:"baseline",gap:8,flexWrap:"wrap"}}>
                      <code style={{fontSize:12,fontWeight:800,color:C.text,fontFamily:"monospace"}}>{o.orderNo||orderId(o.id)}</code>
                      <span style={{fontSize:10,color:C.textSub}}>{o.shippingZoneLabel||"Unknown"}</span>
                      <span style={{fontSize:10,fontWeight:800,color:col,marginLeft:"auto"}}>{st}</span>
                    </div>
                    <div style={{fontSize:10,color:C.textSub,marginTop:2,lineHeight:1.45}}>
                      {claims.length
                        ? claims.map(c=>`${c.name||"Item"} x${c.qty||1}${c.cause?` (${c.cause})`:""}`).join(" · ")
                        : (o.doa&&o.doa.claimReason)||"No item detail recorded"}
                    </div>
                  </div>
                );
              })}
          </div>
          <Section title="By species (most losses)" map={data.species} opts={{onlyDoa:true,sortByRate:true}}/>
          <Section title="By destination zone" map={data.zone} opts={{sortByRate:true}}/>
          <Section title="By season" map={data.season} opts={{sortByRate:true}}/>
          <div style={{fontSize:10,color:C.textSub,marginTop:10,lineHeight:1.5,fontStyle:"italic"}}>Rate = DOA orders ÷ delivered live-fish orders for that group. Use high-rate species/zones to adjust packing, pause distant shipping in hot months, or pre-order delicate stock.</div>
        </div>
      ))}
    </div>
  );
}

