/* ═══════════════════ SINGLE POLICY PAGE ═══════════════════ */
const POLICY_META_ALL = {
  guarantee:   { icon:"🛡️", title:"Live Arrival Guarantee", key:"liveArrivalGuarantee", sub:"Our promise on every live order." },
  returns:     { icon:"↩️", title:"Cancellations, Returns & Refunds", key:"returnPolicy", sub:"Cancellations, returns, DOA claims & refunds." },
  acclimatize: { icon:"💧", title:"Acclimatization Guide",   key:"acclimatizationTips",  sub:"Settle your new arrivals in safely." },
  terms:       { icon:"📜", title:"Terms & Conditions",      key:"termsPolicy",          sub:"The terms you agree to when ordering." },
  privacy:     { icon:"🔒", title:"Privacy Policy",          key:"privacyPolicy",        sub:"How we handle your information." },
  delivery:    { icon:"🚚", title:"Delivery Areas",          key:"deliveryAreas",        sub:"Where and how we deliver." },
};
/* Built by filtering the complete map rather than by assembling a shorter one, so the order the
   policies appear in comes back exactly as it was when live fish do. An old bookmark to a hidden
   policy falls through to Terms below rather than rendering an empty page. */
const policyMeta = () => LIVE_FISH_ENABLED ? POLICY_META_ALL : Object.fromEntries(
  Object.entries(POLICY_META_ALL).filter(([k]) => k!=="guarantee" && k!=="acclimatize"));
/* Two headings carry no icon. A padlock beside "Privacy Policy", or a return arrow beside
   "Cancellations, Returns & Refunds", is decoration on the two pages a customer opens when
   something has gone wrong or while deciding whether to trust the shop with their address —
   and decoration there reads as a shop being playful about a document that binds it. Keyed off
   meta.key rather than `which` so an old bookmark that falls through to Terms is judged by the
   page it actually lands on. The chips under "More policies" keep their icons: there they are
   how six similar buttons are told apart at a glance. */
const POLICY_TITLE_BARE = { privacyPolicy:true, returnPolicy:true };
function PolicyPage({nav,goBack,settings={},which}){
  const POLICY_META=policyMeta();
  const s={...DEFAULT_SETTINGS,...settings};
  const meta=POLICY_META[which]||POLICY_META.terms;
  const others=Object.keys(POLICY_META).filter(k=>k!==which);
  return(
    <div className="slide-up">
      <HeroHeader onBack={goBack} title={POLICY_TITLE_BARE[meta.key]?meta.title:<>{meta.icon} {meta.title}</>}
        subtitle={meta.sub}/>
      <div className="dt-read" style={{padding:"18px 16px 100px"}}>
        <div style={{background:C.card,borderRadius:20,padding:"20px",border:`1px solid ${C.border}`,fontSize:13,color:C.textSub,lineHeight:1.8,whiteSpace:"pre-wrap"}}>{policyText(meta.key, s)}</div>
        {/* The tracking & collection clause is part of the terms whether or not the saved text
            carries it — a store that customised its terms before this clause existed would
            otherwise show terms that don't match what checkout tells the customer. Shown only
            when the saved text doesn't already cover it, so it never appears twice. */}
        {which==="terms" && !/collect it from the courier/i.test(String(s.termsPolicy||"")) && (
          <div style={{background:"#fffbeb",border:"1px solid #fde68a",borderRadius:20,padding:"18px 20px",marginTop:12}}>
            <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
              <span style={{fontSize:16}}>📦</span>
              <span style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:14,fontWeight:800,color:"#92400e"}}>Tracking &amp; collection</span>
            </div>
            <div style={{fontSize:13,color:"#78350f",lineHeight:1.75}}>{courierCollectTerm().replace(/^Tracking & collection: /,"")}</div>
          </div>
        )}
        <div style={{fontSize:11,fontWeight:800,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,margin:"22px 4px 10px"}}>More policies</div>
        <div style={{display:"flex",flexWrap:"wrap",gap:8}}>
          {others.map(k=>(
            <button key={k} className="press" onClick={()=>nav("policy-"+k)}
              style={{display:"inline-flex",alignItems:"center",gap:7,background:C.card,border:`1.5px solid ${C.border}`,borderRadius:12,padding:"9px 13px",fontSize:12,fontWeight:700,color:C.text,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>
              <span>{POLICY_META[k].icon}</span>{POLICY_META[k].title}
            </button>
          ))}
        </div>
        {s.ownerWhatsapp&&(
          <div style={{textAlign:"center",marginTop:22}}>
            <a href={`https://wa.me/${s.ownerWhatsapp.replace(/\D/g,"")}`} target="_blank" rel="noopener"
              style={{display:"inline-flex",alignItems:"center",gap:8,background:"#25D366",color:"white",borderRadius:16,padding:"13px 24px",fontSize:14,fontWeight:700,textDecoration:"none"}}>
              💬 Questions? Chat with us
            </a>
          </div>
        )}
      </div>
    </div>
  );
}

/* ═══════════════════ PRODUCT REQUEST PAGE ═══════════════════ */
function RequestPage({nav,goBack,user,onSubmit,myRequests}){
  const [form,setForm]=useState({product:"",brand:"",link:"",qty:"1",notes:"",name:user?.name||"",phone:user?.phone||""});
  const [imgB64,setImgB64]=useState(null);
  const [imgPrev,setImgPrev]=useState(null);
  const [imgNote,setImgNote]=useState("");
  const [errs,setErrs]=useState({});
  const [saving,setSaving]=useState(false);
  const [done,setDone]=useState(false);
  const f=(k,v)=>setForm(p=>({...p,[k]:v}));

  const handleImg=async file=>{
    if(!file)return;
    setImgNote("Processing…");
    const b64=await fileToBase64(file);
    setImgB64(b64);setImgPrev(b64);
    setImgNote(`✓ ${fmtSize(file.size)} ready`);
  };

  const submit=async()=>{
    const e={};
    if(!form.product.trim())e.product="What product are you looking for?";
    if(!form.name.trim())e.name="Please enter your name";
    if(!/^[6-9]\d{9}$/.test(normalizePhone(form.phone)))e.phone="Valid 10-digit number required";
    setErrs(e);
    if(Object.keys(e).length)return;
    setSaving(true);
    const id=uid("req");
    const req={id,product:form.product.trim(),brand:form.brand.trim(),link:form.link.trim(),
      qty:form.qty,notes:form.notes.trim(),name:form.name.trim(),phone:normalizePhone(form.phone),
      hasImg:!!imgB64,status:"New",createdAt:new Date().toISOString()};
    try{
      await onSubmit(req,imgB64);
      setDone(true);                 // only claim success if it actually went through
    }catch(err){ console.error("request submit",err); setErrs({submit:"Couldn't send your request — please try again"}); }
    finally{ setSaving(false); }
  };

  if(done)return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",minHeight:"80vh",padding:"24px",textAlign:"center"}}>
      <div style={{width:80,height:80,borderRadius:"50%",background:"#dcfce7",display:"flex",alignItems:"center",justifyContent:"center",fontSize:40,marginBottom:20,animation:"checkPop .4s ease both"}}>✓</div>
      <div style={{fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:22,fontWeight:800,color:C.text,marginBottom:8}}>Request Sent! 🙌</div>
      <div style={{fontSize:14,color:C.textSub,lineHeight:1.7,marginBottom:24,maxWidth:300}}>We've received your request. We'll source it and reach out on WhatsApp if it's available.</div>
      <div style={{display:"flex",gap:10}}>
        <button className="press" onClick={()=>{setDone(false);setForm(f=>({...f,product:"",brand:"",link:"",notes:""}));setImgB64(null);setImgPrev(null);}}
          style={{background:"transparent",color:C.primary,border:`1.5px solid ${C.primary}`,borderRadius:16,padding:"13px 22px",fontSize:14,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>+ Another</button>
        <button className="press" onClick={()=>nav("home")}
          style={{background:C.primary,color:"white",border:"none",borderRadius:16,padding:"13px 28px",fontSize:14,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>Back Home</button>
      </div>
    </div>
  );

  return(
    <div className="slide-up">
      <HeroHeader onBack={goBack} title="Request a Product"
        gradient={`linear-gradient(150deg,${C.accent},${C.primary})`}
        subtitle={<>Rare fish, plants or special gear?<br/>Tell us what you need.<br/><b>We source hard-to-find products.</b></>}/>
      <div className="dt-read" style={{padding:"20px 16px 100px"}}>
        <div style={{marginBottom:16}}>
          <div style={{fontSize:12,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:6}}>Product Name *</div>
          <input value={form.product} onChange={e=>f("product",e.target.value)} placeholder="e.g. Galaxy Koi Betta, CO2 regulator…"
            style={{width:"100%",borderRadius:12,border:`1.5px solid ${errs.product?C.danger:C.border}`,padding:"12px 14px",fontSize:14,outline:"none",background:"white"}}/>
          {errs.product&&<div style={{fontSize:11,color:C.danger,fontWeight:600,marginTop:4}}>{errs.product}</div>}
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1.5fr 1fr",gap:12,marginBottom:16}}>
          <div>
            <div style={{fontSize:12,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:6}}>Brand <span style={{fontWeight:400,textTransform:"none"}}>(optional)</span></div>
            <input value={form.brand} onChange={e=>f("brand",e.target.value)} placeholder="e.g. Sera, Eheim"
              style={{width:"100%",borderRadius:12,border:`1.5px solid ${C.border}`,padding:"12px 14px",fontSize:14,outline:"none",background:"white"}}/>
          </div>
          <div>
            <div style={{fontSize:12,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:6}}>Qty</div>
            <input type="number" min="1" value={form.qty} onChange={e=>f("qty",e.target.value)}
              style={{width:"100%",borderRadius:12,border:`1.5px solid ${C.border}`,padding:"12px 14px",fontSize:14,outline:"none",background:"white"}}/>
          </div>
        </div>
        <div style={{marginBottom:16}}>
          <div style={{fontSize:12,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:6}}>Notes <span style={{fontWeight:400,textTransform:"none"}}>(optional)</span></div>
          <textarea value={form.notes} onChange={e=>f("notes",e.target.value)} rows={3} placeholder="Size, colour, variant, budget, or paste a product link here…"
            style={{width:"100%",borderRadius:12,border:`1.5px solid ${C.border}`,padding:"12px 14px",fontSize:14,outline:"none",resize:"none",lineHeight:1.6,background:"white"}}/>
        </div>
        <div style={{height:1,background:C.border,margin:"4px 0 16px"}}/>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:16}}>
          <div>
            <div style={{fontSize:12,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:6}}>Your Name *</div>
            <input value={form.name} onChange={e=>f("name",e.target.value)}
              style={{width:"100%",borderRadius:12,border:`1.5px solid ${errs.name?C.danger:C.border}`,padding:"12px 14px",fontSize:14,outline:"none",background:"white"}}/>
            {errs.name&&<div style={{fontSize:11,color:C.danger,fontWeight:600,marginTop:4}}>{errs.name}</div>}
          </div>
          <div>
            <div style={{fontSize:12,fontWeight:700,color:C.textSub,textTransform:"uppercase",letterSpacing:.8,marginBottom:6}}>Phone *</div>
            <input type="tel" value={form.phone} onChange={e=>f("phone",e.target.value.replace(/\D/g,""))} maxLength={10}
              style={{width:"100%",borderRadius:12,border:`1.5px solid ${errs.phone?C.danger:C.border}`,padding:"12px 14px",fontSize:14,outline:"none",background:"white"}}/>
            {errs.phone&&<div style={{fontSize:11,color:C.danger,fontWeight:600,marginTop:4}}>{errs.phone}</div>}
          </div>
        </div>
        {errs.submit&&<div style={{fontSize:12,color:C.danger,fontWeight:700,marginBottom:8,textAlign:"center"}}>{errs.submit}</div>}
        <button className="press" onClick={submit} disabled={saving}
          style={{width:"100%",background:C.primary,color:"white",border:"none",borderRadius:16,padding:"16px",fontSize:14,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif",display:"flex",alignItems:"center",justifyContent:"center",gap:8,opacity:saving?.7:1}}>
          {saving?<><Spinner/>Sending…</>:"📨 Send Request"}
        </button>
      </div>
    </div>
  );
}

/* ═══════════════════ ERROR BOUNDARY ═══════════════════ */
/* Catches any render/runtime error in the app tree and shows a friendly
   recovery screen instead of a blank white page. */
class ErrorBoundary extends React.Component {
  constructor(props){ super(props); this.state = { err: null }; }
  static getDerivedStateFromError(err){ return { err }; }
  componentDidCatch(err, info){ try{ console.error("App crashed:", err, info); }catch(e){} }
  render(){
    if(!this.state.err) return this.props.children;
    return (
      <div style={{minHeight:"100vh",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:16,padding:"32px 24px",textAlign:"center",fontFamily:"'Plus Jakarta Sans',system-ui,sans-serif",background:"#ffffff",color:C.text}}>
        <div style={{fontSize:52}}>🐠</div>
        <h1 style={{fontSize:22,fontWeight:800,margin:0}}>Something went wrong</h1>
        <p style={{fontSize:14,color:"#64748b",maxWidth:340,lineHeight:1.5,margin:0}}>The app hit an unexpected error. Reloading usually fixes it. If it keeps happening, message us on WhatsApp and we'll sort it out.</p>
        <button onClick={()=>{ try{ location.reload(); }catch(e){} }} style={{background:C.primary,color:"#fff",border:"none",borderRadius:16,padding:"14px 28px",fontSize:14,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer",boxShadow:"0 6px 20px rgba(14,165,233,.35)"}}>Reload</button>
      </div>
    );
  }
}

const DIRECT_PAGE_BY_PATH={
  "/contact-us":"contact",
  "/cancellations-returns-refunds":"policy-returns",
};
const DIRECT_PATH_BY_PAGE={contact:"/contact-us","policy-returns":"/cancellations-returns-refunds"};

/* ═══════════════════ ROOT APP ═══════════════════ */
function NemoStore(){
  const [page,setPage]             = useState(()=>DIRECT_PAGE_BY_PATH[window.location.pathname]||"home");
  const [products,setProducts]     = useState(DEFAULT_PRODUCTS);
  /* The one list every shopping surface reads. `products` stays complete — Admin still
     manages the hidden Live Fish catalogue and order history still renders the fish a
     past order contained — but Home, Shop, Search, Detail, Cart, Checkout, Saved and the
     mini cart all shop from this. Filtering here rather than at load is what makes the
     restore a single flag: nothing is deleted, it is simply not offered. */
  const shopProducts=useMemo(()=>shoppable(products),[products]);
  // Cold-start skeleton: true once we have real/cached data (returning visitors keep instant paint)
  const [hydrated,setHydrated]     = useState(()=>{ try{ return !!localProducts(); }catch(e){ return false; } });
  const [orders,setOrders]         = useState([]);
  const [requests,setRequests]     = useState([]);
  const [guides,setGuides]         = useState([]);
  const [settings,setSettingsState] = useState(DEFAULT_SETTINGS);
  /* Every settings write goes through here. LIVE_FISH_ENABLED is a module variable — it is read
     by helpers and pure functions that have no component to take props — so it has to be brought
     up to date BEFORE the render that follows, not in an effect afterwards. Wrapping the setter
     rather than patching each call site means a settings write added later cannot forget. */
  const setSettings = (next) => { applyLiveFishSwitch(next); setSettingsState(next); };
  const [settingsReady,setSettingsReady] = useState(false);
  const [user,setUser]             = useState(null);
  const [authReturn,setAuthReturn] = useState("orders"); // where to go after login
  const [reviewedSet,setReviewedSet] = useState([]);
  const [reviewIntent,setReviewIntent] = useState(null);
  const [reviewPreset,setReviewPreset]   = useState(0);
  const [favorites,setFavorites]   = useState([]);
  const [savedAddresses,setSavedAddresses] = useState([]);   // reusable delivery addresses (this device)
  const [interestedSet,setInterestedSet] = useState([]);
  const [interestCounts,setInterestCounts] = useState({});
  const [fbReady,setFbReady]       = useState(0);
  const [mediaCache,setMediaCache] = useState({});
  const [loading,setLoading]       = useState(true);
  const [showcase,setShowcase]     = useState([]);
  const [totmVotes,setTotmVotes]  = useState({});   // canonical _once ballots plus deduplicated legacy daily buckets
  const [tankPreviousWinners,setTankPreviousWinners] = useState(null);
  const [activeTankMonth,setActiveTankMonth] = useState(()=>totmMonthOf(Date.now()));
  const [testimonials,setTestimonials] = useState([]);
  // First Firebase community snapshots (including a valid empty result) must settle before
  // the cinematic opening lifts, otherwise these sections pop into an already-visible Home.
  const [communityReady,setCommunityReady] = useState(false);
  const [restockSet,setRestockSet] = useState(()=>loadRestockLocal().map(x=>x.pid));
  const [selProduct,setSelProduct] = useState(null);
  const [walletPts,setWalletPts]   = useState(0);
  const [walletReady,setWalletReady] = useState(false);
  /* The sixth boot gate: the webfont. Every other gate is about data; this one is about the
     page not re-typesetting itself a second after the shopper starts reading it. index.html
     starts the stylesheet immediately and reports the FACES being usable, not just the CSS. */
  const [fontsReady,setFontsReady] = useState(()=>{ try{ return window.__nemoFontsReady===true; }catch(e){ return true; } });
  // Cart persists across sessions (localStorage) — a returning shopper finds their items waiting,
  // which itself recovers otherwise-abandoned carts.
  // `shoppable` drops any live-fish line a shopper had in their basket from before the
  // switch was flipped, before the first render — so checkout can never price, ship or
  // charge for a hidden item. The cleaned cart is persisted by the effect that syncs it.
  const [cart,setCart]             = useState(()=>{ try{ return shoppable(JSON.parse(localStorage.getItem("nemo-cart")||"[]")||[]); }catch(e){ return []; } });
  const [abandonedCarts,setAbandonedCarts] = useState([]); // admin view of shoppers who left items behind
  const [query,setQuery]           = useState("");
  const [category,setCategory]     = useState("All");
  const [toast,setToast]           = useState(null);
  const scrollRef  = useRef(null);
  const vidUrlsRef = useRef({});
  const tapCount   = useRef(0);
  const tapTimer   = useRef(null);

  useEffect(()=>{
    const timer=setInterval(()=>setActiveTankMonth(month=>{ const next=totmMonthOf(Date.now()); return next===month?month:next; }),60000);
    return ()=>clearInterval(timer);
  },[]);

  const saveSettingsHandler=async(s)=>{
    if(isMainAdminUid(FB_AUTH&&FB_AUTH.currentUser&&FB_AUTH.currentUser.uid)){
      try{ await saveAdminAccess({coAdminUid:s.coAdminUid||"",permissions:s.coAdminPermissions||{}}); }catch(e){ showToast("Could not save co-admin access","error"); return; }
    }
    setSettings(s); await saveSettings(s); showToast("Settings saved");
  };

  /* ── Scrolling must never edit a value ────────────────────────────────────────
     A focused number field swallows the wheel and steps itself, so a shopper who
     scrolls the page while the cursor sits over a quantity box silently buys a
     different amount — and an admin scrolling down a product form quietly rewrites
     a price, a stock count or a GST rate. One document-level guard covers every
     such field in the app: drop focus and the wheel goes back to scrolling the
     page, leaving the entered value exactly as typed. A slider can't be fixed by
     blurring (some browsers step it on hover alone), so its wheel is swallowed and
     the scroll it was meant to do is passed on to the panel behind it. */
  useEffect(()=>{
    const scroller=el=>{
      for(let n=el&&el.parentElement;n;n=n.parentElement){
        const ov=getComputedStyle(n).overflowY;
        if((ov==="auto"||ov==="scroll")&&n.scrollHeight>n.clientHeight+1) return n;
      }
      return null;
    };
    const guard=e=>{
      const el=e.target;
      if(!el||!el.tagName) return;
      const tag=el.tagName.toUpperCase();
      const type=(el.type||"").toLowerCase();
      if(tag==="INPUT"&&type==="range"){
        e.preventDefault();
        const box=scroller(el);
        const lines=e.deltaMode===1, pages=e.deltaMode===2;
        const dy=e.deltaY*(lines?16:pages?((box?box.clientHeight:window.innerHeight)):1);
        if(box) box.scrollTop+=dy; else window.scrollBy(0,dy);
        return;
      }
      const stepsOnWheel = (tag==="INPUT"&&type==="number") || tag==="SELECT";
      if(stepsOnWheel&&document.activeElement===el) el.blur();
    };
    document.addEventListener("wheel",guard,{passive:false,capture:true});
    return ()=>document.removeEventListener("wheel",guard,{capture:true});
  },[]);

  const showToast=(msg,type="success")=>setToast({msg,type});

  // Load from storage
  // Load from storage — LOCAL first (instant), then hydrate from Firebase in the background
  const hydrateMedia=async(prods,reqs,guideList)=>{
    // Wave 1 — paint catalog thumbnails as fast as possible: just the FIRST image of each
    // product, pushed to the cache the moment they're ready. The full load (wave 2) still runs
    // below unchanged, so the final cache is identical and detail/admin galleries are unaffected.
    try{
      const firstWave={};
      await Promise.all(prods.map(async p=>{
        if(Array.isArray(p.media)&&p.media.length){
          const first=p.media.find(m=>m.type!=="video")||p.media[0];
          if(first && !first.url){
            // Legacy item (no embedded URL): prefer the tiny thumbnail; fall back to full image.
            if(first.thumb){ const t=await loadMediaItem(first.key+"_thumb"); if(t){ firstWave["thumb-"+first.key]=t; return; } }
            const b=await loadMediaItem(first.key); if(b)firstWave["m-"+first.key]=b;
          }
        }
        else if(p.hasImg){ const b=await loadImg(p.id); if(b)firstWave["img-"+p.id]=b; }
      }));
      if(Object.keys(firstWave).length) setMediaCache(c=>({...c,...firstWave}));
    }catch(e){}

    // Wave 2 — full load: every gallery image, videos, request & guide images (unchanged).
    const cache={};
    await Promise.all([
      ...prods.map(async p=>{
        // New multi-media gallery. Items whose URL is embedded on the product need NO DB read
        // (rendered straight from m.url / m.thumbUrl) — only legacy items hit loadMediaItem.
        if(Array.isArray(p.media)&&p.media.length){
          await Promise.all(p.media.map(async m=>{
            if(m.url) return; // embedded URL — zero extra reads
            if(m.thumb){ const t=await loadMediaItem(m.key+"_thumb"); if(t)cache["thumb-"+m.key]=t; }
            const b=await loadMediaItem(m.key); if(b)cache["m-"+m.key]=b;
          }));
        }
        // Legacy single image/video
        if(p.hasImg){const b=await loadImg(p.id);if(b)cache["img-"+p.id]=b;}
        if(p.hasVid){const b=await loadVid(p.id);if(b)cache["vid-"+p.id]=b;}
      }),
      ...reqs.map(async r=>{ if(r.hasImg){const b=await loadImg(r.id);if(b)cache["img-"+r.id]=b;} }),
      ...guideList.map(async g=>{ if(g.hasImg){const b=await loadImg(g.id);if(b)cache["img-"+g.id]=b;} }),
    ]);
    setMediaCache(c=>({...c,...cache}));
  };

  const cloudSyncDone=useRef(false);
  const cloudSync=async()=>{
    if(!FB_OK||cloudSyncDone.current) return;
    cloudSyncDone.current=true;
    // Products — seed cloud from local/defaults if the cloud is empty
    let prods=await fbGetColl("products");
    if(prods!==null && prods.length===0){ const seed=(localProducts()||DEFAULT_PRODUCTS).map(normalizeProduct); await saveProd(seed); prods=seed; }
    const finalProds=(prods&&prods.length)?prods.map(normalizeProduct):null;
    // A repeat visit paints instantly from cache, then this cloud read lands a moment later.
    // Handing back a fresh array even when nothing changed re-rendered the whole catalog and
    // replayed the grid's reveal animation — the visible "products update" after the store has
    // already opened. Keep the existing array when the data is identical.
    if(finalProds) setProducts(prev=>sameCatalog(prev,finalProds)?prev:finalProds);
    setHydrated(true);
    /* Guides — seed the cloud ONLY from real content this device still holds, never from the
       built-in samples. Writing DEFAULT_GUIDES into a live store's empty `guides` node is worse
       than leaving it empty: the three samples carry no posters, so the owner sees a full-looking
       Care Guides page with every uploaded poster missing, and the samples then look like the
       store's own content on every future sync. The samples stay a local placeholder; only the
       admin's own saves put anything in the cloud. */
    let gds=await fbGetColl("guides");
    if(gds!==null && gds.length===0){
      const local=(localGuidesData()||[]).filter(g=>g&&!g.sample);
      if(local.length){ await saveGuides(local); gds=local; }
    }
    const finalGds=(gds||[]).filter(g=>g&&!isSampleGuide(g));
    setGuides(finalGds);
    // ONE hydrateMedia call with all cloud data (was called twice: once for prods, once for guides)
    const syncedProds=finalProds||(localProducts()||DEFAULT_PRODUCTS).map(normalizeProduct);
    const syncedGds=finalGds||(localGuidesData()||[]);
    hydrateMedia(syncedProds, localRequests(), syncedGds);
    // The storefront is now showing live products with their images — everything past this point
    // (requests, settings) is either admin-only or already served from cache, so there's nothing
    // left worth making the shopper stare at the splash for.
    revealStore();
    // Requests (admin needs these; customers' request page works regardless)
    const reqs=await loadRequests();
    if(reqs)setRequests(reqs);
    // Settings — seed if missing
    const stObj=await fbGetObj("settings");
    // The admin-only half comes back null for everyone else, and the bank half comes back null
    // until the shopper signs in — merging them here matters because this result replaces the
    // in-memory settings. Without it an admin's session would silently lose its private keys
    // and the next save would blank them.
    const [stPriv,stBank]=await Promise.all([fbGetObj("settingsPrivate"),fbGetObj("settingsBank")]);
    if(stObj===null && FB_OK){ const local=localSettingsData(); await saveSettings(local); setSettings(local); }
    else if(stObj){
      const merged=normalizeSettings({...DEFAULT_SETTINGS,...stObj,...(stBank||{}),...(stPriv||{})}); setSettings(merged); try{dbSet("nemo-settings",JSON.stringify(merged));}catch(e){}
      // Migration: keys that moved out of the world-readable node only actually leave it when
      // something writes. Waiting for the owner to remember to press Save leaves them exposed,
      // so the admin's own session re-saves once the moment it sees a leftover.
      if(FB_AUTH?.currentUser?.uid===ADMIN_UID && NON_PUBLIC_SETTING_KEYS.some(k=>stObj[k]!==undefined)){
        try{ await saveSettings(merged); }catch(e){ console.warn("settings migration",e&&e.message); }
      }
    }
    setSettingsReady(true);
    // Showcase + testimonials are loaded via a live listener (see the global content effect).
  };

  useEffect(()=>{
    (async()=>{
      // 1) Instant first paint from local cache
      const localP=localProducts();
      const prods=(localP||DEFAULT_PRODUCTS).map(normalizeProduct);
      setProducts(prods);
      setOrders(localOrders());
      const reqs=localRequests(); setRequests(reqs);
      const guideList=(localGuidesData()||[]).filter(g=>g&&!isSampleGuide(g)); setGuides(guideList);
      setSettings(localSettingsData());
      // Caching is now reliable (media lives in IndexedDB, so localStorage no longer fills up
      // and silently drops settings writes). So a cached settings blob is trustworthy — reveal
      // settings-gated promo banners IMMEDIATELY from cache instead of waiting on the cloud fetch.
      // First-ever visitors (no cache) briefly wait for the cloud value; everyone else sees it instantly.
      try{ if(localStorage.getItem("nemo-settings")) setSettingsReady(true); }catch(e){}
      const u=await loadUser(); if(u){setUser(u);setReviewedSet(loadReviewedSet(userKey(u)));loadFavorites(userKey(u)).then(setFavorites);setInterestedSet(loadIntLocal(userKey(u)));}
      setLoading(false);
      // React now has a usable shell. Let the splash go immediately; a cold visitor sees the
      // intentional catalogue skeleton while REST/Firebase hydrate it, rather than staring at
      // a blocking animation for network work that can safely finish in the background.
      revealStore();
      // A repeat visitor already has a complete catalogue snapshot, so it skips the skeleton.
      if(localP) setHydrated(true);
      // Safety: never leave skeletons up indefinitely (e.g. Firebase off) — reveal after a short wait
      // Fast path: the REST prefetch started before this component existed and normally
      // lands well ahead of the SDK, so the real catalogue replaces the placeholder within a
      // few hundred ms instead of after the whole Firebase handshake.
      CATALOG_PREFETCH.then(list=>{
        if(!list||!list.length) return;
        const next=list.map(normalizeProduct);
        setProducts(prev=>sameCatalog(prev,next)?prev:next);
        try{ dbSet("nemo-products",JSON.stringify(next)); }catch(e){}
        setHydrated(true);
        hydrateMedia(next, localRequests(), localGuidesData()||[]);
        revealStore();          // nothing left worth holding the splash for
      });
      // Safety: never leave skeletons up indefinitely (e.g. Firebase off) — but a first-time
      // visitor has no cache, so revealing on a bare timer is what flashes DEFAULT_PRODUCTS
      // at them a moment before the real shop arrives. With no cache to fall back on, wait
      // for the prefetch to settle first, capped so an unreachable database still reveals.
      if(!localP) Promise.race([CATALOG_PREFETCH,new Promise(r=>setTimeout(r,2500))]).then(()=>setHydrated(true));
      hydrateMedia(prods,reqs,guideList);
      // Seed defaults into the LOCAL cache only. saveProd also writes the cloud when Firebase
      // happens to be up by now, which would publish the ten placeholder products over a real
      // catalogue. Seeding a genuinely empty cloud is cloudSync's job, and it only does so
      // after actually reading the node and finding it empty.
      if(!localP){ try{ dbSet("nemo-products",JSON.stringify(prods)); }catch(e){} }
      // Guides get the same treatment, and for the same reason — but this line used to call
      // saveGuides(), which writes the CLOUD as well as the cache. That is how three sample
      // guides ended up published over a store whose own guides were missing: the samples have
      // no posters, so the page looked full while every uploaded poster was gone. Local cache
      // only; publishing an empty cloud is cloudSync's job, and it now refuses to publish
      // samples at all.
      if(!localGuidesData()){ try{ dbSet("nemo-guides",JSON.stringify(guideList.filter(g=>g&&!g.sample))); }catch(e){} }
      // 2) Cloud hydrate behind the visible shell. Product grids remain skeletons until the
      // catalogue is ready, avoiding both a blocked first paint and a flash of guessed stock.
      if(!FB_OK) await waitForFirebase(1200);
      try{ await cloudSync(); }catch(e){ console.warn("cloudSync",e&&e.message); }
      revealStore();
    })();
  },[]);

  // When Firebase connects after first paint (async SDK), re-sync from the cloud
  useEffect(()=>{
    window.addEventListener("nemo-fb-ready",cloudSync);
    return()=>window.removeEventListener("nemo-fb-ready",cloudSync);
  },[]);

  // Safety net: first-ever visitors have no cache, so reveal settings-gated promo banners
  // from the local value after a short grace period even if Firebase is slow/blocked.
  useEffect(()=>{ const t=setTimeout(()=>setSettingsReady(true), 650); return()=>clearTimeout(t); },[]);

  /* Bounded like every other boot gate: a webfont that never arrives must not hold the store
     behind the splash. 1.2s is comfortably longer than a warm cache — where the event has
     usually fired before this effect even runs — and short enough that nobody on a bad
     connection is made to wait on typography. */
  useEffect(()=>{
    if(fontsReady) return;
    let alive=true;
    const done=()=>{ if(alive) setFontsReady(true); };
    const cap=setTimeout(done,1200);
    window.addEventListener("nemo-fonts-ready",done,{once:true});
    return ()=>{ alive=false; clearTimeout(cap); window.removeEventListener("nemo-fonts-ready",done); };
  },[fontsReady]);

  /* The cinematic opening may lift only after the visible Home data has settled:
     catalogue, settings, Customer Tanks, testimonials and the signed-in wallet. Each source
     carries its own bounded fallback, so this waits for real inner completion without hanging. */
  /* Drive the splash percentage from the same five gates the reveal waits on, so the number
     reflects work that actually finished rather than a timer. 40% is the shell existing at
     all — React mounted and this component is rendering — and the five data gates share the
     rest, 10 points each. index.html keeps it monotonic and creeps between milestones. */
  useEffect(()=>{
    const done=[!loading,hydrated,settingsReady,communityReady,walletReady,fontsReady].filter(Boolean).length;
    bootProgress(40+done*10);
  },[loading,hydrated,settingsReady,communityReady,walletReady,fontsReady]);

  useEffect(()=>{
    if(loading||!hydrated||!settingsReady||!communityReady||!walletReady||!fontsReady) return;
    try{ window.__nemoBootReady=true; }catch(e){}
    bootProgress(100);
    revealStore();
  },[loading,hydrated,settingsReady,communityReady,walletReady,fontsReady]);

  const deepLinkRef = useRef((()=>{ try{ return new URLSearchParams(window.location.search).get("p")||""; }catch(e){ return ""; } })());
  useEffect(()=>{
    const pid=deepLinkRef.current;
    if(!pid) return;
    // Resolved against the shoppable list: an old share link or a Google result for a
    // hidden live-fish product must not open its detail page. The link is retired either
    // way, so a hidden id lands on Home with a clean URL instead of retrying forever.
    const prod=shopProducts.find(p=>p.id===pid);
    const hidden=!prod&&products.some(p=>p.id===pid);
    if(prod||hidden){
      deepLinkRef.current=""; // fire once
      if(prod) nav("detail",prod);
      // Tidy the URL so a refresh/share doesn't keep re-triggering, without reloading
      try{ window.history.replaceState({},"",window.location.pathname); }catch(e){}
    }
  },[products,shopProducts]);
  /* Coming back from a gateway that navigated away rather than opening a modal (PhonePe).
     The return itself proves nothing — a customer can reach this URL by typing it — so it is
     only a cue to ask our server to check the order with the gateway.

     Deliberately gated on Firebase auth being ready: verification is authorised by the
     customer's own ID token, so running it early would fail. If auth never arrives, this
     simply never runs and the signed webhook settles the order server-side instead, which
     is why that second path exists. */
  /* Land on Orders the instant we can see a payment coming back — before Firebase auth is up
     and long before /api/pay-verify answers. Verification below still decides what the order
     SAYS; this only decides which page the customer is looking at while it runs, and the
     answer was the home page, which reads as "my payment went nowhere". Read-only, so the
     marker is still there for the effect below to consume. */
  useEffect(()=>{ if(pendingPaymentReturn()) nav("orders"); },[]);
  const payReturnRef = useRef(false);
  useEffect(()=>{
    if(payReturnRef.current) return;
    if(!FB_OK||!FB_AUTH||!FB_AUTH.currentUser) return;
    const orderId=takePaymentReturn();
    if(!orderId) return;
    payReturnRef.current=true;
    const uid=FB_AUTH.currentUser.uid;
    (async()=>{
      try{
        const checked=await verifyPaymentForOrder(uid,orderId);
        showToast(checked.mode==="sandbox"?"Test payment recorded":"Payment confirmed \u{1F389}");
      }catch(e){
        const m=String((e&&e.message)||"");
        showToast(m==="payment-not-complete"
          ? "Payment was not completed. Nothing has been charged."
          : "We could not confirm the payment yet — check My Orders in a moment.","error");
      }
      try{ await cloudSync(); }catch(e){}
      nav("orders");
    })();
  },[user,fbReady]);

  // Page deep links (?page=shop|orders|cart|guides|tools) — used by PWA app shortcuts
  useEffect(()=>{
    try{
      const pg=new URLSearchParams(window.location.search).get("page");
      if(pg&&["shop","orders","cart","guides","tools"].includes(pg)){
        nav(pg);
        window.history.replaceState({},"",window.location.pathname);
      }
    }catch(e){}
  },[]);

  // Visitor analytics: count one visit per session, once Firebase is ready
  useEffect(()=>{
    if(FB_OK) trackVisit(); else window.addEventListener("nemo-fb-ready",trackVisit,{once:true});
    return()=>window.removeEventListener("nemo-fb-ready",trackVisit);
  },[]);
  /* Name today's signed-in visitors for the 7-day log. Runs on sign-in as well as on load,
     because a customer who signs in mid-visit should still appear under today. */
  useEffect(()=>{
    if(!user||!user.uid) return;
    const go=()=>logVisitorName(user);
    if(FB_OK) go(); else window.addEventListener("nemo-fb-ready",go,{once:true});
    return()=>window.removeEventListener("nemo-fb-ready",go);
  },[user&&user.uid,fbReady]);
  // Optional Google Analytics, if the admin pasted a Measurement ID in Settings
  useEffect(()=>{ if(settings.gaId) injectGA(settings.gaId); },[settings.gaId]);

  const pageRef = useRef("home");
  /* Where Back goes. This used to be a single "previous page" that only the product page
     ever set, so every other screen sent the shopper to Home however deep they were —
     leaving Checkout for Home when they had walked in from the Cart. This is the real
     trail instead: every forward move pushes the screen being left, and Back pops it, so
     Back always lands where they actually were. Detail entries carry their product,
     because restoring that page without one renders an empty product screen.
     selProduct only ever changes inside nav(), so the ref beside it cannot drift. */
  const navStackRef = useRef([]);
  const selProductRef = useRef(null);
  const NAV_STACK_MAX = 25;
  /* Screens Back must never return INTO. A sign-in is finished the moment it succeeds;
     dropping someone back onto the screen they just cleared is worse than Home. The admin
     panel is the same — the store is not a way back into it. */
  const NO_RETURN_PAGES = ["auth","admin-login","admin"];

  /* Where the shopper had scrolled to on each page. Going deeper (tapping a product) always
     opens the new page at the top, but coming BACK should return them to the spot they left —
     losing a long scroll through the shop on every product they look at is what made browsing
     feel like starting over. */
  const scrollMem = useRef({});
  const saveScroll=()=>{ try{ scrollMem.current[pageRef.current]=scrollRef.current?.scrollTop||0; }catch(e){} };
  const applyScroll=(y)=>{
    /* The page keeps growing after it first paints — product images decode, lazy sections
       fill in — so a single early scrollTo silently clamps to whatever height exists at that
       instant and drops the shopper part-way up (restoring 900 landed at 385). Re-apply until
       the target is actually reachable, then stop. Scrolling to 0 needs none of this and
       exits on the first pass. */
    let tries=0;
    const step=()=>{
      const d=scrollRef.current; if(!d) return;
      d.scrollTo({top:y,behavior:"auto"});
      if(y>0 && d.scrollTop < y-2 && ++tries<25) setTimeout(step,60);
    };
    requestAnimationFrame(()=>requestAnimationFrame(step));
  };
  const nav=(pg,product=null,opts={})=>{
    if(pg!=="detail") setReviewIntent(null);
    const from = pageRef.current;
    /* Leave a breadcrumb for Back. Not when going back (that would undo the pop we are
       serving), and not when re-opening the screen already on show — stacking a page on
       top of itself makes the first Back press look like it did nothing. */
    if(!opts.back && pg!==from && !NO_RETURN_PAGES.includes(from)){
      navStackRef.current.push({page:from, product:selProductRef.current});
      if(navStackRef.current.length>NAV_STACK_MAX) navStackRef.current.shift();
    }
    // Hardware-back trap: when leaving Home for a deeper page, push a history entry
    // so the phone's Back button returns to Home instead of closing the app.
    if(from==="home" && pg!=="home"){ try{ history.pushState({nemo:1},""); }catch(e){} }
    saveScroll();
    pageRef.current = pg;
    setPage(pg);
    if(DIRECT_PATH_BY_PAGE[pg]||DIRECT_PATH_BY_PAGE[from]){
      try{ history.replaceState(history.state||{},"",DIRECT_PATH_BY_PAGE[pg]||"/"); }catch(e){}
    }
    if(product){ setSelProduct(product); selProductRef.current=product; }
    // Forward = open at the top. Back (opts.restore) = pick up where they left off.
    applyScroll(opts.restore ? (scrollMem.current[pg]||0) : 0);
  };
  /* One step back up the trail: the screen they came from, at the spot they left it. An
     empty trail means they arrived here directly — a shared link, a fresh load, a push
     notification — and Home is the only place Back can honestly go. */
  const goBack=()=>{
    const prev = navStackRef.current.pop();
    nav(prev?prev.page:"home", (prev&&prev.page==="detail")?prev.product:null, {restore:true, back:true});
  };
  /* The phone Back button fires through a listener registered once, so it calls this
     rather than closing over the first render's goBack. */
  const goBackRef = useRef(goBack);
  goBackRef.current = goBack;
  /* Backing out of a flow to a screen that is already behind them — payment cancelled,
     back to the Cart — rewinds the trail to that screen rather than stacking on top of
     it. Otherwise Back from the Cart would walk right back into the checkout they just
     abandoned. If the screen isn't on the trail this is an ordinary move. */
  const navRewind=(pg)=>{
    const st=navStackRef.current;
    const at=st.map(e=>e.page).lastIndexOf(pg);
    if(at>=0) st.length=at;
    nav(pg,null,{restore:true, back:true});
  };

  // Phone Back button: inner pages follow the real trail; top-of-Home asks before leaving Nemo.
  const [appExitAsk,setAppExitAsk]=useState(false);
  const appExitAskRef=useRef(false);
  // Admin panel: Back must never drop straight out of the panel — a stray back-swipe mid-edit
  // would throw away the work in progress. AdminHub registers a handler here that closes any
  // open sub-screen (product form / order detail) first; at the top level we ask to confirm.
  const adminBackRef = useRef(null);
  const [adminExitAsk,setAdminExitAsk]=useState(false);

  /* Native Android Back bridge. WebView URLs do not reliably reveal React's current
     screen, so Android asks the app itself. From a deep flow the first press restores
     the immediately previous screen, then the trail is deliberately reduced to Home:
     next press reaches Home, and only the following press may show Android's exit dialog. */
  useEffect(()=>{
    const handleAndroidBack=()=>{
      if(pageRef.current==="admin"){
        if(adminBackRef.current && adminBackRef.current()) return "handled";
        setAdminExitAsk(true);
        return "handled";
      }
      if(pageRef.current==="home") return "home";
      const prev=navStackRef.current.pop();
      if(prev&&prev.page&&prev.page!=="home"){
        navStackRef.current=[{page:"home",product:null}];
        nav(prev.page,prev.page==="detail"?prev.product:null,{restore:true,back:true});
      }else{
        navStackRef.current=[];
        nav("home",null,{restore:true,back:true});
      }
      return "handled";
    };
    window.__nemoHandleAndroidBack=handleAndroidBack;
    return()=>{
      if(window.__nemoHandleAndroidBack===handleAndroidBack){
        try{ delete window.__nemoHandleAndroidBack; }catch(e){ window.__nemoHandleAndroidBack=undefined; }
      }
    };
  },[]);

  useEffect(()=>{
    // Seed one history entry so the FIRST back press is captured (even on a fresh Home load).
    try{ history.pushState({nemo:1},""); }catch(e){}
    const onPop=()=>{
      if(appExitAskRef.current){
        try{ history.pushState({nemo:1},""); }catch(e){}
        appExitAskRef.current=false;
        setAppExitAsk(false);
        return;
      }
      if(pageRef.current==="admin"){
        try{ history.pushState({nemo:1},""); }catch(e){}   // never leave on this press
        // Step out of a sub-screen first, if one is open.
        if(adminBackRef.current && adminBackRef.current()) return;
        // Top level of the panel → warn before going back to the store. (window.confirm is
        // blocked inside popstate on most phones, so this is an in-app dialog.)
        setAdminExitAsk(true);
        return;
      }
      if(pageRef.current!=="home"){
        /* Back out to wherever this page was opened FROM, not always Home — a product opened
           from a scrolled Shop list belongs back in that list, at that spot, and Checkout
           belongs back in the Cart it was entered from. Restoring the scroll is the other
           half: landing at the top of the list they had worked down is the same as losing
           their place. */
        goBackRef.current();
        try{ history.pushState({nemo:1},""); }catch(e){}   // re-arm the trap
      } else if((scrollRef.current?.scrollTop||0) > 8){
        // On Home, but scrolled down: the first press takes them back to the top. Only a
        // press from the top of Home is treated as "leaving", which is where the exit
        // prompt belongs — pressing back mid-page and being asked to quit is jarring.
        scrollRef.current?.scrollTo({top:0,behavior:"smooth"});
        scrollMem.current["home"]=0;
        try{ history.pushState({nemo:1},""); }catch(e){}
      } else {
        // At the top of Home, stay inside Nemo until the customer explicitly confirms exit.
        // This Back press consumed the sentinel, so re-arm it before opening the sheet.
        try{ history.pushState({nemo:1},""); }catch(e){}
        appExitAskRef.current=true;
        setAppExitAsk(true);
      }
    };
    window.addEventListener("popstate",onPop);
    return()=>window.removeEventListener("popstate",onPop);
  },[]);

  /* Weekly tank care reminder. Checked when the app opens rather than pushed, because there is
     no sender yet — see careDue(). Stamped per day so opening the app five times in an evening
     does not nag five times. */
  useEffect(()=>{
    const uk=userKey(user);
    const t=loadMyTank(uk);
    if(!t||!t.remind) return;
    const d=careDue(t);
    if(!d.due) return;
    const key="nemo-carenotif-"+(uk||"guest"), today=new Date().toISOString().slice(0,10);
    try{
      if(localStorage.getItem(key)===today) return;
      localStorage.setItem(key,today);
    }catch(e){}
    const litres=careChangeLitres(t,false);
    sendLocalNotif(`${t.name||"Your tank"} — weekly care due`,
      litres>0?`Time for a ~${litres} L water change, and a look at the filter and heater.`:"Time for this week's water change.");
  },[user]);

  // Secret admin tap handler
  const handleSecretTap=()=>{
    clearTimeout(tapTimer.current);
    tapCount.current+=1;
    /* Browser only. The gesture exists so the owner can reach Admin from a shop-front that
       shows no door — but the installed app is the copy on a phone in a pocket, handed
       around, and the one place the owner never needs the door because they can open the
       store in a browser instead. Counting taps but never opening keeps the logo behaving
       exactly as it does for a shopper: taps go Home, and nothing hints there is more. */
    if(tapCount.current>=SECRET_TAPS && !(typeof window!=="undefined" && window.nemoInApp)){
      tapCount.current=0;
      nav("admin-login");
    } else {
      // Normal use: a logo tap just goes home. Only 10 rapid taps (within 2s of each other)
      // opens admin. Re-navigating to the page already on screen re-runs the page-swap
      // animation and scrolls the hero out from under the finger, so mid-count taps land on
      // a moving target — on Home there is nowhere to go anyway.
      if(pageRef.current!=="home") nav("home");
      tapTimer.current=setTimeout(()=>{tapCount.current=0;},2000);
    }
  };

  const addToCart=(product,qty=1,variant=null)=>{
    // A Coming Soon product isn't on sale yet, so it must never reach the cart — whichever
    // surface asked (option picker, cross-sell, reorder, a saved cart from an earlier session).
    // Guarding here rather than only in the UI means one rule, enforced on every path.
    // Negative qty still passes so an existing line can always be removed.
    if(qty>0 && product && product.comingSoon){ setTimeout(()=>showToast("Coming soon — not on sale yet","error"),0); return; }
    let v = variant;
    // Any product with options gets one picked if the caller didn't pass one (reorder, cross-sell,
    // "buy it again") — otherwise the line would land with no option and the plain base price.
    if(!v){ const vs=productVariants(product); if(vs&&vs.length) v=vs.find(x=>!variantSoldOut(product,x))||null; }
    // Never let a sold-out option through, whoever asked for it.
    if(qty>0 && v && variantSoldOut(product,v)){ setTimeout(()=>showToast(`${v.label} is sold out`,"error"),0); return; }
    if(qty>0 && productStockTotal(product)<=0){ setTimeout(()=>showToast("Out of stock","error"),0); return; }
    // The cap is the CHOSEN option's stock, not the product-wide pool.
    const stock = v ? variantStockOf(product, v) : (product.stockCount ?? DEFAULT_STOCK);
    const key = product.id + (v?("|"+v.id):"");
    const unitPrice = v ? variantEffPrice(product, v) : effectivePrice(product);
    const maxAllowed = Math.max(0, Math.min(stock, MAX_PER_ORDER));
    setCart(prev=>{
      // Taking one off has to target a line that is actually in the cart. The
      // catalogue card has no option picker, so its "−" calls this with no
      // variant — and the auto-pick above then chooses an option by
      // availability, which is a different key from the one the shopper added,
      // or none at all once that option sells out. Either way the press hit a
      // line that does not exist, nothing changed, and the cart could not be
      // emptied. So on the way down, fall back to the line this product really
      // has (the most recently added, if it has several options in the cart).
      let k=key;
      if(qty<0 && !prev.some(i=>i.key===k)){
        const line=[...prev].reverse().find(i=>i.id===product.id);
        if(!line) return prev;
        k=line.key;
      }
      const ex=prev.find(i=>i.key===k);
      const curQty=ex?ex.qty:0;
      // Stock caps what you can add, never what you can take away — clamping a
      // decrement to the cap emptied the whole line the moment an option sold
      // out while it sat in the cart.
      const nextQty=qty<0?curQty+qty:Math.min(maxAllowed, curQty+qty);
      if(nextQty<=0) return prev.filter(i=>i.key!==k);
      if(qty>0 && curQty+qty>maxAllowed) setTimeout(()=>showToast(`Only ${maxAllowed} available per order`,"error"),0);
      else if(qty>0){ setTimeout(()=>showToast("Added to cart"),0); trackEvent("addcart",product.id); trackFunnel("addcart"); }
      if(ex) return prev.map(i=>i.key===k?{...i,qty:nextQty}:i);
      // The Product ID travels with the line, so the order records what the item
      // was called when it sold rather than what the catalogue says today.
      const vIdx=v?((productVariants(product)||[]).findIndex(x=>x.id===v.id)):-1;
      return [...prev,{key,id:product.id,sku:product.sku||"",variantSku:variantSku(product,v,vIdx<0?0:vIdx),name:product.name,category:product.category,price:unitPrice,mrp:(v?variantBasePrice(product,v):(product.price||unitPrice)),qty:nextQty,variantId:v?.id||null,variantLabel:v?.label||null,packagingWeight:product.packagingWeight??null,variantPackagingWeight:v?.packagingWeight??null,suggestedPacking:product.suggestedPacking||null,suggestSpecialDelivery:!!product.suggestSpecialDelivery,returnEligible:product.returnEligible===true,stockCount:stock,gstApplicable:product.gstApplicable===true,hsn:product.hsn||"",gstRate:(product.gstRate==null?null:Number(product.gstRate))}];
    });
  };
  const updateQty=(key,delta)=>
    setCart(prev=>prev.map(i=>{
      if(i.key!==key)return i;
      const max=Math.min(i.stockCount??DEFAULT_STOCK,MAX_PER_ORDER);
      return {...i,qty:Math.min(max,Math.max(0,i.qty+delta))};
    }).filter(i=>i.qty>0));

  // Persist the cart so it survives reloads / return visits.
  useEffect(()=>{ try{ localStorage.setItem("nemo-cart",JSON.stringify(cart)); }catch(e){} },[cart]);

  // That saved cart stores the price each line was added at, so a line added during a sale would
  // still be charged at the sale price long after the offer's end date — exactly what the end
  // date is meant to stop. Re-price every line against the live catalog whenever it changes.
  // Lines whose product (or chosen option) has since gone are left alone for checkout to handle.
  useEffect(()=>{
    if(!products.length) return;
    setCart(prev=>{
      let changed=false;
      const next=prev.map(i=>{
        const prod=products.find(x=>x.id===i.id);
        if(!prod) return i;
        const vs=productVariants(prod);
        const v=i.variantId ? (vs||[]).find(x=>x.id===i.variantId) : null;
        if(i.variantId && !v) return i;
        const price=v?variantEffPrice(prod,v):effectivePrice(prod);
        const mrp=v?variantBasePrice(prod,v):(prod.price||price);
        if(price===i.price && mrp===i.mrp) return i;
        changed=true;
        return {...i,price,mrp};
      });
      // A product flagged Coming Soon after it was added — or restored from a saved cart made
      // before it was flagged — must not stay purchasable. Drop those lines and say why.
      const dropped=[];
      const kept=next.filter(i=>{
        const prod=products.find(x=>x.id===i.id);
        if(prod && prod.comingSoon){ dropped.push(i.name); return false; }
        return true;
      });
      if(dropped.length){
        const more=dropped.length>1?` +${dropped.length-1} more`:"";
        setTimeout(()=>showToast(`${dropped[0]}${more} isn't on sale yet — removed from your cart`,"error"),0);
        return kept;
      }
      return changed?next:prev;          // unchanged -> same array, so this can't loop
    });
  },[products]);

  // ── Abandoned-cart capture ──
  // While a signed-in shopper has items in their cart, mirror a lightweight snapshot to Firebase
  // (debounced) so the owner can gently nudge them. Keyed by the Firebase auth uid (satisfies the
  // security rule), and cleared automatically once the cart empties or an order is placed.
  useEffect(()=>{
    if(isDemoUser(user)) return; // demo/review sessions never surface in the admin panel
    if(!(FB_OK && FB_AUTH && FB_AUTH.currentUser && FB_DB)) return;
    const auid = FB_AUTH.currentUser.uid;
    const ref = FB_DB.ref("abandonedCarts/"+auid);
    const t = setTimeout(()=>{
      if(!cart.length){ ref.remove().catch(()=>{}); return; }
      const phone = normalizePhone(user?.phone||"");
      const email = (user?.email||"").slice(0,80);
      if(!phone && !email) return; // not actionable without a way to reach them
      ref.set({
        uid:auid,
        name:(user?.name||"Customer").slice(0,60),
        phone, email,
        items: cart.slice(0,20).map(i=>({name:(i.name||"").slice(0,60),qty:i.qty,price:i.price,variantLabel:i.variantLabel||null})),
        count: cart.reduce((a,i)=>a+i.qty,0),
        value: cart.reduce((a,i)=>a+(i.price||0)*i.qty,0),
        updatedAt: Date.now(),
      }).catch(()=>{});
    }, 1500);
    return ()=>clearTimeout(t);
  },[cart,user,fbReady]);

  // ADMIN: live listener on abandoned carts (recent, still-open shopping carts).
  useEffect(()=>{
    if(page!=="admin") return;
    if(!(FB_OK && FB_DB)){ setAbandonedCarts([]); return; }
    const ref=FB_DB.ref("abandonedCarts");
    const cb=ref.on("value",snap=>{
      const v=snap.val(); const cutoff=Date.now()-30*86400000; // ignore anything older than 30 days
      const arr=v?Object.values(v).filter(c=>c&&c.items&&c.updatedAt>cutoff).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)):[];
      setAbandonedCarts(arr);
    },err=>{ setAbandonedCarts([]); });
    return ()=>ref.off("value",cb);
  },[page,fbReady]);

  // Owner dismisses a lead after contacting them (allowed by the admin branch of the security rule).
  const dismissAbandoned=(auid)=>{
    if(FB_OK && FB_DB){ try{ FB_DB.ref("abandonedCarts/"+auid).remove().catch(()=>{}); }catch(e){} }
    setAbandonedCarts(prev=>prev.filter(c=>c.uid!==auid));
  };

  // Auth
  const handleLogin=(u)=>{
    setUser(u);
    setReviewedSet(loadReviewedSet(userKey(u)));
    loadFavorites(userKey(u)).then(setFavorites);
    setInterestedSet(loadIntLocal(userKey(u)));
    if(u.keep!==false) saveUser(u);
    showToast(`Welcome, ${u.name?.split(" ")[0]||"there"}!`);
    nav("home"); // after sign-in, always land on the home page
  };
  const handleLogout=()=>{ setUser(null); setReviewedSet([]); setFavorites([]); setInterestedSet([]); clearUser(); showToast("Signed out"); nav("home"); };
  // Customer self-service account deletion (Play Store requirement). Deletes the personal
  // data reachable from the customer's own session, records a request so the owner can
  // finish clearing the rest, then signs out. Order/payment records are retained (tax law).
  const handleDeleteAccount=async()=>{
    const ukey=userKey(user);
    if(!isDemoUser(user)){
      const auid=(FB_OK&&FB_AUTH&&FB_AUTH.currentUser&&FB_AUTH.currentUser.uid)||ukey||"";
      const req={
        id:uid("del"), type:"account-deletion", ukey:ukey||"", uid:auid,
        name:(user?.name||"Customer").slice(0,60),
        email:(user?.email||"").slice(0,80),
        phone:normalizePhone(user?.phone||""),
        createdAt:new Date().toISOString(),
      };
      try{ await saveOneRequest(req); }catch(e){}     // notify owner via the admin Requests tab
      try{ await purgeUserCloudData(ukey); }catch(e){} // wipe reachable cloud data while still authed as this user
    }
    purgeUserLocalData(ukey);
    setUser(null); setReviewedSet([]); setFavorites([]); setInterestedSet([]);
    try{ await clearUser(); }catch(e){}
    nav("home");
    showToast(isDemoUser(user)?"Demo account cleared":"Your account and data have been deleted");
  };
  const goAuth=(returnTo="orders")=>{ setAuthReturn(returnTo); nav("auth"); };
  const adminGoogleSignIn=async()=>{
    try{
      showToast("Opening Google sign-in…");
      const u=await googleSignIn();
      if(u){
        const usr={...u,keep:true};
        setUser(usr); saveUser(usr);
        await refreshAdminAccess();
        if(isAdminUid(u.uid)){ showToast("✓ Admin signed in — permitted sections are available"); }
        else{ showToast("Signed in — copy this account UID to add it as a co-admin"); }
        setTimeout(()=>{ loadOrders().then(o=>o&&setOrders(o)); loadInterestCounts().then(setInterestCounts); },400);
        return u;
      }
    }catch(e){
      const msg=String(e?.message||""), code=String(e?.code||"");
      if(msg==="redirecting") return;                      // page is navigating to Google
      if(msg==="offline")      showToast("Can't reach Firebase right now — check your connection","error");
      else if(code.includes("popup-closed")||code.includes("cancelled")) showToast("Sign-in cancelled","error");
      else if(code.includes("network-request-failed")) showToast("Network hiccup — try again","error");
      else showToast("Sign-in failed — try again","error");
      return null;
    }
  };
  const markReviewed=(pid)=>{ if(user){ setReviewedSet(addReviewedLocal(userKey(user),pid)); } };
  const unmarkReviewed=(pid)=>{ if(user){ setReviewedSet(removeReviewedLocal(userKey(user),pid)); } };
  const startReview=(prod,preset=0)=>{ setReviewIntent(prod.id); setReviewPreset(Number(preset)||0); nav("detail",prod); };

  /* ── Address book ──────────────────────────────────────────────────────────────────
     Only customer-saved cards are loaded. Order history is deliberately excluded so a
     deleted address cannot reappear at the next checkout. */
  useEffect(()=>{
    const uk=userKey(user);
    if(!uk){ setSavedAddresses([]); return; }
    if(page==="admin") return;
    setSavedAddresses(loadSavedAddresses(uk));
  },[user,page]);
  const saveAddressBookEntry=entry=>{
    const uk=userKey(user);
    if(!uk||addrIsBlank(entry)) return;
    setSavedAddresses(prev=>{
      const fp=addrFingerprint(entry);
      // Editing an existing card updates it in place; a new place is appended. Matching on
      // the fingerprint as well as the id stops "save" quietly duplicating the same address.
      const idx=prev.findIndex(a=>(entry.id&&a.id===entry.id)||addrFingerprint(a)===fp);
      const row={...entry, id:entry.id||uid_addr(), fromOrder:false};
      const next=idx>=0 ? prev.map((a,i)=>i===idx?{...a,...row,id:a.id}:a) : [...prev,row];
      saveAddrBook(uk,next);
      return next;
    });
    showToast("Address saved ✓");
  };
  const deleteAddressBookEntry=id=>{
    const uk=userKey(user);
    if(!uk) return;
    setSavedAddresses(prev=>{ const next=prev.filter(a=>a.id!==id); saveAddrBook(uk,next); return next; });
    showToast("Address deleted");
  };
  const toggleFav=(prod)=>{
    if(!user){ goAuth("home"); showToast("Sign in to save items"); return; }
    const on=!favorites.includes(prod.id);
    setFavorites(on?[...favorites,prod.id]:favorites.filter(x=>x!==prod.id));
    setFavoriteRemote(userKey(user),prod.id,on);
    showToast(on?"Saved to favorites ♥":"Removed from favorites");
  };
  const markInterested=(prod)=>{
    if(!user){ goAuth("home"); showToast("Sign in to register interest"); return; }
    if(interestedSet.includes(prod.id))return;
    setInterestedSet([...interestedSet,prod.id]);
    setInterestCounts(c=>({...c,[prod.id]:(c[prod.id]||0)+1}));
    markInterestedRemote(userKey(user),prod.id);
    showToast("Thanks! We'll notify you when it's in 🔔");
  };
  const handleShowcaseSubmit=async(item)=>{
    const cloudOk=await addShowcasePhoto(item);
    if(!cloudOk){
      showToast("Couldn't upload the tank photo — check your connection and retry","error");
      return false;
    }
    setShowcase(s=>[item,...s.filter(x=>x.id!==item.id)]); // pending replacement and approved photo may coexist
    showToast("📩 Submitted! We'll review and post it soon.");
    return true;
  };
  const handleDeleteShowcase=async(id)=>{
    const removed=(showcase||[]).find(x=>x&&x.id===id);
    if(!removed) return true;
    /* Optimistic removal keeps Reject/Remove instant. Restore the exact row if Firebase refuses. */
    setShowcase(list=>list.filter(x=>x&&x.id!==id));
    const ok=await deleteShowcasePhoto(id);
    if(!ok){
      setShowcase(list=>list.some(x=>x&&x.id===id)?list:[removed,...list].sort((a,b)=>(b.createdAt||"").localeCompare(a.createdAt||"")));
      showToast("Couldn't remove that submission — verify admin sign-in","error");
      return false;
    }
    showToast(showcaseApproved(removed)?"Tank photo removed":"Submission rejected");
    return true;
  };
  const handleApproveShowcase=async(item)=>{
    const {updated,replacedId,ok}=await approveShowcasePhoto(item,settings,showcase);
    if(!ok){ showToast("Couldn't approve — sign in with the admin Google account and retry","error"); return; }
    setShowcase(s=>s.filter(x=>!replacedId||x.id!==replacedId).map(x=>x.id===item.id?updated:x));
    showToast(replacedId?"✓ Replacement approved — previous photo removed":"✓ Tank approved — streak day logged and live for 24h");
  };
  /* One vote per tank image per customer. The screen moves first and the write follows: a
     refused write puts the count back rather than leaving a tick the server never agreed to. */
  const handleShowcaseVote=async(entry)=>{
    const uid=user&&user.uid;
    if(!tankVoteRewardOn(settings)){ showToast("Tank of the Month voting is currently off","error"); return; }
    if(!uid){ showToast("Sign in to vote","error"); return; }
    if(entry.userUid===uid){ showToast("You can't vote for your own tank","error"); return; }
    const month=totmMonthOf(Date.now());
    if(hasVotedForTank(entry,uid,totmVotes)){ showToast("You already voted for this tank","error"); return; }
    // Tick first, write second, and put it back if the write is refused — the rules make the
    // voter key create-only, so a refusal here means it was already counted.
    const before=totmVotes;
    setTotmVotes(v=>({...v,[entry.id]:{...(v[entry.id]||{}),_once:{...(((v[entry.id]||{})._once)||{}),[uid]:true}}}));
    const ok=await castShowcaseVote(month,entry.id,uid);
    if(!ok){ setTotmVotes(before); showToast("Couldn't record that vote — check your connection","error"); return; }
    showToast("Voted for "+entry.ownerName+" 🗳️");
  };
  const handleTankMonthlyAward=async(type,month,row)=>{
    const isStreak=type==="streak";
    if(isStreak&&!tankStreakRewardOn(settings)){ showToast("The longest-streak reward is turned off in Settings","error"); return null; }
    if(!isStreak&&!tankVoteRewardOn(settings)){ showToast("The Tank of the Month reward is turned off in Settings","error"); return null; }
    const pts=Math.max(0,Number(isStreak?settings.tankStreakRewardCoins:(settings.tankVoteRewardCoins??settings.totmRewardCoins))||0);
    const minimum=Math.max(1,Number(settings.tankMinStreak||settings.tankUploadStreakTarget)||1);
    if(isStreak&&Number(row.streak)<minimum){ showToast(`Minimum ${minimum}-day streak not met`,"error"); return null; }
    if(!isStreak&&Number(row.votes)<=0){ showToast("No valid votes to reward","error"); return null; }
    if(pts>0){
      const ok=await adminCreditLoyalty(row.uid,pts,`tank-month:${month}:${type}`,isStreak?"Monthly tank streak winner":"Monthly tank vote winner",settings.walletValidityMonths);
      if(!ok){ showToast("Couldn't credit the reward — verify admin sign-in","error"); return null; }
    }
    try{
      const record=await markTankMonthlyWinner(month,type,row,pts);
      if(month===previousTotmMonth(Date.now())) setTankPreviousWinners(w=>({...((w)||{}),[type]:record}));
      showToast(`🏆 ${row.ownerName} awarded ${pts} coin${pts===1?"":"s"} for ${isStreak?"best streak":"most votes"}`);
      return record;
    }catch(e){ showToast("Reward was credited, but the winner record needs retrying","error"); return null; }
  };
  const handleTestimonialSubmit=async(t)=>{
    const cloudOk=await addTestimonial(t);
    setTestimonials(list=>[t,...list.filter(x=>x.uid!==t.uid)]);
    if(!cloudOk) throw new Error("cloud-write-failed"); // surfaces the ⚠ message in the form
  };
  const handleDeleteTestimonial=async(id)=>{
    const cloudOk=await deleteTestimonial(id);
    if(cloudOk){
      setTestimonials(list=>list.filter(x=>x.id!==id));
      showToast("Testimonial removed");
    }else{
      // Cloud rejected the delete — almost always because this browser isn't signed into the
      // admin Google account. Don't fake-remove it (it would reappear on reload).
      showToast("⚠ Couldn't delete — sign in with the admin Google account first");
    }
  };
  const handleRestock=(prod)=>{
    if(!user){ goAuth("home"); showToast("Sign in to get restock alerts"); return; }
    const uid=userKey(user);
    subscribeRestock(uid, prod.id);
    setRestockSet(s=>[...new Set([...s,prod.id])]);
    showToast("🔔 You'll be alerted when it's back in stock!");
  };

  // Complete a Google redirect sign-in when the page returns from the redirect
  useEffect(()=>{
    const bump=()=>setFbReady(x=>x+1);
    window.addEventListener("nemo-fb-ready",bump);
    return()=>window.removeEventListener("nemo-fb-ready",bump);
  },[]);
  useEffect(()=>{
    const onReady=async()=>{
      try{
        if(!FB_OK||!FB_AUTH.getRedirectResult) return;
        const res=await FB_AUTH.getRedirectResult();
        if(res&&res.user&&!res.user.isAnonymous){
          const u={...googleUserFromCred(res.user),keep:true};
          setUser(u); saveUser(u); showToast(`Welcome, ${u.name?.split(" ")[0]||"there"}!`);
        }
      }catch(e){
        /* A redirect that FAILED used to be indistinguishable from no redirect at all: both
           landed here and said nothing, so the customer came back signed out with no idea why
           and tried again into the same wall. Only speak up if we know a redirect was in
           flight — an ordinary page load throws nothing to report. */
        let pending=false;
        try{ pending=sessionStorage.getItem(REDIRECT_PENDING)==="1"; }catch(e2){}
        if(pending) showToast("Google sign-in didn't complete — please try again","error");
      }finally{
        // Either way the redirect is over; let anonymous sign-in resume for signed-out visitors.
        try{ sessionStorage.removeItem(REDIRECT_PENDING); }catch(e2){}
      }
    };
    onReady();
    window.addEventListener("nemo-fb-ready",onReady);
    return()=>window.removeEventListener("nemo-fb-ready",onReady);
  },[]);

  // Requests
  const submitRequest=async(req,imgB64)=>{
    if(imgB64){const ok=await saveImg(req.id,imgB64);req.hasImg=ok;if(ok)setMediaCache(c=>({...c,["img-"+req.id]:imgB64}));}
    setRequests(prev=>[req,...prev]); saveOneRequest(req); // per-id write — no longer clobbers other customers' requests
  };
  const deleteRequest=async(id)=>{
    setRequests(prev=>prev.filter(r=>r.id!==id)); deleteOneRequest(id);
    await delMedia(id);
    setMediaCache(c=>{const n={...c};delete n["img-"+id];return n;});
    showToast("Request deleted");
  };
  // Admin one-tap: finish clearing a user's leftover cloud data after a deletion request,
  // then remove the request. Orders are retained (tax law) and are NOT touched here.
  const purgeUserForAdmin=async(r)=>{
    if(!isAdminUid(user?.uid)){ showToast("⚠ Sign in with the admin Google account first"); return; }
    showToast("Deleting user data…");
    try{ await purgeUserCloudData(r.ukey||r.uid); }catch(e){}
    await deleteRequest(r.id);
    showToast("✓ User data deleted");
  };
  // Guides
  /* The write is awaited and its result reported. A guide that only reached this device is
     a guide that is going to vanish the next time the store syncs, so say so at the moment
     it happens rather than letting the owner find out weeks later that their work is gone. */
  const CLOUD_DENIED="⚠ Saved on THIS DEVICE ONLY — the store was not signed in with the admin Google account, so this will disappear when the app next syncs. Sign in (Admin → Sign in with Google) and save it again.";
  const saveGuideHandler=async(g,imgB64)=>{
    if(imgB64){const ok=await saveImg(g.id,imgB64);g.hasImg=ok;if(ok)setMediaCache(c=>({...c,["img-"+g.id]:imgB64}));}
    const ex=guides.some(x=>x.id===g.id);
    const next=ex?guides.map(x=>x.id===g.id?g:x):[g,...guides];
    setGuides(next);
    // Writes only this guide's key. It used to write `next` over the whole collection, which
    // deleted every guide missing from the in-memory list — see saveOneGuide.
    const confirmed=await saveOneGuide(g);
    if(!confirmed) showToast(CLOUD_DENIED,"error");
    else if(g.hasImg && FB_OK && !isAdminSignedIn()) showToast("⚠ Sign in with Google so customers can see this poster","error");
    else showToast("Guide saved");
  };
  const deleteGuideHandler=async(id)=>{
    const next=guides.filter(g=>g.id!==id);
    setGuides(next);
    const confirmed=await removeOneGuide(id);
    await delMedia(id);
    setMediaCache(c=>{const n={...c};delete n["img-"+id];return n;});
    showToast(confirmed?"Guide deleted":"⚠ Deleted on this device only — sign in with the admin Google account and delete it again, or it will come back on the next sync.",confirmed?undefined:"error");
  };
  /* Removing several guides needs its own handler rather than a loop over the one above: that
     one rebuilds the list from the `guides` it captured at render, so awaiting it once per id
     writes the same near-complete list back each time and only the final removal survives. One
     filter, one write. */
  const deleteGuidesHandler=async(ids)=>{
    const kill=new Set(ids||[]);
    if(!kill.size) return;
    const next=guides.filter(g=>!kill.has(g.id));
    setGuides(next);
    let confirmed=true;
    for(const id of kill){ if(!await removeOneGuide(id)) confirmed=false; }
    for(const id of kill) await delMedia(id);
    setMediaCache(c=>{ const n={...c}; kill.forEach(id=>delete n["img-"+id]); return n; });
    showToast(confirmed?`Removed ${kill.size} guide${kill.size!==1?"s":""}`:"⚠ Removed on this device only — sign in with the admin Google account and try again.",confirmed?undefined:"error");
  };

  const saveProdHandler=async(saved,cachePatch)=>{
    const next=products.find(p=>p.id===saved.id)?products.map(p=>p.id===saved.id?saved:p):[...products,saved];
    setProducts(next);
    if(cachePatch&&Object.keys(cachePatch).length)setMediaCache(c=>({...c,...cachePatch}));
    // Only the edited row goes to the cloud, not the whole catalog. Awaited so the form's
    // spinner reflects the real write — and it's time-bounded, so it can't spin forever.
    const confirmed=await saveOneProd(saved,next);
    // Learn the HSN + rate this product was listed with, so the next similar
    // product can offer it instead of asking for it again. Saved separately from
    // the product itself: a failure here must not cost the owner the listing.
    if(saved.gstApplicable && String(saved.hsn||"").trim() && Number(saved.gstRate)>0){
      const master=readHsnMaster(settings);
      const updated=upsertHsnMaster(master,{hsn:saved.hsn,rate:saved.gstRate,name:saved.name,category:saved.category});
      // upsert always returns a new array; only write when something really moved.
      const changed=JSON.stringify(updated)!==JSON.stringify(master);
      if(changed){
        const s={...settings,hsnMaster:updated};
        setSettings(s);
        try{ await saveSettings(s); }catch(e){}
      }
    }
    showToast(confirmed||!FB_OK?"Product saved!":"Saved on this device — syncing when the connection returns");
  };
  const deleteProdHandler=async id=>{
    const prod=products.find(p=>p.id===id);
    setProducts(prev=>{const next=prev.filter(p=>p.id!==id);saveProd(next);return next;});
    if(prod&&Array.isArray(prod.media)){ for(const m of prod.media) await delMediaItem(m.key); }
    await delMedia(id);
    setMediaCache(c=>{const n={...c};delete n["img-"+id];delete n["vid-"+id];(prod?.media||[]).forEach(m=>delete n["m-"+m.key]);return n;});
    showToast("Product deleted");
  };
  const updateOrderHandler=async updated=>{
    const old=orders.find(o=>o.id===updated.id);
    const prevStatus=old?old.status:"";
    const becamePaid=paymentSucceeded(updated)&&!paymentSucceeded(old);
    /* Only on the crossing, not on every save of an order already in that state — re-saving a
       shipped one to correct a courier number must not tell the customer it shipped again.
       Confirmed is deliberately absent: it happens at payment, while the customer is looking
       at the screen that says so. */
    const PUSH_ON={Shipped:"shipped",Delivered:"delivered"};
    if(updated.status!==prevStatus && PUSH_ON[updated.status] && updated.userUid){
      queueOrderPush(updated.userUid, updated.id, PUSH_ON[updated.status]);
    }
    if(becamePaid){
      if(updated.referralCode){
        const consumed=await finalizeReferralOnPayment(updated.referralCode,updated.userUid,updated.id);
        if(consumed&&!updated.referralUsageCounted){ bumpPromoUsage("referral"); updated={...updated,referralUsageCounted:true}; }
      }
    }
    // ── On a successfully paid DELIVERY: all order-spend rewards are granted here. ──
    if(updated.status==="Delivered" && paymentSucceeded(updated)){
      // (a) buyer earns loyalty points on the amount actually paid
      if(settings.loyaltyEnabled!==false && updated.userUid && !updated.pointsEarned){
        /* Reward coins are earned on what the customer ACTUALLY PAID for the goods: the product
           value less every discount they used, and never the shipping / parcel / packing cost.
           This used to run off `total` — the subtotal before any discount — so a ₹1,000 order
           settled with a ₹300 coupon still earned coins on the full ₹1,000. That compounds:
           spend a coupon, earn full coins anyway, spend those coins next order, earn full again.
           The comment here always claimed "the amount actually paid"; now it is true. */
        const pts=coinsEarnedFor(updated, settings);
        if(pts>0){
          const credited=await adminCreditLoyalty(updated.userUid, pts, "earn:"+updated.id, "Order "+(updated.orderNo||updated.id), settings.walletValidityMonths);
          if(credited) updated={...updated,pointsEarned:pts};
        }
      }
      /* (b) the OWNER of the referral code earns theirs — a different customer from the buyer.
         Paid here, on delivery, rather than on payment: a referral that is cancelled or refunded
         before it arrives never happened, and paying at delivery means there is nothing to claw
         back in the ordinary case. adminCreditLoyalty is idempotent per entryId, so a re-save of
         a delivered order cannot pay twice. `referralOwnerUid` was stamped on the order when the
         code was reserved, so a code that has since changed hands still pays the right person. */
      if(settings.referralEnabled!==false && updated.referralOwnerUid && !updated.referralCoinsPaid){
        const coins=referralOwnerCoins(settings);
        if(coins>0){
          const credited=await adminCreditLoyalty(updated.referralOwnerUid, coins, "refer:"+updated.id,
            "Referral reward — order "+(updated.orderNo||updated.id), settings.walletValidityMonths);
          if(credited) updated={...updated,referralCoinsPaid:coins};
        }
      }
    }
    // ── On CANCEL: restock once and idempotently claw back anything this order earned. ──
    // Running the wallet reconciliation on every later save means a temporary Firebase error
    // is retried; each silent reversal carries a private idempotency marker in the wallet.
    if(updated.status==="Cancelled"){
      if(!old?.restocked && !updated.restocked){ updated={...updated,restocked:true}; restock(updated); }
      // Remove every coin lot tied to this order without adding cancellation rows to the wallet.
      if(Number(updated.pointsEarned)>0 && updated.userUid){
        const removed=await silentlyRemoveLoyaltyCredit(updated.userUid,"earn:"+updated.id,Number(updated.pointsEarned));
        if(removed) updated={...updated,pointsEarned:0,pointsReversed:true};
      }
      // A referral reward is only ever paid at delivery, so this reverses the rare case of an
      // order cancelled AFTER it was delivered — a return resolved as a cancellation, say.
      if(Number(updated.referralCoinsPaid)>0 && updated.referralOwnerUid){
        const removed=await silentlyRemoveLoyaltyCredit(updated.referralOwnerUid,"refer:"+updated.id,Number(updated.referralCoinsPaid));
        if(removed) updated={...updated,referralCoinsPaid:0,referralCoinsReversed:true};
      }
      if(updated.shippingReward&&updated.userUid){
        const coinVal=Number(settings.loyaltyRedeemValue||1)||1;
        const coins=Math.round(Number(updated.shippingReward.amount||0)/coinVal);
        const creditId=updated.shippingReward.creditId||("ship:"+updated.shippingReward.code);
        const removed=await silentlyRemoveLoyaltyCredit(updated.userUid,creditId,coins);
        if(removed) updated={...updated,shippingReward:null};
      }
      if(updated.doa?.resolution==="coins"&&Number(updated.doa.refundAmount)>0&&updated.userUid){
        const coinVal=Number(settings.loyaltyRedeemValue||1)||1;
        await silentlyRemoveLoyaltyCredit(updated.userUid,"doa:"+updated.id,Math.ceil(Number(updated.doa.refundAmount)/coinVal));
      }
      if((updated.returnReq?.adminResolution||updated.returnReq?.resolution)==="coins"&&updated.userUid){
        const coinVal=Number(settings.loyaltyRedeemValue||1)||1;
        await silentlyRemoveLoyaltyCredit(updated.userUid,"return:"+updated.id,Math.ceil(returnItemsValue(updated)/coinVal));
      }
      if(updated.referralCode) await releaseReferralReservation(updated.referralCode,updated.userUid,updated.id);
      // refund any wallet points the buyer SPENT on this order (they shouldn't lose points on a cancelled order)
      if(Number(updated.loyaltyDiscount)>0 && updated.userUid && !updated.loyaltyRefunded){
        const coinVal=Number(settings.loyaltyRedeemValue||1)||1;
        const back=Math.ceil(Number(updated.loyaltyDiscount)/coinVal);
        const restored=await silentlyRestoreRedeemedPoints(updated.userUid,updated.id,back,settings.walletValidityMonths);
        if(restored) updated={...updated,loyaltyRefunded:true};
      }
    }
    setOrders(prev=>prev.map(o=>o.id===updated.id?updated:o));
    await saveOneOrder(updated);
    // Notify the customer by email when the order moves to a new milestone (if they opted in)
    if(updated.status!==prevStatus){
      const evMap={Confirmed:"confirmed",Shipped:"shipped",Delivered:"delivered"};
      const ev=evMap[updated.status];
      if(ev) sendCustomerEmail(updated, settings, ev);
    }
  };
  const deleteOrderHandler=async order=>{
    setOrders(prev=>prev.filter(o=>o.id!==order.id));
    // Deleting is an admin action, so the admin's own snapshot is the cache to correct — the
    // shared customer key is written by the customer's own listener and is not this one.
    const r=await dbGet(ADMIN_ORDER_CACHE); const arr=r?JSON.parse(r):[]; await dbSet(ADMIN_ORDER_CACHE,JSON.stringify(arr.filter(x=>x.id!==order.id)));
    // Removing the order also removes its payment screenshot (stored on the order) — frees Firebase space.
    if(FB_OK&&order.userUid){ try{ await FB_DB.ref("orders/"+order.userUid+"/"+order.id).remove(); }catch(e){} }
  };
  const cleanupOldOrders=async months=>{
    const cutoff=Date.now()-months*30*24*60*60*1000;
    const old=orders.filter(o=>(o.status==="Delivered"||o.status==="Cancelled") && new Date(o.placedAt||0).getTime()<cutoff);
    for(const o of old){ await deleteOrderHandler(o); }
    return old.length;
  };
  /* Go-live reset — clears every test order. Guarded by the admin uid check as well as the
     UI's confirmation flow, because this is the one action in the panel with no undo. */
  const resetOrderDataHandler=async opts=>{
    if(!isAdminUid(user?.uid)){ showToast("⚠ Sign in with the admin Google account first","error"); return null; }
    const report=await resetAllOrderData(opts||{});
    setOrders([]);
    setWalletPts(0);
    setAbandonedCarts([]);
    return report;
  };
  /* Opt-in migration: generate a small catalog thumbnail for every product image that lacks one,
     so the shop grid loads tiny images instead of full-size photos. Works on BOTH plans:
       • Free (no Storage): thumbnails are stored as base64 in the Realtime Database.
       • Paid (Storage on): images move to Storage and their URL + thumbUrl get embedded.
     Purely additive — full-size images are never deleted. */
  const backfillThumbs=async(onProgress)=>{
    let done=0;
    for(const p of products){
      if(!Array.isArray(p.media)||!p.media.length) continue;
      const firstImgKey=(p.media.find(m=>m.type!=="video")||{}).key;
      let changed=false; const patch={}; const newMedia=[];
      for(const m of p.media){
        const entry={...m};
        const isThumbTarget = m.key===firstImgKey;   // only the 1st image becomes the thumbnail
        const cur = m.url || mediaCache["m-"+m.key] || await loadMediaItem(m.key);
        // Embed an existing Storage URL on the record (cheap, kills a per-image DB read).
        if(typeof cur==="string" && /^https?:/.test(cur) && !entry.url){ entry.url=cur; changed=true; }
        // Generate a thumbnail ONLY for the first image, and only if it doesn't have one yet.
        if(isThumbTarget && !entry.thumb && !entry.thumbUrl && typeof cur==="string"){
          if(FB_STORAGE && /^https?:/.test(cur)){
            const t=await makeThumbFromAny(cur);
            if(t){ const tu=await uploadToStorage("media/"+m.key+"_thumb.jpg",t); if(tu){ entry.thumbUrl=tu; entry.thumb=1; patch["thumb-"+m.key]=t; changed=true; } }
          } else if(cur.startsWith("data:")){
            if(FB_STORAGE){
              const r=await persistImage(m.key, cur, true);
              if(r.url){ entry.url=r.url; changed=true; if(r.url_thumb) entry.thumbUrl=r.url_thumb; }
              if(r.thumbData){ entry.thumb=1; patch["thumb-"+m.key]=r.thumbData; changed=true; }
            } else {
              const t=await makeThumb(cur);
              if(t){ await saveMediaItem(m.key+"_thumb", t); entry.thumb=1; patch["thumb-"+m.key]=t; changed=true; }
            }
          }
        }
        newMedia.push(entry);
      }
      if(changed){
        const saved={...p,media:newMedia};
        setProducts(prev=>{ const next=prev.map(x=>x.id===saved.id?saved:x); saveProd(next); return next; });
        setMediaCache(c=>({...c,...patch}));
        done++;
      }
      if(onProgress) onProgress(done);
    }
    return done;
  };

  // Keep each product's rating/count in sync with its REAL reviews
  const recomputeProductRating=(pid, reviews)=>{
    const count=reviews.length;
    const avg=count?reviews.reduce((s,r)=>s+r.rating,0)/count:0;
    setProducts(prev=>{
      const next=prev.map(p=>p.id===pid?{...p,reviewCount:count,ratingAvg:Math.round(avg*10)/10}:p);
      saveProd(next);
      return next;
    });
  };
  const placeOrder=(o)=>{
    // Demo/review sessions: the order stays on this device only — no cloud order,
    // no stock decrement, no admin visibility.
    const demo=isDemoUser(user);
    if(demo) o={...o,demo:true};
    setCart([]);
    setOrders(prev=>[o,...prev]);
    saveOneOrder(o);
    if(demo) return;
    trackFunnel("order");
    // NOTE: loyalty points are earned ONLY when the order is delivered (see updateOrderHandler),
    // never at placement — an unpaid/cancelled order earns nothing.
    // Atomically decrement stock in the cloud (prevents overselling across devices).
    // Two counters move together for an option product: the option's own count and the
    // product-wide total, each under its own transaction so concurrent buyers can't oversell.
    const sold={};                       // pid -> units (product-wide)
    const soldVar={};                    // pid -> { variantId -> units }
    o.items.forEach(it=>{
      sold[it.id]=(sold[it.id]||0)+it.qty;
      if(it.variantId){ (soldVar[it.id]=soldVar[it.id]||{})[it.variantId]=(soldVar[it.id][it.variantId]||0)+it.qty; }
    });
    if(FB_OK){
      Object.keys(sold).forEach(pid=>{
        try{
          FB_DB.ref("products/"+pid+"/stockCount").transaction(cur=>{
            const c=(typeof cur==="number")?cur:DEFAULT_STOCK;
            return Math.max(0, c - sold[pid]);
          });
        }catch(e){}
        // Only touch a per-option counter that already exists — a product still on the shared
        // pool must not sprout one here, or its stock would start reading as zero.
        Object.keys(soldVar[pid]||{}).forEach(vid=>{
          try{
            FB_DB.ref("products/"+pid+"/variantStock/"+vid).transaction(cur=>{
              if(typeof cur!=="number") return cur;   // abort: no per-option stock on this product
              return Math.max(0, cur - soldVar[pid][vid]);
            });
          }catch(e){}
        });
      });
    }
    setProducts(prev=>{
      const next=prev.map(p=>{
        if(!sold[p.id]) return p;
        const np={...p,stockCount:Math.max(0,(p.stockCount??DEFAULT_STOCK)-sold[p.id])};
        if(hasVariantStock(p) && soldVar[p.id]){
          const vs={...p.variantStock};
          Object.keys(soldVar[p.id]).forEach(vid=>{ if(typeof vs[vid]==="number") vs[vid]=Math.max(0, vs[vid]-soldVar[p.id][vid]); });
          np.variantStock=vs;
        }
        return np;
      });
      if(!FB_OK) saveProd(next);
      else dbSet("nemo-products",JSON.stringify(next)); // local cache only; cloud handled by transaction
      return next;
    });
  };

  // Customer reports a Dead-on-Arrival fish → flags the order (best-effort cloud write) and routes them to WhatsApp
  const reportDoa=async(order,opts={})=>{
    if(order.doa&&order.doa.status&&order.doa.status!=="Requested") return; // don't overwrite an in-progress/resolved request
    // Claims are recorded per item and accumulate, so a customer who opens a second bag an hour
    // later adds to the same request rather than replacing the first one. The order-level `doa`
    // record is kept as the umbrella the admin screen and the status text still read.
    const prevItems=(order.doaItems&&typeof order.doaItems==="object")?order.doaItems:{};
    const doaItems=opts.itemId
      ? {...prevItems,[opts.itemId]:{ name:opts.itemName||"", qty:Number(opts.qty)||1, cause:opts.cause||"",
          note:opts.note||"", resolution:opts.resolution==="coins"?"coins":"refund", requestedAt:new Date().toISOString() }}
      : prevItems;
    // The umbrella reason stays human-readable: every item's claim, one per line.
    const allReasons=Object.values(doaItems).map(c=>`${c.name||"Item"} x${c.qty||1}: ${[c.cause,c.note].filter(Boolean).join(" — ")}`).join(" | ")
      || opts.reason || "";
    const updated={...order,doaItems,doa:{status:"Requested",requestedAt:(order.doa&&order.doa.requestedAt)||new Date().toISOString(),note:(order.doa&&order.doa.note)||"",resolution:opts.resolution==="coins"?"coins":"refund",claimReason:allReasons}};
    setOrders(prev=>prev.map(o=>o.id===updated.id?updated:o));
    await saveOneOrder(updated);
    showToast("DOA request noted — please send your video on WhatsApp");
  };

  // Customer cancels their own order instantly (only inside the self-cancel window)
  const cancelByCustomer=async(order)=>{
    if(!selfCancelOpen(order)){ showToast("This order can no longer be cancelled","error"); return; }
    const paid=!!order.paidAt||["Payment Review","Confirmed"].includes(order.status);
    const refund=paid
      ? { due:true, amount:order.amountDue??((order.total||0)+(order.fee||0)), method:"upi", refundTxnId:"", status:"pending", updatedAt:new Date().toISOString() }
      : { due:false, amount:0, method:"none", refundTxnId:"", status:"none", updatedAt:new Date().toISOString() };
    let updated={...order,status:"Cancelled",paymentStatus:paid?"Cancelled by customer — refund due":"Cancelled by customer",cancelReason:"Cancelled by customer",cancelledBy:"customer",refund,restocked:true,updatedAt:new Date().toISOString()};
    setOrders(prev=>prev.map(o=>o.id===updated.id?updated:o));
    await saveOneOrder(updated);
    restock(order);
    if(Number(order.loyaltyDiscount)>0 && order.userUid && !order.loyaltyRefunded){
      const coinVal=Number(settings.loyaltyRedeemValue||1)||1;
      const restored=await silentlyRestoreRedeemedPoints(order.userUid,order.id,Number(order.loyaltyCoinsUsed)||Math.ceil(Number(order.loyaltyDiscount)/coinVal),settings.walletValidityMonths);
      if(restored) updated={...updated,loyaltyRefunded:true};
    }
    if(order.referralCode) await releaseReferralReservation(order.referralCode,order.userUid,order.id);
    setOrders(prev=>prev.map(o=>o.id===updated.id?updated:o));
    if(updated.loyaltyRefunded&&!order.loyaltyRefunded) await saveOneOrder(updated);
    showToast(paid?"Order cancelled — your refund will be processed":"Order cancelled");
  };

  // Customer raises a damaged-item return / replacement request
  const requestReturn=async(order,payload={})=>{
    const updated={...order, returnReq:{ status:"Requested", requestedAt:new Date().toISOString(),
      itemIds:payload.itemIds||[], reason:payload.reason||"", photo:payload.photo||"",
      resolution:payload.resolution||"refund", courier:"", consignment:"", note:"" }};
    setOrders(prev=>prev.map(o=>o.id===updated.id?updated:o));
    await saveOneOrder(updated);
    showToast("Return request submitted — we'll review and update you");
  };
  // Customer adds courier + consignment details once the return is approved
  const submitReturnShipment=async(order,ship={})=>{
    const rr={...(order.returnReq||{}), status:"Shipped", courier:ship.courier||"", consignment:ship.consignment||"", shippedAt:new Date().toISOString()};
    const updated={...order, returnReq:rr};
    setOrders(prev=>prev.map(o=>o.id===updated.id?updated:o));
    await saveOneOrder(updated);
    showToast("Return shipment details saved — thank you");
  };

  // Restock items from a cancelled order
  const restock=(o)=>{
    const back={}, backVar={};
    (o.items||[]).forEach(it=>{
      back[it.id]=(back[it.id]||0)+it.qty;
      if(it.variantId){ (backVar[it.id]=backVar[it.id]||{})[it.variantId]=(backVar[it.id][it.variantId]||0)+it.qty; }
    });
    if(FB_OK){ Object.keys(back).forEach(pid=>{
      try{ FB_DB.ref("products/"+pid+"/stockCount").transaction(cur=>(typeof cur==="number"?cur:0)+back[pid]); }catch(e){}
      // Mirror of the checkout decrement: give the units back to the option they came from,
      // and leave products still on the shared pool untouched.
      Object.keys(backVar[pid]||{}).forEach(vid=>{
        try{ FB_DB.ref("products/"+pid+"/variantStock/"+vid).transaction(cur=>(typeof cur==="number")?cur+backVar[pid][vid]:cur); }catch(e){}
      });
    }); }
    setProducts(prev=>{
      const next=prev.map(p=>{
        if(!back[p.id]) return p;
        const np={...p,stockCount:(p.stockCount??0)+back[p.id]};
        if(hasVariantStock(p) && backVar[p.id]){
          const vs={...p.variantStock};
          Object.keys(backVar[p.id]).forEach(vid=>{ if(typeof vs[vid]==="number") vs[vid]=vs[vid]+backVar[p.id][vid]; });
          np.variantStock=vs;
        }
        return np;
      });
      if(!FB_OK) saveProd(next); else dbSet("nemo-products",JSON.stringify(next));
      return next;
    });
  };

  // Auto-cancel an unpaid order past its window (idempotent)
  const cancelUnpaid=async(order)=>{
    if(order.status!=="Awaiting Payment")return;
    let updated={...order,status:"Cancelled",paymentStatus:"Unpaid — auto-cancelled",restocked:true,updatedAt:new Date().toISOString()};
    setOrders(prev=>prev.map(o=>o.id===updated.id?updated:o));
    await saveOneOrder(updated);
    if(Number(order.loyaltyDiscount)>0&&order.userUid&&!order.loyaltyRefunded){
      const coinVal=Number(settings.loyaltyRedeemValue||1)||1;
      const restored=await silentlyRestoreRedeemedPoints(order.userUid,order.id,Number(order.loyaltyCoinsUsed)||Math.ceil(Number(order.loyaltyDiscount)/coinVal),settings.walletValidityMonths);
      if(restored) updated={...updated,loyaltyRefunded:true};
    }
    if(order.referralCode) await releaseReferralReservation(order.referralCode,order.userUid,order.id);
    setOrders(prev=>prev.map(o=>o.id===updated.id?updated:o));
    if(updated.loyaltyRefunded&&!order.loyaltyRefunded) await saveOneOrder(updated);
    restock(order);
  };

  /* Backing out of payment on purpose must not cost the shopper their basket. The order is
     cancelled and its stock released exactly as before, but the lines it was built from go
     straight back into the cart and we land them there — rebuilding a whole order by hand
     is where an abandoned payment turns into an abandoned customer.
     A window that runs out gets the same treatment: an unpaid order is not a decision to stop
     shopping, and leaving the shopper with a cancelled order and an empty basket is how an
     abandoned payment turns into an abandoned customer. */
  const restoreLinesToCart=(lines)=>{
    if(!lines||!lines.length) return;
    setCart(prev=>{
      const next=[...prev];
      lines.forEach(line=>{
        const at=next.findIndex(i=>i.key===line.key);
        if(at<0){ next.push({...line}); return; }
        // Same line already back in the cart (added again while payment was open): keep
        // one line, and never let the merge push it past what may actually be bought.
        const max=Math.min(next[at].stockCount??DEFAULT_STOCK,MAX_PER_ORDER);
        next[at]={...next[at],qty:Math.min(max,next[at].qty+line.qty)};
      });
      return next;
    });
  };
  const cancelPaymentAndRestoreCart=async(order)=>{
    // A second press (or a press on an order that has moved on) must not stack the same
    // lines into the cart twice — cancelUnpaid is idempotent and so is this.
    if(!order||order.status!=="Awaiting Payment"){ navRewind("cart"); return; }
    const lines=order.items||[];
    await cancelUnpaid(order);
    restoreLinesToCart(lines);
    navRewind("cart");
    showToast("Payment Cancelled");
  };

  /* The payment window ran out. Same outcome as backing out on purpose — the order is
     cancelled, its stock released and its lines handed back — with three differences that
     matter because this runs unattended, from a sweep, on whatever device happens to be open:

     · it never navigates. Yanking someone into the cart mid-sentence because a timer they had
       forgotten about elapsed is worse than the empty basket it is fixing.
     · `cartReturned` is written on the order first, so the same expiry cannot hand the same
       lines back twice — on a second sweep, on a second tab, or on a second device.
     · the toast says what happened to the items, because nobody watched it happen. */
  const expireUnpaid=async(order)=>{
    if(!order||order.status!=="Awaiting Payment") return;
    if(order.cartReturned){ await cancelUnpaid(order); return; }
    const lines=order.items||[];
    // Claimed before the await: two sweeps can otherwise both read "not yet returned".
    setOrders(prev=>prev.map(o=>o.id===order.id?{...o,cartReturned:true}:o));
    await cancelUnpaid({...order,cartReturned:true});
    if(lines.length){
      restoreLinesToCart(lines);
      showToast("Payment time ran out — your items are back in the cart");
    }
  };

  // Auto-close a delivered order once its return window has passed (idempotent).
  const autoCloseOrder=async(order)=>{
    if(!order||order.closed||order.demo) return;
    const updated={...order,closed:true,closedAt:new Date().toISOString(),closedAuto:true,updatedAt:new Date().toISOString()};
    setOrders(prev=>prev.map(o=>o.id===updated.id?updated:o));
    await saveOneOrder(updated);
  };
  // When is a delivered order due to auto-close? Admin's per-order date wins, else deliveredAt + N days.
  const orderCloseDueAt=(o)=>{
    if(o.autoCloseAt) return new Date(o.autoCloseAt).getTime();
    const base=deliveredAtOf(o); if(!base) return 0;
    const days=orderRetentionDays(o);
    return new Date(base).getTime()+Math.max(0,days)*86400000;
  };

  // Sweep for expired unpaid orders + due auto-closes every 30s + on order changes
  useEffect(()=>{
    const sweep=()=>{
      const now=Date.now();
      orders.forEach(o=>{
        if(o.status==="Awaiting Payment" && o.paymentDeadline && now>o.paymentDeadline){ expireUnpaid(o); return; }
        // Auto-close: delivered, not closed, no open DOA / return, past its close date.
        if(o.status==="Delivered" && !o.closed && !o.demo){
          const doaOpen = o.doa && !((o.doa.status||"").startsWith("Approved") || o.doa.status==="Declined");
          const retOpen = o.returnReq && !["Resolved","Declined"].includes(o.returnReq.status);
          if(doaOpen||retOpen) return;
          const due=orderCloseDueAt(o);
          if(due && now>=due) autoCloseOrder(o);
        }
      });
    };
    sweep();
    const t=setInterval(sweep,30000);
    return()=>clearInterval(t);
  },[orders]);

  const cartCount=useMemo(()=>cart.reduce((s,i)=>s+i.qty,0),[cart]);
  const cartTotal=useMemo(()=>cart.reduce((s,i)=>s+i.price*i.qty,0),[cart]);
  const cartMap=useMemo(()=>{ const m={}; cart.forEach(i=>{m[i.id]=(m[i.id]||0)+i.qty;}); return m; },[cart]);
  const priorityOrderCount=useMemo(()=>{
    if(!user) return 0;
    const uk=userKey(user);
    return orders.filter(o=>!cancelledByCustomer(o)&&customerOrderStage(o)!=="Past Orders"&&(
      (o.userUid&&uk&&o.userUid===uk)||(user.uid&&o.userUid===user.uid)||
      (user.phone&&normalizePhone(o.address?.phone)===normalizePhone(user.phone))
    )).length;
  },[orders,user]);
  const isAdminPage=["admin-login","admin"].includes(page);
  const [miniOpen,setMiniOpen]=useState(false);

  /* ── Swipe between the bottom-nav tabs ──────────────────────────────────────
     The same four tabs, in the same order, that the bar at the bottom shows: a sideways swipe
     is that bar under your thumb instead of at the edge of your reach. It sits on the scroll
     container rather than on any one page, because a gesture that works on Home and nowhere
     else is worse than no gesture — people stop trusting it.

     Three things it must not fight:
       · Android 10+ reserves a strip at BOTH screen edges for its own Back gesture, so a touch
         starting there belongs to the system. This is why it is not an edge-swipe drawer.
       · The store is built out of rows that scroll sideways — category chips, new arrivals,
         offers, "goes well with". A drag that starts on one of those belongs to the row.
       · Anything laid OVER the page — the Browse drawer, the wallet sheet, a lightbox — is not
         the page, and a swipe across it is not a swipe between tabs. Every one of them is
         position:fixed, which is a truer test than a list of names that would rot. */
  const NAV_TABS=["home","shop","orders","cart"];
  const SWIPE_EDGE=32, SWIPE_MIN=70;
  const swipeFrom=useRef(null);
  const [homeMenuSignal,setHomeMenuSignal]=useState(0);
  const onTabTouchStart=(e)=>{
    swipeFrom.current=null;
    if(NAV_TABS.indexOf(page)<0) return;
    if(!e.touches||e.touches.length!==1) return;
    const t=e.touches[0], w=window.innerWidth||0;
    if(t.clientX<SWIPE_EDGE||t.clientX>w-SWIPE_EDGE) return;
    for(let el=e.target; el&&el!==e.currentTarget; el=el.parentElement){
      let cs=null; try{ cs=getComputedStyle(el); }catch(err){}
      if(!cs) continue;
      if(cs.position==="fixed") return;
      /* Overflowing is not the same as scrollable, and testing the width alone is what kept
         this from firing near the top of Home: the hero clips two decorative circles off its
         right edge, so it overflows by forty pixels while scrolling nothing. */
      if(el.scrollWidth>el.clientWidth+4&&(cs.overflowX==="auto"||cs.overflowX==="scroll")) return;
    }
    swipeFrom.current={x:t.clientX,y:t.clientY};
  };
  const onTabTouchEnd=(e)=>{
    const from=swipeFrom.current; swipeFrom.current=null;
    if(!from||!e.changedTouches||!e.changedTouches.length) return;
    const t=e.changedTouches[0], dx=t.clientX-from.x, dy=t.clientY-from.y;
    /* Mostly sideways, and far enough to be deliberate — a diagonal flick while scrolling the
       page must not change tab. */
    if(Math.abs(dx)<SWIPE_MIN||Math.abs(dx)<Math.abs(dy)*2) return;
    const i=NAV_TABS.indexOf(page); if(i<0) return;
    const j=i+(dx>0?-1:1);
    // Past the left end of the strip is Browse, which is what a customer on Home wants next.
    if(j<0){ setHomeMenuSignal(n=>n+1); return; }
    // Past the right end there is nothing, and a bounce back to Home would be a surprise.
    if(j>=NAV_TABS.length) return;
    nav(NAV_TABS[j]);
  };
  useEffect(()=>{ if(cart.length===0) setMiniOpen(false); },[cart.length]); // auto-close when cart empties

  // ── "Why Nemo" welcome popup — first visit of the day, once per day ──
  // Waits for the app to be ready AND for the splash to lift, so it opens onto the store rather
  // than under the splash overlay. Never shown over the admin panel. The date stamp is written
  // the moment it opens, so a reload the same day doesn't bring it back — except for a forced
  // ?why=1 showing, which leaves the stamp alone.
  const [whyOpen,setWhyOpen]=useState(false);
  const whyArmed=useRef(false);
  useEffect(()=>{
    if(loading||isAdminPage||whyArmed.current) return;
    const forced=whyUsForced();
    if(!forced && !whyUsDue()) return;
    whyArmed.current=true;   // at most one showing per app session, whatever happens after this
    return whenSplashGone(()=>{ if(!forced) markWhyUsShown(); setWhyOpen(true); });
  },[loading,isAdminPage]);
  // Reveal-on-scroll: tagged (.js-reveal) sections spring up as they enter the viewport.
  // Progressive enhancement — only JS adds the hidden state, so content stays visible if this never runs.
  useEffect(()=>{
    if(typeof IntersectionObserver==="undefined") return;
    let io;
    /* The per-card stagger that used to live here is gone with its last caller. It hid children
       AFTER they had been painted, which is only invisible when the container starts below the
       fold — and the one grid using it was the Shop grid, filling the screen on arrival. */
    const raf=requestAnimationFrame(()=>{
      const els=document.querySelectorAll(".js-reveal:not(.reveal-in)");
      if(!els.length) return;
      els.forEach(el=>el.classList.add("reveal"));
      io=new IntersectionObserver((ents)=>{ ents.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add("reveal-in"); io.unobserve(en.target); } }); },{threshold:0.06,rootMargin:"0px 0px -40px 0px"});
      els.forEach(el=>io.observe(el));
    });
    return ()=>{ cancelAnimationFrame(raf); if(io) io.disconnect(); };
  },[page]);
  // When in admin mode, a page refresh/close prompts for confirmation so you don't exit admin by accident.
  useEffect(()=>{
    if(page!=="admin") return;
    const warn=e=>{ e.preventDefault(); e.returnValue=""; return ""; };
    window.addEventListener("beforeunload",warn);
    return ()=>window.removeEventListener("beforeunload",warn);
  },[page]);
  // Load all orders when entering admin; load the user's own orders when they sign in
  // ADMIN: live listener on ALL orders (reflects new orders + customer payments instantly)
  useEffect(()=>{
    if(page!=="admin") return;
    loadInterestCounts().then(setInterestCounts);
    if(FB_OK && FB_DB){
      const ref=FB_DB.ref("orders");
      const cb=ref.on("value",snap=>{
        const v=snap.val(); const all=[];
        if(v) Object.values(v).forEach(byUser=>{ if(byUser&&typeof byUser==="object") Object.values(byUser).forEach(o=>{ if(o&&o.id) all.push(o); }); });
        all.sort((x,y)=>(y.placedAt||"").localeCompare(x.placedAt||""));
        setOrders(all);
        try{ localStorage.setItem(ADMIN_ORDER_CACHE,JSON.stringify(all)); }catch(e){}
      },err=>{ /* permission denied = not signed in as admin; fall back to one-shot */ loadOrders().then(o=>o&&setOrders(o)); });
      return ()=>ref.off("value",cb);
    } else {
      loadOrders().then(o=>o&&setOrders(o));
    }
  },[page,fbReady]);

  // GLOBAL: live listener on the CATALOGUE. cloudSync reads products exactly once per boot
  // (it is guarded by cloudSyncDone), so until now an admin's edit reached a shopper only
  // when they next cold-started the app — a price change, a restock, a new product or a
  // delisting could sit unseen on an open storefront indefinitely. This subscribes to the
  // same node cloudSync reads, so every edit lands on every open screen as it is saved.
  //
  // An empty or failed read is deliberately ignored rather than rendered: a permission
  // denial, a dropped connection or a mid-write moment must never blank the shop or drop
  // it back to DEFAULT_PRODUCTS. The screen keeps whatever it has until real data arrives.
  useEffect(()=>{
    if(!(FB_OK && FB_DB)) return;
    // `last` lives for the life of the subscription, so the cache write and the media
    // fetch below run only on a real change — they must stay out of the setProducts
    // updater, which React is free to call more than once for a single update.
    let alive=true, last=null;
    const ref=FB_DB.ref("products");
    const cb=ref.on("value",s=>{
      if(!alive) return;
      const v=s&&s.val();
      const list=v?Object.values(v).filter(p=>p&&p.id):[];
      if(!list.length) return;
      const next=list.map(normalizeProduct);
      if(sameCatalog(last,next)) return;
      last=next;
      try{ dbSet("nemo-products",JSON.stringify(next)); }catch(e){}
      hydrateMedia(next, localRequests(), localGuidesData()||[]);
      // sameCatalog again against the live state: the boot read may have already applied
      // this exact catalogue, and handing back a fresh array would re-render the whole
      // grid and replay its reveal animation for no reason.
      setProducts(prev=>sameCatalog(prev,next)?prev:next);
    },()=>{ /* denied or offline — keep showing what is already on screen */ });
    return ()=>{ alive=false; try{ ref.off("value",cb); }catch(e){} };
  },[fbReady]);

  // Only the compact winner record is public. Monthly entry metadata stays admin-only, and
  // expired photos remain deleted rather than being retained for a winner banner.
  useEffect(()=>{
    if(!(FB_OK&&FB_DB)) return;
    const ref=FB_DB.ref("tankMonthlyWinners/"+previousTotmMonth(Date.now()));
    const cb=ref.on("value",s=>setTankPreviousWinners((s&&s.val())||null),()=>{});
    return ()=>{ try{ref.off("value",cb);}catch(e){} };
  },[fbReady,activeTankMonth]);

  /* GLOBAL: live listener on this month's Tank-of-the-Month votes. Counts have to move for
     everyone as they are cast — a vote total that only refreshes on a cold start is a vote
     total nobody trusts. Scoped to the current month, so last month's ballots are not carried
     around forever. */
  useEffect(()=>{
    if(!(FB_OK && FB_DB)) return;
    setTotmVotes({});
    const ref=FB_DB.ref("totmVotes/"+activeTankMonth);
    let alive=true;
    const cb=ref.on("value",s=>{ if(alive) setTotmVotes((s&&s.val())||{}); },()=>{});
    return ()=>{ alive=false; try{ ref.off("value",cb); }catch(e){} };
  },[fbReady,activeTankMonth]);

  // GLOBAL: live listener on the CARE GUIDES — same one-shot read, same fix as the catalogue.
  useEffect(()=>{
    if(!(FB_OK && FB_DB)) return;
    let alive=true, last=null;
    const ref=FB_DB.ref("guides");
    const cb=ref.on("value",s=>{
      if(!alive) return;
      const v=s&&s.val();
      const raw=v?Object.values(v).filter(g=>g&&g.id):[];
      const list=raw.filter(g=>!isSampleGuide(g));
      if(isAdminSignedIn()) raw.filter(isSampleGuide).forEach(g=>{ try{ FB_DB.ref("guides/"+g.id).remove(); }catch(e){} });
      if(sameCatalog(last,list)) return;
      last=list;
      try{ dbSet("nemo-guides",JSON.stringify(list)); }catch(e){}
      hydrateMedia(localProducts()||[], localRequests(), list);
      setGuides(prev=>sameCatalog(prev,list)?prev:list);
    },()=>{ /* denied or offline — keep what is on screen */ });
    return ()=>{ alive=false; try{ ref.off("value",cb); }catch(e){} };
  },[fbReady]);

  // GLOBAL: live listener on SETTINGS — coupons, banners, delivery charges, the store-closed
  // switch, live-fish zones. All of it was read once per boot, so a change made in admin
  // reached a shopper only on their next cold start.
  //
  // Settings are assembled from three nodes: the world-readable `settings`, plus
  // `settingsPrivate` and `settingsBank`, which read back null for anyone who is not the
  // admin (and bank until the shopper signs in). A listener on `settings` alone would drop
  // an admin's private and bank keys out of the in-memory copy, and their next Save would
  // write those blanks back over the real ones — so all three are watched, and the merge is
  // recomputed whenever any of them fires, in the same order cloudSync merges them.
  //
  // The one-time key migration in cloudSync is deliberately not repeated here: it writes to
  // a node this effect is listening to, which would be a feedback loop.
  useEffect(()=>{
    if(!(FB_OK && FB_DB)) return;
    let alive=true, pub=null, priv=null, bank=null, last=null;
    const apply=()=>{
      // Nothing public yet — a denial or a slow first read must not wipe the cached
      // settings the store is already running on.
      if(!alive||!pub) return;
      const merged=normalizeSettings({...DEFAULT_SETTINGS,...pub,...(bank||{}),...(priv||{})});
      const json=stableJSON(merged);
      if(json===last) return;
      last=json;
      setSettings(merged);
      try{ dbSet("nemo-settings",JSON.stringify(merged)); }catch(e){}
      setSettingsReady(true);
    };
    const offs=[
      ["settings",      v=>{ pub=v;  }],
      ["settingsPrivate",v=>{ priv=v; }],
      ["settingsBank",  v=>{ bank=v; }],
    ].map(([path,assign])=>{
      const ref=FB_DB.ref(path);
      // A read denied by the rules leaves that slot null — exactly what the one-shot
      // read hands back for a non-admin, so the merge is unchanged for them.
      const cb=ref.on("value",s=>{ if(!alive) return; assign(s&&s.val()); apply(); },()=>{});
      return ()=>{ try{ ref.off("value",cb); }catch(e){} };
    });
    return ()=>{ alive=false; offs.forEach(f=>f()); };
  },[fbReady]);

  // GLOBAL: live listeners on community content (showcase + testimonials) so the admin
  // sees new submissions the instant they're posted, and customers see fresh testimonials.
  // Their FIRST settled results are part of boot readiness. A result may validly be empty;
  // readiness means the inner read completed, not that the store happens to contain a row.
  useEffect(()=>{
    let alive=true;
    let detach=()=>{};
    let showcaseSettled=false, testimonialsSettled=false;
    const settle=kind=>{
      if(!alive) return;
      if(kind==="showcase") showcaseSettled=true;
      if(kind==="testimonials") testimonialsSettled=true;
      if(showcaseSettled&&testimonialsSettled){ clearTimeout(guard); setCommunityReady(true); }
    };
    const useShowcase=sc=>{
      if(!alive) return;
      setShowcase(Array.isArray(sc)?sc:[]);
      settle("showcase");
    };
    const useTestimonials=ts=>{
      if(!alive) return;
      setTestimonials(Array.isArray(ts)?ts:[]);
      settle("testimonials");
    };
    // Failure boundary only: normal release comes from both inner reads below. This prevents
    // one blocked Firebase path from trapping the customer behind the opening forever.
    const guard=setTimeout(()=>{ if(alive) setCommunityReady(true); },8000);
    const start=async()=>{
      // Firebase loads asynchronously after React. Give it a brief chance to connect before
      // deciding the device is offline and using the local community cache.
      if(!(FB_OK&&FB_DB)) await waitForFirebase(4000);
      if(!alive) return;
      /* An OFF switch has to stop the READ, not merely the render. showcaseEnabled was checked
         in one place — TankShowcaseSection returning null — so switching the showcase off hid
         the gallery while this listener went on pulling the whole node on every visit. Entries
         carry up to three base64 photos, so that is the most expensive node in the store, and
         the owner was paying full price for a feature they had turned off. Same for
         testimonials. Waiting for settingsReady matters: the default is ON, so deciding before
         the owner's real settings arrive would attach, download, and only then detach.
         A skipped listener still settles as empty, or boot readiness waits out the 8s guard. */
      const wantShowcase = settings.showcaseEnabled!==false;
      const wantTestimonials = settings.testimonialsEnabled!==false;
      if(!(FB_OK&&FB_DB)){
        Promise.all([
          wantShowcase?loadShowcase().then(useShowcase).catch(()=>useShowcase([])):useShowcase([]),
          wantTestimonials?loadTestimonials().then(useTestimonials).catch(()=>useTestimonials([])):useTestimonials([]),
        ]);
        return;
      }
      const offs=[];
      if(wantShowcase){
        const scRef=FB_DB.ref("showcase");
        const scCb=scRef.on("value",s=>{
          if(!alive) return;
          const v=s&&s.val(); const now=Date.now();
          let arr=v?Object.values(v).filter(x=>x&&x.id):[];
          arr=arr.filter(x=>!showcaseExpired(x,now)&&!showcasePendingExpired(x,now))
            .sort((a,b)=>(b.createdAt||"").localeCompare(a.createdAt||""));
          useShowcase(arr);
          pruneShowcaseCache(arr);
        },()=>{
          loadShowcase().then(useShowcase).catch(()=>useShowcase([]));
        });
        offs.push(()=>{ try{ scRef.off("value",scCb); }catch(e){} });
      } else useShowcase([]);
      if(wantTestimonials){
        const tsRef=FB_DB.ref("testimonials");
        const tsCb=tsRef.on("value",s=>{
          if(!alive) return;
          const v=s&&s.val();
          const arr=v?Object.values(v).filter(x=>x&&x.id)
            .sort((a,b)=>(b.createdAt||"").localeCompare(a.createdAt||"")):[];
          useTestimonials(arr);
          pruneTestimonialCache(arr);
        },()=>{
          loadTestimonials().then(useTestimonials).catch(()=>useTestimonials([]));
        });
        offs.push(()=>{ try{ tsRef.off("value",tsCb); }catch(e){} });
      } else useTestimonials([]);
      detach=()=>{ offs.forEach(f=>f()); };
    };
    if(settingsReady) start();
    return()=>{ alive=false; clearTimeout(guard); detach(); };
  },[fbReady,settingsReady,settings.showcaseEnabled,settings.testimonialsEnabled]);

  // CUSTOMER: live listener on THEIR orders (reflects admin status updates instantly)
  useEffect(()=>{
    if(!user || page==="admin") return;
    const uid=userKey(user);
    if(!uid) return;
    if(FB_OK && FB_DB){
      const ref=FB_DB.ref("orders/"+uid);
      const cb=ref.on("value",snap=>{
        const v=snap.val();
        const mine=v?Object.values(v).filter(o=>o&&o.id).sort((x,y)=>(y.placedAt||"").localeCompare(x.placedAt||"")):[];
        setOrders(mine);
        try{ localStorage.setItem("nemo-orders",JSON.stringify(mine)); }catch(e){}
      },err=>{ loadUserOrders(uid).then(o=>o&&setOrders(o)); });
      return ()=>ref.off("value",cb);
    } else {
      loadUserOrders(uid).then(o=>o&&setOrders(o));
    }
  },[user,page,fbReady]);

  // WALLET: load the signed-in customer's live balance. Re-runs when their orders change.
  useEffect(()=>{
    if(loading) return;
    const uid=userKey(user);
    if(!uid){ setWalletPts(0); setWalletReady(true); return; }
    let alive=true;
    const cached=loadLoyaltyLocal(uid);
    setWalletReady(true);
    setWalletPts(cached.points||0);
    // Cached balance is already painted; Firebase now refreshes it without delaying first paint.
    const fallback=setTimeout(()=>{},0);
    // Provision the permanent referral profile now, freezing today's unlock threshold for
    // this customer so later admin changes affect only profiles created afterwards.
    if(settings.referralEnabled!==false) ensureReferralProfile(uid,settings).catch(()=>{});
    // ── Unified, live wallet: subscribe to the authoritative cloud loyalty node so any
    //    admin credit (delivery reward or shipping refund) or the customer's
    //    own redemption reflects in the UI instantly — same source of truth for every user. ──
    if(FB_OK && FB_DB){
      const ref=FB_DB.ref("loyalty/"+uid);
      const cb=ref.on("value",s=>{
        if(!alive) return;
        const v=s&&s.val();
        // Auto-expire: drop any lots whose frozen expiry has passed, then persist the cleaned wallet.
        let data=v, pts=(v&&Number(v.points))||0;
        if(v){
          const pruned=pruneExpiredLots(v, Date.now());
          if(pruned.expiredPts>0){ data=pruned.data; pts=data.points; try{ FB_DB.ref("loyalty/"+uid).set(data); }catch(e){} }
        }
        try{ localStorage.setItem("nemo-lp-"+uid, JSON.stringify(data||{points:0,history:[]})); }catch(e){}
        setWalletPts(pts);
        setWalletReady(true);
      },()=>{ /* read denied / offline → fall back to cached value */ if(alive){ setWalletPts(loadLoyaltyLocal(uid).points||0); setWalletReady(true); } });
      return ()=>{ alive=false; clearTimeout(fallback); try{ ref.off("value",cb); }catch(e){} };
    }
    // Offline fallback is already painted from cache; the bounded timer above releases boot.
    return ()=>{alive=false;clearTimeout(fallback);};
  },[loading,user,settings.loyaltyRedeemValue,settings.referralEnabled,settings.referralLifetimeSpendMin,fbReady]);

  if(loading)return(
    <div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",height:"100vh",background:C.bg,gap:16,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>
      <div style={{fontSize:52}}>🐠</div>
      <Spinner/>
      <div style={{fontSize:13,color:C.textSub}}>Loading {STORE_NAME}…</div>
    </div>
  );

  return(
    <div className="nemo-app" style={{fontFamily:"'Plus Jakarta Sans',sans-serif",background:C.bg,maxWidth:430,margin:"0 auto",position:"relative",overflow:"hidden",display:"flex",flexDirection:"column"}}>
      <style>{STYLES}</style>
      {toast&&<Toast msg={toast.msg} type={toast.type} onDone={()=>setToast(null)}/>}
      {adminExitAsk&&<AdminExitConfirm onStay={()=>setAdminExitAsk(false)} onLeave={()=>{setAdminExitAsk(false);nav("home");}}/>}
      {appExitAsk&&<AppExitConfirm onStay={()=>{appExitAskRef.current=false;setAppExitAsk(false);}} onExit={()=>{try{window.close();}catch(e){}}}/>}
      {!isAdminPage&&<WhyNemoPopup open={whyOpen} onClose={()=>setWhyOpen(false)} nav={nav}/>}
      {!isAdminPage&&<DesktopNav page={page} nav={nav} cartCount={cartCount} user={user} settings={settings} onSecretTap={handleSecretTap} walletPts={walletPts} ordersCount={priorityOrderCount}/>} 
      {/* overscrollBehavior:contain stops a flick that reaches the end of this list from
          chaining out to the document and dragging the pinned bottom nav with it. */}
      {/* The bottom nav is absolutely positioned over this container and grows by the phone's
          own gesture-bar inset, but every page's bottom padding was written as a flat 100px —
          measured against a nav without one. On a phone with a 34px inset the last thing on
          the page ends exactly level with the top of the nav, which is why the pincode checker
          had nothing below it, and why the space appeared the moment a keyboard shrank the
          viewport. Added here rather than to twenty page paddings: it is one fact about the
          device, and the pages should not each have to remember it. */}
      <div ref={scrollRef} className="nemo-main-scroll" onTouchStart={onTabTouchStart} onTouchEnd={onTabTouchEnd} style={{flex:1,overflowY:"auto",overflowX:"hidden",overscrollBehavior:"contain",paddingBottom:"env(safe-area-inset-bottom, 0px)"}}>
        <div key={page} className="page-swap">
        {page==="home"     &&<HomePage nav={nav} products={shopProducts} mediaCache={mediaCache} addToCart={addToCart} cartMap={cartMap} setCategory={setCategory} onSecretTap={handleSecretTap} setQuery={setQuery} query={query} user={user} settings={settings} settingsReady={settingsReady} favorites={favorites} onFav={toggleFav} interestedSet={interestedSet} onInterest={markInterested} orders={orders} showcase={showcase} onShowcaseSubmit={handleShowcaseSubmit} onShowcaseVote={handleShowcaseVote} totmVotes={totmVotes} tankPreviousWinners={tankPreviousWinners} restockSet={restockSet} onRestock={handleRestock} walletPts={walletPts} testimonials={testimonials} onTestimonialSubmit={handleTestimonialSubmit} hydrated={hydrated} openMenuSignal={homeMenuSignal} onMenuOpened={()=>setHomeMenuSignal(0)}/>}
        {page==="shop"     &&<ShopPage nav={nav} products={shopProducts} mediaCache={mediaCache} query={query} setQuery={setQuery} category={category} setCategory={setCategory} addToCart={addToCart} cartMap={cartMap} favorites={favorites} onFav={toggleFav} interestedSet={interestedSet} onInterest={markInterested} restockSet={restockSet} onRestock={handleRestock} hydrated={hydrated}/>}
        {page==="detail"   &&<DetailPage product={selProduct} products={shopProducts} mediaCache={mediaCache} media={selProduct?getProductMedia(selProduct,mediaCache):{images:[],video:null}} settings={settings} addToCart={addToCart} cart={cart} nav={nav} goBack={goBack} user={user} orders={orders} goAuth={()=>goAuth("detail")} onReviewsChanged={recomputeProductRating} onReviewed={markReviewed} onReviewDeleted={unmarkReviewed} autoReview={reviewIntent===selProduct?.id} reviewPreset={reviewPreset} isFav={selProduct?favorites.includes(selProduct.id):false} onFav={toggleFav} isInterested={selProduct?interestedSet.includes(selProduct.id):false} onInterest={markInterested} restockSet={restockSet} onRestock={handleRestock}/>}
        {page==="cart"     &&<CartPage cart={cart} updateQty={updateQty} total={cartTotal} nav={nav} settings={settings} products={shopProducts} mediaCache={mediaCache} orders={orders}/>}
        {page==="checkout" &&(user
          ? <CheckoutPage cart={cart} total={cartTotal} nav={nav} goBack={goBack} onOrderPlaced={placeOrder} onCancelled={cancelUnpaid} onCancelPayment={cancelPaymentAndRestoreCart} updateQty={updateQty} user={user} settings={settings} orders={orders} products={shopProducts} mediaCache={mediaCache} savedAddresses={savedAddresses} onSaveAddress={saveAddressBookEntry} onDeleteAddress={deleteAddressBookEntry}/>
          : <PhoneAuth mode="checkout" settings={settings} onSuccess={(u)=>{setUser(u);if(u.keep!==false)saveUser(u);nav("checkout");}} onBack={goBack}/>)}
        {page==="orders"   &&(user
          ? <OrderHistoryPage user={user} orders={orders} products={shopProducts} mediaCache={mediaCache} nav={nav} onLogout={handleLogout} onDeleteAccount={handleDeleteAccount} onWriteReview={startReview} reviewedSet={reviewedSet} onCancelled={cancelUnpaid} onCancelPayment={cancelPaymentAndRestoreCart} onReportDoa={reportDoa} onCancelByCustomer={cancelByCustomer} onRequestReturn={requestReturn} onSubmitReturnShipment={submitReturnShipment} addToCart={addToCart} settings={settings} favorites={favorites}/>
          : <PhoneAuth mode="signin" settings={settings} onSuccess={(u)=>{setUser(u);setReviewedSet(loadReviewedSet(userKey(u)));if(u.keep!==false)saveUser(u);nav("home");}} onBack={goBack}/>)}
        {page==="auth"     &&<PhoneAuth mode="signin" settings={settings} onSuccess={handleLogin} onBack={goBack}/>}
        {page==="request"  &&<RequestPage nav={nav} goBack={goBack} user={user} onSubmit={submitRequest}/>}
        {page==="guides"   &&<CareGuidesPage nav={nav} goBack={goBack} guides={guides} mediaCache={mediaCache}/>}
        {page==="tools"    &&<AquaToolsPage nav={nav} goBack={goBack} user={user} settings={settings}/>}
        {page==="saved"    &&<SavedPage nav={nav} products={shopProducts} mediaCache={mediaCache} favorites={favorites} addToCart={addToCart} cartMap={cartMap} onFav={toggleFav} interestedSet={interestedSet} onInterest={markInterested} user={user} restockSet={restockSet} onRestock={handleRestock}/>}
        {page==="about"    &&<AboutPage nav={nav} goBack={goBack} settings={settings}/>} 
        {page==="contact"  &&<ContactPage nav={nav} goBack={goBack} settings={settings}/>} 
        {typeof page==="string"&&page.indexOf("policy-")===0&&<PolicyPage nav={nav} goBack={goBack} settings={settings} which={page.slice(7)}/>}
        {page==="admin-login"&&<AdminLogin onSuccess={()=>nav("admin")} onBack={goBack} onAdminSignIn={adminGoogleSignIn} settings={settings}/>}
        {page==="admin"   &&<AdminHub products={products} orders={orders} requests={requests} guides={guides} settings={settings} interestCounts={interestCounts} mediaCache={mediaCache} showToast={showToast} abandonedCarts={abandonedCarts} onDismissAbandoned={dismissAbandoned} showcase={showcase} onDeleteShowcase={handleDeleteShowcase} onApproveShowcase={handleApproveShowcase} onTankMonthlyAward={handleTankMonthlyAward} totmVotes={totmVotes} tankMonthKey={activeTankMonth} testimonials={testimonials} onDeleteTestimonial={handleDeleteTestimonial}
          onSaveProd={saveProdHandler} onDeleteProd={deleteProdHandler} onUpdateOrder={updateOrderHandler} onDeleteOrder={deleteOrderHandler} onCleanupOrders={cleanupOldOrders} onResetOrderData={resetOrderDataHandler} onBackfillThumbs={backfillThumbs} onDeleteRequest={deleteRequest} onPurgeUser={purgeUserForAdmin} onSaveGuide={saveGuideHandler} onDeleteGuide={deleteGuideHandler} onDeleteGuides={deleteGuidesHandler} onSaveSettings={saveSettingsHandler} onReviewsChanged={recomputeProductRating} onBack={()=>nav("home")} onAdminSignIn={adminGoogleSignIn} backRef={adminBackRef}/>}
        </div>
      </div>
      {/* Floating cart bar — Zepto-style: free-delivery nudge + cart chip, opens the mini-cart */}
      {!isAdminPage && cart.length>0 && !["cart","checkout","auth"].includes(page) && (()=>{
        const thr=Number(settings.freeDeliveryThreshold||0);
        const left=thr>0?Math.max(0,thr-cartTotal):0;
        // Nearest coupon discount to unlock. `orders` is what tells usableCoupons whether a
        // first-order coupon still applies — without it this pill dangled the welcome offer at
        // customers who had already used it.
        /* Only a threshold still AHEAD belongs on this pill. nextDiscountNudge also reports a
           cleared one (need: 0), which the cart uses for its "you've unlocked it" state — left
           unfiltered here it would read "Add \u20b90 more to get 10% off". */
        const nudge=nextDiscountNudge(cartTotal,settings,orders);
        const dc=(nudge&&!nudge.unlocked&&nudge.need>0)?nudge:null;
        // Show whichever reward needs the least extra spend (Zepto-style).
        const showFree=left>0 && (!dc || left<=dc.need);
        return(
          <button className="press floating-cart-bar" onClick={()=>setMiniOpen(true)}
            style={{position:"absolute",left:"50%",transform:"translateX(-50%)",bottom:"calc(76px + env(safe-area-inset-bottom))",zIndex:90,width:"calc(100% - 28px)",maxWidth:440,background:"#0f172a",color:"white",border:"none",borderRadius:99,padding:"7px 8px 7px 18px",display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,boxShadow:"0 14px 34px rgba(15,23,42,.35)",fontFamily:"'Plus Jakarta Sans',sans-serif",cursor:"pointer"}}>
            <span style={{fontSize:12,fontWeight:700,textAlign:"left",lineHeight:1.3,minWidth:0,flex:1,overflow:"visible",textOverflow:"clip",whiteSpace:"normal"}}>
              {showFree?<>🚚 Add <b style={{color:"#fda4af"}}>₹{left}</b> more for free delivery</>
               :dc?<>🏷️ Add <b style={{color:"#fda4af"}}>₹{dc.need}</b> more to get <b>{dc.off}</b></>
               :thr>0&&cartTotal>=thr?<>🎉 Free delivery unlocked!</>
               :<>🛒 {cartCount} item{cartCount!==1?"s":""} in your cart</>}
            </span>
            <span style={{flexShrink:0,display:"inline-flex",alignItems:"center",gap:7,background:C.coral,borderRadius:99,padding:"9px 16px",fontSize:12,fontWeight:800,boxShadow:"0 6px 16px rgba(244,63,94,.4)"}}>
              🛒 Cart · {cartCount}<span style={{opacity:.9}}>₹{cartTotal}</span>
            </span>
          </button>
        );
      })()}
      {!isAdminPage&&<BottomNav page={page} nav={nav} cartCount={cartCount} ordersCount={priorityOrderCount}/>} 
      {!isAdminPage&&<MiniCart open={miniOpen} onClose={()=>setMiniOpen(false)} cart={cart} total={cartTotal} updateQty={updateQty} nav={nav} settings={settings} products={shopProducts} mediaCache={mediaCache}/>}
    </div>
  );
}
